/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20151006-4","meetingId":"h27-c-settlement","date":"2015年10月6日","dateIso":"2015-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山委員","kind":"質問","question":"おはようあります。私からは、１２９ページ、児童相談事業、１３５ページ、すまいるスクール運営費、そして時間があれば、１２３ページの認知症高齢者の支援とケアの充実、１３４ページのすくすく赤ちゃん訪問事業についてお伺いいたします。児童相談事業についてです。","respondent":"伊崎子ども育成課長","answer":"児童虐待ゼロへの取り組みです。品川区では、要保護児童対策地域協議会というネットワークをつくりまして、地域の方との連携をとりながら、虐待のまず未然防止、早期発見、それから早期対応に努めておるところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"今、ネットワークというキーワードをいただきました。品川区における子ども虐待防止のためのネットワークによる支援体制の現状をもう少し詳しく教えてください。横のつながり、相談の窓口がたくさんあります。そうした横の連携をどのように行っていらっしゃるのか、お願いいたします。","respondent":"伊崎子ども育成課長","answer":"区の機関としましては、保健センターと子ども育成課、あと教育委員会が特に取り組みを進めておりまして、それぞれ虐待または疑いを発見したときには、お互いに連絡をし合いまして、それぞれの役割の中で対応を進めるということをとっております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"都道府県市町村の役割について、児童福祉法第１０条、市町村の業務の一部抜粋になるのですけれども、「児童及び妊産婦の福祉に関し、家庭その他からの相談に応じ、必要な調査及び指導を行うこと並びにこれらに付随する業務を行うこと」、また、「専門的な知識及び技術を必要とするものについては、児童相談所の技術的援助及び助言を求めなければならない」というふうにあります。","respondent":"伊崎子ども育成課長","answer":"今、虐待の件数が増えているということがございまして、やはり児童相談所も迅速な対応がなかなか難しいということは１つ課題としてあると考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"区側の作業として、移管モデルの具体化の検討等を早急に進めていただきたいということを要望します。施設においても学習の時間が設けられておりますが、品川区は独自の教育を行っているということもありまして、命の安全が確認できまして、そして家庭に戻ったときにスムーズに学校生活に戻っていくことは、子どもの健やかな成長にとって、とても重要となります。そこで２点、お聞きいたします。","respondent":"伊崎子ども育成課長","answer":"他区との比較ですけれども、全体の経費につきましては、非常に状況がばらばらでございまして、全体経費に占める保護者の負担という数字は持ち合わせてはおりませんが、保護者負担に着目をいたしますと、他区の場合は、放課後健全育成事業の負担金としまして。","voiceIndex":12,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"ただいま全体の負担額と財源の投入額、そしてほかの２２区との比較について教えていただきましたけれども、高いところですと８,０００円ということでお聞きしております。区民の声の中でも、有料でもいいので、ぜひ時間延長していただきたい、そういった声は多数ございました。こちらの学校支援ボランティアのほうは、またすまいるスクールのほうとは違ってくるのでしょうか、お願いいたします。","respondent":"伊崎子ども育成課長、村尾教育総合支援センター長","answer":"すまいるスクールの時間延長の見直しにつきましては、条例の施行が来年の４月ですので、４月の春休みからと考えているところです。この学習支援ボランティアという部分ですけれども、これは、各学校、放課後、また土曜日に、児童生徒への学習指導を行うという学力向上プランの１つの事業です。","voiceIndex":14,"id":"exchange-005"},{"speaker":"横山委員","kind":"確認","question":"今、学校支援ボランティアの内容の資料を拝見させていただいているのですけれども、そちらの制度を使ってすまいるの地域の学校支援ボランティアの方がいらしているというわけでは、今はないということでよろしいでしょうか。確認をお願いいたします。","respondent":"伊崎子ども育成課長","answer":"委員ご指摘のとおりです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"横山委員","kind":"質問","question":"こちらの件については、また後日、質問をさせていただけたらと考えています。では、次、すくすく赤ちゃん訪問についてお伺いいたします。こちら、ただいまのすくすく赤ちゃん訪問の現状の内容と、助産師の人数等について教えてください。","respondent":"伊崎子ども育成課長、太田品川保健センター所長","answer":"新生児を抱えた子育て家庭を孤立させないように、なるべく生後１カ月のうちに、まず新生児宅に助産師が訪問し、助産師が連絡のとれないケースについて、子ども育成課のほうに連絡が来まして、児童センターの職員が訪問しているです。助産師の人数ですが、現在、１８名の方が登録されております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問","question":"１８名の助産師がいらっしゃるということでお聞きしました。現在、助産師の方の声なのですけれども、ご相談は多様化しておりまして、そういった相談をきちんと消化して対応していくには、助産師のスキル、特に、産後すぐですとか、そういった不安な時期、母乳のケアだったり、そういったところは助産師のお力を、これから品川区で必要となってくるというところだと考えています。","respondent":"太田品川保健センター所長、伊崎子ども育成課長","answer":"母乳相談等、産後ケアの部分については、非常に助産師の方の専門的な知識が必要となっているところですので、その部分については、今後、ご活躍いただけると考えています。小中高生と赤ちゃんふれあい事業につきましても、現在、児童センター１４館でやっておりますが、学校とのカリキュラムの関係があり、なかなか増やすのも難しいという状況にはあります。","voiceIndex":22,"id":"exchange-008"},{"speaker":"横山委員","kind":"確認","question":"最後に、簡単な確認だけになってしまうのですけれども、認知症高齢者の支援とケアの充実の部分で１点だけお聞きしたいと思います。認知症をめぐっての会議体、さまざまなものを行っていただいているかと思います。こちら、１つの会議、さまざまな会議の中での横の連携といいますか、どういった形で区としての意見をまとめたり、そして推進していくのかというところだけ簡単にお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"区では、一昨年ですけれども、地域医療連携会議を立ち上げました。そこがまず一番の中心になっていきます。医療連携検討部会がその下の部会ということになっており、その組織を使いながら連携を図っているところです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"私から、１２１ページの市民後見人養成、１２４ページ、ふれあいステーションについてお伺いいたします。質問をいたします。市民後見人は、社会福祉協議会が開催する市民後見人養成講座の基礎講座、実務講座をあわせて６６時間受講して資格が得られるものですが、これまで何人修了したのか、人数を教えていただきたいと思います。そして、その中で実際に活動されている方は何名いらっしゃいますでしょうか。","respondent":"大串福祉計画課長","answer":"そうした方のセーフティーネットということで、この後見人制度、私ども品川区では社会福祉協議会の成年後見センターと連携しながら事業を進めているところですので、今後ともこういった市民講座の充実を図りながら、あるいはこの成年後見制度への理解。","voiceIndex":28,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後、本当に認知症になられる高齢者が増えてくると思うのですけれども、成年後見人制度を必要とする人が急増することが見込まれている中で、区として今後必要とされる潜在的な利用者を１万人と推測されているようなのですが、今後どれくらい市民後見人が必要と見込んでいて、その養成の取り組みをどのように進めていこうとお考えか、教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"ひるがえって、その方に対して後見人の数がどれぐらい必要かといったところ、なかなかこれ、数を出すのは難しいところだというふうには思っておりますけれども、少なくとも今の数だけではまかない切れないのではないかというふうに考えておりますので。","voiceIndex":30,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後、本当に必要とされる大事な後見人かと思いますので、拡大をぜひよろしくお願いいたします。次の質問に移ります。ふれあいステーション事業についてお伺いいたします。本年度も２地区拡大をされまして４地区になりました。今のこの現状と、４地区開設をされての効果をお伺いさせていただきたいと思います。","respondent":"大串福祉計画課長","answer":"当初は２カ所、品川第２地区、荏原第２地区というところで始めたものです。若干それまでについては試行という形で進めさせていただきましたけれども、本年、平成２７年８月から本格実施ということで、新たに大井第２地区、大崎第２地区でこのステーションを開設したです。","voiceIndex":34,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"地域の民生委員、また町会長がご相談を受けたときに、地域センターに相談に行けばいいというところができたということは、大変に心強いかと思います。例えば、今後、地域のニーズによって、まとめて工夫が必要かと思うのですが、ここの地域はこの地域センターということではなく、何か品川区全体に大きく拡大できる工夫が何かされているかと思うのですけれども、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"はそういった形で基盤を整えていきたいというふうに考えておりますし、未設置のところにつきましては、私ども福祉部あるいは社会福祉協議会、こういったところでの相談等々を今まで以上に対応させていただきながら。","voiceIndex":36,"id":"exchange-013","title":"町会・自治会支援"},{"speaker":"中塚委員","kind":"質問","question":"成果報告書１２２ページの障害者災害対策支援事業にかかわって、福祉避難所について伺いたいと思います。昨今、水害、地震、また土砂災害と全国各地で災害が発生し、避難所の姿がテレビで報道されるたびに、これが自分たちだったらどうなるのかと、そういった不安の声を障害がある家族の方や当事者からたくさん伺います。","respondent":"中山障害者福祉課長","answer":"は自宅を安全安心な場所として整えること、そういったことをご紹介するとともに、あるいは、避難場所への経路の確認、地域での防災訓練の参加、そういったところから地道に進めていくような、ご相談の中で一緒にさせていただいているところです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"地道にというか、少しずつさまざまな事業も始まっていると思いますけれども、当事者の方に伺うと、例えば名簿登録し、防災訓練のときに声をかけてもらったが、実際では移動や避難生活は周りの方に迷惑もかけるかもしれないから難しいのではないかという、こういった不安の声や、あと、知的障害の息子が作業所で仕事をしているときに震災が発生、このときの施設や家族はどう行動すべきなのか、３・１１以来。","respondent":"鈴木防災課長、中山障害者福祉課長","answer":"１点目の福祉避難所におけるマニュアル等の整備ですが、福祉避難所につきましては、区内の５福祉法人の皆さまとご相談をしながら、各施設の現状にあわせた対応、また、その具体的なマニュアルということについて相談をしている段階です。障害者のほうでも、２つほど福祉避難所があります。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"緊急対策の備蓄品ですけれども、通常の備蓄は福祉避難所にも備蓄されたということは前進なのですけれども、段ボールの間仕切りの検討が先日ありましたけれども、段ボールベッドもぜひ追加をしていただきたいと思うのですけれども、この追加の備蓄について、現状どうなのか、施設でスペースがなければ、また別の対応を考えていらっしゃるのか、ぜひ段ボールベッドも必要ではないかと思うのですけれども。","respondent":"中山障害者福祉課長","answer":"今現在、それぞれの避難場所の備蓄品の準備、それから、そこでまずは開設訓練をやる必要があるかと考えています。モデル的に実施する中で、どういった開設ができるかを含めて実地しながら、そのマニュアルに活かしていくような形がとれたらと考えています。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚委員","kind":"確認","question":"それと、特養ホームが当初に開設されたり、今後、平塚や旧みやこ荘と開設されていきますけれども、新しい特養ホームの開設の時期に合わせてこういう開設や運営のマニュアルというものもつくっていくのか、施設をつくるときは１つのタイミングだと思うのですけれども、そこについてもお考えを伺いたいと思います。","respondent":"中山障害者福祉課長、鈴木防災課長、大串福祉計画課長","answer":"そこの福祉避難所を開設するに当たっては、まずそちらの事業者の協力ということも必要になってまいりますので。現在は、そのほか、津波、内水被害、川の氾濫等々、災害の種類ごとに同様に基準と対応を今、検討していますので、それに合わせて災害の種類。後段のほうのこれからの新規施設といったところですけれども、そちらの運営事業者である法人等とマニュアルについての話し合いもしています。","voiceIndex":46,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"施設ごとにするのかどうかということと、そうした計画を当事者に伝えていくということが大事だと思うのですけれども、以前も伺ったときに「しっかり伝えていきます」などとお話がありましたけれども、どのように伝えているのかということと、現状、どういう準備をしたらいいのかという、現状について、ぜひ障害がある方や家族に向けた全体の説明会や障害別ごとの説明会、また、施設ごとの説明会。","respondent":"中山障害者福祉課長","answer":"そういった中で、それぞれ障害の種別によって心配なこと、気になること、どうしたらいいのだろうと悩んでいらっしゃることが違いますので、それぞれの対象者ごとに、まずはその７団体の会を中心に話を進めていければというふうに考えております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"７団体の方々や当事者の参加の中でつくっていくことは大事だと思いますけれども、ぜひ施設の利用者や家族に説明会、施設ごとなのか、障害別なのか、全体に共通する部分と障害によって変わる部分がありますけれども、ぜひ説明会の開催をお願いしたいのと、必要な資料、パンフレットをつくっていただきたいと思うのですけれども、その点改めて伺いたいと思います。","respondent":"中山障害者福祉課長、鈴木防災課長","answer":"７団体だけではなく、施設ごとの防災の説明会をというお話でございました。各施設では、防災訓練も実施しておりますし、それぞれ保護者会みたいなこともあります。全体計画についてのお尋ねにお答えをいたします。平成２５年６月の災害対策基本法の改正に基づきまして、ただいま避難行動要支援者の避難行動支援に関する取組指針に基づいた全体計画を作成しています。","voiceIndex":52,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"私からは、成果報告書の１２０ページのホームレス対策事業について、続きまして、１２３ページの認知症高齢者の支援とケアの充実について、１２５ページの障害者虐待防止対策について伺いたいと思います。ホームレス対策事業について伺いたいと思います。そこで改めて、この事業内容が変わっているのかいないのか、また、その内容について伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"予算的には、そういうことを継続してやっております関係で、ほとんど変更がないというような状況です。","voiceIndex":56,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"内容は変わっていないけれども、年々減少しているということはとてもいいことだと思います。今現在、区が把握されている路上生活者の人数、また、実績等がわかりましたら伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"ただ、全区域一斉に調査というわけにはいきませんし、実態として移動系の方が多いという状況になってきますので、本当の意味での実数というところでは難しい部分があるのかと考えています。","voiceIndex":58,"id":"exchange-021","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"今現在、巡回されている方がいらっしゃると思うのですが、例えばペアでホームレスの方を探しているのか、それとも手分けしてやっているのか、例えば年に何回かやって、今だったら、今日もとても寒いですけれども、そういった巡回の時期というのはあるのでしょうか。それについて伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"これは委託してやっているわけなのですけれども、２名でペアを組んでいただきまして、「今日はこの公園です」とかというようなリストをもとに、満遍なく回るようにしておるところです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした中で、巡回されている方がホームレスの方に対して、いろいろ言葉を、そして助言とかされているということをおっしゃっておられたのですが、そうした中で、例えばホームレスの方が相談員に対して、例を挙げていただきたいのですけれども、こういうことでホームレスになってしまったというような主な原因が、わかりましたら伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"病気を機に仕事を失って、療養生活をしている中で、そういうふうな社会に溶け込めないような状況になって、社会的に孤立をして路上生活に陥っているのではないか、そんなような、直接的な話はなかなか聞けないことですけれども、そのようなことかと思っています。","voiceIndex":62,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"以前、鈴木委員もお話しされていたと思うのですが、ホームレスの、路上生活者の支援について、大きく２つ課題があると言われておりました。１つは、話を聞いていただけないということと、２つ目は、一旦解消したけれども、時間が経過するとまた戻ってきてしまうというお話を伺ったときに、まず、話を聞いていただけないという理由は何なのか伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"私も一度巡回にお供したことがあるわけなのですけれども、話しかけても、「放っておいてくれ、俺のことは構うな」というようなことで、こちらからいろいろ支援のことをお伝えしようとしているわけなのですけれども。","voiceIndex":64,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"ぜひ今後も粘り強くゼロを目指してよろしくお願いいたします。それに関連してなのですけれども、品川寮が以前あったと思うのですが、今現在の自立支援センターの品川寮というのは、今現在、どのようになっているのか伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"自立支援センターということでの品川寮ですけれども、こちらにつきましては、平成２６年３月２３日に一旦閉鎖をしまして、それ以降、平成２６年３月２４日以降は、目黒寮ということで開設して、機能は同じですけれども、ブロック内で５年ごとにやっているということで。","voiceIndex":66,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"その寮に関してなのですけれども、例えば５年ごとに順次交替制で行うということになっておりますが、２０年後にまた品川区に戻ってくるわけであります。今後どのような対応をしていくのか伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"ブロック内で５年ごとに開設ということで、今、計画を進めているところですけれども、今、委員おっしゃったとおり、次回の品川は、２０年後というか１９年後ということになってくるかと思います。","voiceIndex":68,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"初めに、１２０ページの成年後見制度についてお伺いしますが、この制度、私も評価をしておりますが、改めてお伺いしますけれども、品川区の成年後見人で事故を起こしたこととか、あるいは問題のある事例はなかったのでしょうか。","respondent":"大串福祉計画課長","answer":"先ほどもご答弁しましたように、特に事故事件といったことでの報告はいただいてはおりません。","voiceIndex":71,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"すばらしいですね。弁護士が後見人で。品川は起きていない。先ほど言った熱意、モラル、そういうことがあると思うのですけれども、そういうことで、品川区においては、そういうことができない、もちろんやってくださっている方のお気持ちなのですけれども、そういうシステムというのは構築されているのでしょうか。","respondent":"大串福祉計画課長","answer":"委員のほうで出していただいた事例、弁護士云々といったところですけれども、先ほど申し上げましたように、我々の今やっている成年後見制度の中においては、そういった形で何か事件事故といったものは起きていないというふうに報告は受けております。","voiceIndex":73,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"次は、お金の流れ、決算ですからお金の流れについてお伺いしたいと思うのですけれども、１２１ページの社会福祉協議会助成金なのですけれども、都の支出金の返還は、区ならばわかるのですけれども、なぜ社協の返還金を区が負担しなければならないのか教えていただきたいのと、同じく社協の団体助成なのですけれども、こういう形で見ると、社会福祉協議会の団体助成を区が負担していることになりますが。","respondent":"中山障害者福祉課長、廣田子ども家庭支援課長","answer":"このふれあい作業所に対して区の助成金は、人件費助成のところと、それから今回、ふれあい作業所が新しく建物を建て直しをしました。その補助金が区からと都からの包括補助ということで行っているものだと思います。この団体助成のうち１００万円につきましては、母子父子寡婦の関係の事業ということで、社会福祉協議会に子ども家庭支援課が予算を計上していっているものが一部あります。","voiceIndex":75,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"よくわかりました。次に行きたいと思いますけれども、次が、１２９ページのひとり親家庭支援事業についてお伺いしたいと思うのですけれども、この事業に関しては、私自身もすごく強力に応援していきたい事業の１つです。私もひとり親で育ちました。ですから、改めてここもお伺いするのですけれども、充実強化をしていただいて、その中でさまざまな事業展開をしています。","respondent":"廣田子ども家庭支援課長","answer":"ひとり親家庭の支援に対する今後の課題ということで、区としての課題といたしましては、先ごろ貧困の対策の大綱が出てありますが、ひとり親の家庭につきましては、大学の進学率が一般の方よりも低い、また、ひとり親の親御さんの正規の就業率が低いということがありますので。","voiceIndex":78,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろな事業部があって、事業部の名前は変わっていくのですけれども、その中で「未来」とついているではないですか。「未来」とつくということは、次世代を担う子どもたちをどう支援していくか、それだと私は思っているのです。次に、児相についてお伺いしたいのですけれども、委員長、すみません、ページがわからなくなってしまったのですけれども、児相についてお伺いしてしまっていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"すみません。児相なのですけれども、児童虐待について、改めて児童虐待の対応件数と、それに対する区の体制を教えていただけますか。","respondent":"伊崎子ども育成課長","answer":"平成２６年度に新規で受理をしました児童虐待の相談件数は２１７件です。そのうち７９件が調査の結果、非該当でございましたので、虐待として対応しましたのが１３８件です。","voiceIndex":84,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"それだけの数字が上がっているのですね。品川区と児童相談所のいわば二元体制という形で今なっていると思うのですけれども、その弊害は何か、実例があったら教えてください。それと、児童相談所の移管について、何回もお伺いしてきましたけれども、やはり全然進まないではないですか。進みませんよね、これだけ要望しているのに。その辺についてもどう考えているか教えていただけますか。","respondent":"伊崎子ども育成課長","answer":"品川区と児童相談所、児童相談の対応ということでは二重の組織となっております。","voiceIndex":86,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"私からは、成果報告書１２５ページ、３目障害者福祉費の自立支援サービス、介護人派遣事業の同行援護について、それから１２８ページ、４目重症心身障害者通所施設運営費についてお伺いいたします。時間があれば、１２０ページの社会福祉総務費から各種資金貸付事務の女性福祉資金についても伺いたいと思います。最初に、障害者福祉費の自立支援サービスの同行援護についてです。","respondent":"中山障害者福祉課長","answer":"同行援護の支給の決定につきましては、その方の日常生活の中でどういった外出の支援が必要か、そういったことを聞き取り調査する中で支給決定をさせていただいているところです。","voiceIndex":89,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"例えば、予算も限りがあることであれば、どれくらいまでを目安にする、そういうようなことはないのでしょうか。","respondent":"中山障害者福祉課長","answer":"具体的に言いますと、例えば、今現在で一番少ない時間数の方は２時間です。だけれども、逆に最高支給時間の方は７５時間ということで、これはその方の生活に即した支給をさせていただいているというものです。","voiceIndex":91,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。サービスを受けている人同士で、時間数の違いに納得がいかないケースもあるというご意見が生活者ネットワークに寄せられております。当事者へは、支給決定についての考え方をどのように説明していらっしゃるのでしょうか。","respondent":"中山障害者福祉課長","answer":"こちらのサービスの中身が、やはりどれぐらいの移動が必要かということになってきますので、そういった基準の中で支給をしますという、ご相談の中で話もした上で必要な量を決めしています。","voiceIndex":93,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"例えば、これぐらい時間が必要だという要請に対して、家族がいることを理由に支給を断られたというお話も聞いておりますが、そういうことがあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"ご家族がいらっしゃるからということで一律に同行援護を認めないとか、そういうものではありません。ただし、ご家族の役割として、一緒に外出するということも当然あるはずですので、そういったお話を１つ１つお聞きする中で決めしています。","voiceIndex":95,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。ただ、誤解を招くような表現がもしかするとあったかもしれないと思いますので、なるべくその辺は誤解がないようにしていただきたいと思います。勤労は憲法２７条に定められた権利であり、また、国民の義務でもあります。納税の義務も憲法３０条に定められ義務ですので、これらの義務を果たして権利を行使するために税金を使うというのは妥当ではないかと考えるのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"同行援護については、国の法令上の中で定められているものですので、国のほうでもそういったことは多分税金の使い方としてどういったことが適切なのか、議論の中で、今のところ認めることはふさわしくないだろうということで結論づけられているものと考えております。","voiceIndex":97,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"それは多分、障害者総合支援法のことだと思います。その法のことは承知をしております。ただ、障害児の通学支援についても、障害者総合支援法の中で使えないとされているものを、品川区の場合は独自の制度として認めて、要綱の中でそういう扱いになっています。視覚障害者の同行援護についても同様な事を区独自でするということは可能なのではないかと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"実はとても似たサービスではあるのですが、同行援護は法内サービスです。一方、移動支援は地域生活支援事業の位置づけになっておりまして、それは各地域の実情に合わせて柔軟な対応がとれるということになっております。","voiceIndex":99,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは本日は要望にとどめたいと思います。次に、重症心身障害者通所施設運営費について伺います。この通称ピッコロについては、在宅で重症心身障害者の子育てをしている保護者の方のレスパイト事業にも取り組むということで、障害者の家族の方から大変歓迎されている事業と理解しております。２０１４年度のレスパイト事業の利用実績について伺います。","respondent":"中山障害者福祉課長","answer":"平成２６年度のいわゆるレスパイト事業の利用者数ですが、２人ということになっております。","voiceIndex":101,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"大変歓迎をされて始まったということで、２人の利用というのはちょっと意外だというふうに思うのですけれども、利用が少ない要因をどのように考えられているでしょうか。","respondent":"中山障害者福祉課長","answer":"そうなってくると、長期のお休み、例えば夏休み、冬休み、春休み、こういったところでの利用ということになりますが、１日１名までというところと、それから、レスパイトについては送迎はできない状況にありますので、そういったこと。","voiceIndex":103,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。そのように分析されているということなのですけれども、一方で、利用したいのだけれども、申し込んでもなかなか受け入れてもらえないというご意見も生活者ネットワークには届いておりますが、区へはこのようなお声は届いていないのでしょうか。","respondent":"中山障害者福祉課長","answer":"そういった説明と同時に、あとはピッコロの体制上、比較的受入れがしやすい曜日の設定とか、そういったものも利用者には伝えながらご利用いただきたいということでお話は進めているところです。","voiceIndex":105,"id":"exchange-042"},{"speaker":"吉田委員","kind":"確認","question":"状況はわかりました。ただ、情報公開で委託契約書も確認させていただきましたが、通所事業とレスパイト事業を丸めての３,２１０万円の契約ということになっております。委託料のほとんどは人件費と伺いました。通所事業とレスパイト事業それぞれどのような人件費を積み上げて、その両方の事業を委託するということでこういう金額になったのか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ピッコロについて言いますと、看護職が２人、それから生活支援員が１人、保育士が１人、それからＰＴが１人というような体制と、それから、直営ですので区から管理者という形で、都合６名で体制を組んでいるところです。そのうちの５名の委託料ということで支払いをしています。","voiceIndex":107,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"隙間があくだろうということを想定していたけれども、実際にはなかなか厳しいということなのでしょうか。あわせて、レスパイト事業実施要綱７条で、利用定員として１日１名をうたっているわけですから、やはりこれを根拠に委託元の区としては、レスパイト事業を進めるということを考えるべきではないでしょうか。２点についてお伺いします。","respondent":"中山障害者福祉課長","answer":"ただし、レスパイトが必要なことは確かなので、こういう場所に来てもらうだけではなく、今後、１つの方策としては、訪問型のレスパイト事業みたいなものも検討する必要はあるのではないかと考えているところです。","voiceIndex":109,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどご答弁にもちょっとありましたけれども、送迎が必要なことがネックという声も聞きましたが、送迎ができるように見直すということで利用が進むということはないのでしょうか。車両はあるわけですから、例えば、予約のあるときだけ運転士の手配をするなど、何か工夫はできないのでしょうか。お考えを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"これは、ここを利用される方の医療依存度が高く、急変する可能性があるということで、いつでもそのために救急車を呼ぶわけではなく体制がとれるという形で準備しておりますので、例えばレスパイトで予約を受けて、その間に何かがあるとということで。","voiceIndex":111,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。時間がありそうなので、各種資金貸付事務の女性福祉資金について、数字の確認になるかと思いますが、伺いたいと思います。この６件という数は、決算書のほうで見ますと、１２０ページの６件で同じなのですけれども、事務事業概要では実績が３８５万２,０００円、決算書では、同じ６件なのですが１,０９２万３,０００円ということで、この数字について説明いただけますか。","respondent":"廣田子ども家庭支援課長","answer":"平成２６年１０月から女性福祉資金のシステムにつきましては、東京都の制度であります母子・父子福祉資金と一緒のシステムを使っておりまして、ここには都からシステム改修費を、父子も平成２６年１０月から入りましたので、その分の補助金をいただいているのですが。","voiceIndex":113,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。そうしたら、貸付そのものについては就学資金で３８５万２,０００円ということで了解です。そうしましたら、この貸付の実績については、当初の見込みより上回ったのでしょうか。それとも見込みどおりくらいなのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"貸付については見込みどおりです。","voiceIndex":115,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"了解いたしました。今、質問したのは、ぜひこういうところへの貸付というのは、なかなか一般の金融機関では難しいですので、ぜひ進めて多くの方が利用して、しかもきちんと仕事に結びつくようなフォローまでなされるようなという姿勢で質問をいたしました。機会があれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、成果報告書１３０ページの子ども・子育て会議等、１３１ページの保育従事職員資格取得支援事業、１３４ページの児童センター事業に関連して質問いたします。子ども・子育て会議等から、品川区の子ども・子育て会議についてお伺いいたします。平成２５年８月２９日に第１回会議が開催されてから、この９月３０日まで通算９回開かれ、子ども・子育て支援事業計画が審議されているようです。","respondent":"伊崎子ども育成課長","answer":"品川区では、この子ども・子育て会議を設置し、その中で子ども・子育て支援事業計画を同じく次世代育成推進対策支援計画とあわせて、子ども・子育て計画という形で検討し、設置をしてまいりました。","voiceIndex":121,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"詳細なご説明をありがとうございました。お話をお聞きしたいのですが、保育の質とか、保育の量とか数値についての審議が多いように感じられました。保育の量の拡大も焦眉の課題ですが、各保育施設でも、保育の高いレベルで標準化する質の問題も重要と考えます。子ども・子育て会議では、保育の質に関してはどのように審議され、今後、どのように方向性を考えていらっしゃるのか、お考えをお示しください。","respondent":"竹田保育課長","answer":"子ども・子育て会議ですが、今まではどうしても数字的な議題が中心になってまいりましたが、今後は十分質の内容についても、品川区全体の保育の向上に向けて、ご意見を賜りながら向上に向けて進めてまいりたいと考えております。","voiceIndex":123,"id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子ども・子育て会議の今後の審議の内容を期待し、次の質問に移りたいと思います。第２に、保育従事職員資格取得支援事業から、保育所の人材確保について、一般質問に引き続きお尋ねいたします。保育従事職員資格取得支援事業で保育士資格を取得した方がいらっしゃるのか、また、セカンドチャレンジ保育士支援事業により、保育所に入所された方がいらっしゃるのか、その実績についてお尋ねいたします。","respondent":"竹田保育課長","answer":"残念ながら昨年度は合格に至る方はいらっしゃいませんでした。それから、セカンドチャレンジ保育士支援事業ですが、こちらは現在、保育職に従事していない資格所持者に対して、セミナー等を実施して保育職への従事を支援する事業です。","voiceIndex":125,"id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問","question":"なかなか厳しい状況であることがよく理解されました。それとともに、保育士の質も問題だと考えます。保育士の質を向上させるために、品川区も講演会等いろいろと積極的に、今、課長からお話があったように、会議等も、講習会等も行われているようですが、現在、品川区では、区立認可保育園以外の保育所のスタッフを対象とした講習会等は行われているのでしょうか、質問いたします。","respondent":"竹田保育課長","answer":"品川区で保育の職につく方には、広くお声かけをさせていただいて、区が開催する研修にも私立園等の方にご参加いただけるように広く門戸を開けてお声かけをしています。さまざまな形を通じまして、品川区全体の保育の質の向上に向けて頑張ってまいりたいと考えております。","voiceIndex":127,"id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"提案","question":"さきの一般質問で、区立認可保育園以外の保育所のスタッフに、区の無料講習会の参加を促す方法として、区指定の講習会、研修会などに参加した保育士には、区からポイントを付与し、ポイントが集まれば、品川区認定保育士の資格を与えることを提案しました。品川区は、各保育所の保育士の質を高めるために、この提案も含めてどのような取り組みをお考えになっているのか、ご説明をお願いいたします。","respondent":"竹田保育課長","answer":"講習会参加のポイント制の導入、あるいは品川区認定保育士の設立というお問い合わせですが、先ほども申し上げましたが、区の主催する講習会等にお声かけをすると同時に、私立の園長会のご意見も聞きながら、区全体のレベルアップに向けて支援していきたいと考えております。","voiceIndex":129,"id":"exchange-053","title":"議員研修会の内容と所要時間"},{"speaker":"鈴木（博）委員","kind":"提案","question":"今後もご努力をお願いいたします。今後も高止まりが続く保育士需要、日本各地で保育士の奪い合いが続く状況の中で、若い良質の保育士を確保するために、介護専門学校に保育専門学校を併設開校することを一般質問で提案させていただきました。国の施策を先取りすることでもあり、福祉子育ての先進国品川ならではの取り組みと評価されると考えますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"フィンランドと日本の事情も異なるということも聞いておりますので、今後の乳幼児人口や保育の需要の動向を見極めながら、ご提案の内容は研究させていただきたいと考えております。","voiceIndex":131,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問","question":"児童センター事業に関連してお伺いいたします。私のところの患者も皆そうおっしゃいます。離乳食教室で実際に料理をつくって離乳食づくりをマスターするように、病気の子どものケアを練習しておけば、子どもが実際に病気になったとき、正確に冷静に対処できるのではないでしょうか。これは極めて有意義な事業だと考えますが、区のお考えはいかがでしょうか。","respondent":"伊崎子ども育成課長、太田品川保健センター所長","answer":"児童センターで行っております子育て支援事業の中に、助産師にベビーマッサージに来ていただいている事業があります。こういったものの中でも医療ケアについて取り入れることができるかどうか検討していきたいと考えております。委員ご提案の実地研修ということになりますと、病児の状態とか実地というのは難しいかと思いますので、講義形式で小児科医の協力を得てやりたいと思います。","voiceIndex":133,"id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。１２０ページ、民生費全般と、２０７ページの介護保険特別会計をあわせての質問と、１２９ページ、児童福祉費、１３４ページ、父親のための親育ちワークショップ、時間があれば、そのほか伺いたいと思います。最初に、民生費と介護保険に関連してということでお尋ねします。いわゆるダブルケアについて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"子育てと介護のダブルになっている方のケアについてですけれども、やはり大事なことは、まず入口である相談支援の部分と、あともう１つが、子どもの部分と高齢者の部分での連携というところが一番大事なことだと考えています。","voiceIndex":138,"id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな制度、仕組みがあると思いますが、その現実の課題に対して、一番最前線の行政として、困っている方、努力されている方にどう対応していくのか、これをしっかりと実態把握等、まずはそうした世帯の確認等をやっていただきながら、また、今ご答弁いただいたことも含めた支援のあり方、これをしっかりと全庁にわたって進めていただきたいと思います。そして今、３歳になる息子がいる。次に移ります。","respondent":"伊崎子ども育成課長","answer":"切れ目のない支援の仕組みです。区では、これまでも母子保健相談、育児相談、子育て支援、さまざまな相談事業等をそれぞれの所管で実施してきております。","voiceIndex":140,"id":"exchange-057"},{"speaker":"つる委員","kind":"提案","question":"先ほどの質問の中でも、地域包括と関連して、要は、本当に地域でどういうふうに全世代が支えあっていくかという仕組みが、今後、自治体においても非常に課題になっていくと思います。私も平成２５年の決算特別委員会で、産前産後ケアの施設利用者への利用費助成、また産後ドゥーラの活用を提案させていただいて、過日の一般質問でも、そのことを提案させていただきました。","respondent":"伊崎子ども育成課長","answer":"そういった現状に立ちまして、この部分について、助産師あるいは今おっしゃられた産後ドゥーラなど、民間のいろいろな資源を活用しながら進めていく方向で、今、検討を進めているところです。","voiceIndex":142,"id":"exchange-058"},{"speaker":"つる委員","kind":"提案","question":"これについてもまた改めて機会を捉えて質問させていただきたいと思います。さまざま提案する中でこういう形で事業としてやっていただいて、非常に喜んでおります。その中で一定のご答弁がありましたけれども、改めてまた前年度、平成２６年度の取り組みと、今年度、１カ所、実施機関を増やしての実施かと思いますが、その今の状況等、教えていただければと思います。","respondent":"伊崎子ども育成課長","answer":"それぞれゆたか児童センター、大井倉田児童センターという昨年もやったところで実施をしておりまして、それぞれ１５人、１２人というご応募をいただきまして、皆さま、充実したワークショップを送っていただいたと認識しております。","voiceIndex":144,"id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"現在も好評だというふうに捉えました。私も実際、モデル事業のときに参加をさせていただいて、その参加されたお父さまたちからも本当に好評の声をいただいていますので、引き続き、この事業についても拡充を求めたいと思います。次に行きます。１３０ページ、子ども・子育て支援事業計画策定経費に関連してお尋ねしたいと思います。障害児向けの居宅訪問型保育についてお尋ねさせていただきたいと思います。","respondent":"竹田保育課長","answer":"今後もニーズの把握と適切な執行に努めてまいりたいと考えております。","voiceIndex":146,"id":"exchange-060"},{"speaker":"つる委員","kind":"確認","question":"１０月１日より１件ということで確認ができました。","respondent":"竹田保育課長","answer":"こちらの事業は、まだスタートしたところです。今後、しっかりとニーズを把握しまして、制度設計に見直すべき点がないかどうか十分チェックしながら適切に執行していきたいと考えております。","voiceIndex":148,"id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、恐らくこの事業者は、最近、テレビでもモデルとして取り上げられた事業者かと思いますけれども、しっかりと今後、適切な事業者と連携しながら充実させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"成果報告書の１３５ページのすまいるスクール運営費についてお伺いをします。もう１点、共産党は、制度改正のときには政策決定過程から、利用者の意見と働く職員の意見を聞くよう求めてきています。品川区の最大の欠点は、ここにあらわれているように、トップダウンで物事を決める、区民の声や職員の意見をしっかりと聞くように改めていただきたいのですが、いかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"この保護者への通知につきましては、文教委員会の中で条例の可決の前ではありますが、条例の概略についてお知らせをするということはご説明をさせていただいているところです。","voiceIndex":152,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"提案","question":"条例の内容について、１点目は時間延長、２点目、利用料についてお伺いをしたいと思います。安全を求める保護者の願いもよくわかっております。共産党は、この間、制度変更に当たり、保護者の意見、職員の意見をしっかり聞き、慎重に行うべきと提案をしました。共産党は、この間、再検討すべきと条例に反対をしてきましたけれども、こういった問題点をどう受けとめていらっしゃるのでしょうか。","respondent":"伊崎子ども育成課長","answer":"すまいるスクール利用料の見込みの総額です。現行７０％の登録率がありますが、これが仮に６０％になったと仮定をしたところで５,９００万円ほどの収入を見込んでおります。","voiceIndex":154,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学童保育、今は放課後児童健全育成事業の名前に変わりましたが、すまいるスクールにぜひ学童の機能をしっかりと位置づけてほしいと、この点で質問をします。先日、すまいるスクールの職員の方からお話を伺う機会がありました。保護者会の参加も少ないそうです。区は、全児童対策と違う学童保育の機能をどう捉えているのか、現実的に現在、どういった機能があるのか、具体的に教えていただきたいと思います。","respondent":"伊崎子ども育成課長","answer":"それに対してどのように対応していくべきかということを課として検討を進めているところです。","voiceIndex":156,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時間がなくなってしまいましたが、委託の職員では、十分に子どもを見ることができない、しょっちゅう替わるそうで、正規職員２名の配置を求めます。ぜひ今後、検討をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"１２３ページの上から１２行目、高齢者の趣味・健康づくり事業からの質問です。行政としての考えや、また目的はどこにあるのでしょうか。そして、この中で最も人気があるのは、数字的に見ても、いきいき健康マージャンですけれども、それではこの６事業の中で最も長く続いている事業は何でしょうか、教えてください。","respondent":"松山高齢者地域支援課長","answer":"一番人気があるのはというお話でしたけれども、こちらのほう、数字からもわかりますように、健康マージャンが平成１４年から実施しておりまして、数的にも非常に多くの方がご利用していて、区内でも定着しているものです。","voiceIndex":160,"id":"exchange-067"},{"speaker":"木村委員","kind":"質問","question":"そういう中で、この中にシルバーダンスパーティーというのがあるのですけれども、これも長く続いているということをお聞きいたしました。この長く続く魅力はどこに隠されているのか、しかし、逆に参加人数が１４４人と大変少ないわけでありますけれども、これが定員なのだから仕方がないと言われればそれまでなのですけれども、私的には、数が少ないように思うのですけれども、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"委員お尋ねのシルバーダンスパーティーですが、こちらは１４４名ということで、徐々に減少傾向にはあるのですけれども、こちらのほう、区と品川区社交ダンス連盟との共催でして、品川区社会福祉協議会からも後援をいただきまして、初心者講習会、ダンスコンテストなど。","voiceIndex":162,"id":"exchange-068"},{"speaker":"木村委員","kind":"意見","question":"大体年齢的にシルバーでありますから６０歳以上のことを言うわけだと思いますけれども、皆さまで体を動かすことだけではなくて、今言われたように発表の場として、自分の技術、技能がどのように上達をしているのか、変な意味ではありませんけれども、男性よりも女性のほうが自分を華麗に美しく見せることで日々のストレスを発散したり、若さを維持されているのではないかと思っています。","respondent":"松山高齢者地域支援課長","answer":"参加されている男性ということのお尋ねです。参加者１４４名のうち男性が５２名、女性が９２名の割合です。","voiceIndex":164,"id":"exchange-069"},{"speaker":"木村委員","kind":"質問・要望","question":"これ、男性はどういうところに魅力を感じるのかということをお聞きしたかったわけですけれども、私はそういう意味ではダンスはできませんから、そういうことがちょっとわからないのですけれども、ちょっとお聞きをしたかったと思っています。まさにそのとおりだと思っています。１人でも多くの元気な高齢者づくりに専念していただきたいのですが、これからの事業計画はどのように考えているのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"高齢者の方の豊富な経験ですとか知識を活かした活動を充実することで、地域の活性化にもつながると考えております。","voiceIndex":166,"id":"exchange-070"},{"speaker":"木村委員","kind":"質問","question":"聞き間違いでなければいいのですけれども、初心者から中級、上級ではなくて、初心者からゆっくり、そして一般という言い方をされるということを聞きましたけれども、おもしろい呼び方をするのですけれども、何か意味があるのでしょうか。この１,４００万円の使い道、その内訳をお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"それからあと、参加者の負担金のことですけれども、区の施設を使用する場合は７００円なのですけれども、区有施設でない場合、会場費等かかりますので、１,０００円ということになってまいります。","voiceIndex":168,"id":"exchange-071"},{"speaker":"木村委員","kind":"意見","question":"多分、大震災があった年、平成２４年のときには、大変多いと思うのですけれども、昨年は４４件と大きな違いだと思いますけれども、これは多分、喉もと過ぎれば熱さ忘れるような状況ではないかと思いますけれども、この助成を受けられる対象年齢、そして家族構成など、どのような条件でないといけないのかお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"現在の対象者なのですが、こちらは、６５歳以上の世帯、それから障害者のみの世帯、それから６５歳以上と障害者のみの世帯、あるいは平成２４年度より要介護３以上で６５歳以上の高齢者のいる世帯、それと身体障害者手帳２級以上の障害者のいる世帯です。","voiceIndex":170,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"本区でも多くの高齢世帯がおり、年々足腰も弱ってきます。１世帯でも多く取りつけていただくためには、どのようにすれば区民の皆さまに知っていただけるのか、多分知っていると思うのですけれども、本当に区内の区民の皆さまにこの情報がしっかりと行き渡っているのかどうかということに対して、お考えをお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"民生委員協議会等にも周知を図っているものですが、まだまだ引き続き、この件数が同数ということなので、今後も周知の強化を図ってまいりたいと考えております。","voiceIndex":172,"id":"exchange-073"},{"speaker":"木村委員","kind":"意見","question":"時間がありませんけれども、１つだけ。次に、１３４ページの上から３行目、児童センター運営費１１億３,３００万円余からですけれども、中ほどの児童センター事業ですけれども、２２事業が行われています。２２事業の共通の目標をお聞かせください。","respondent":"伊崎子ども育成課長","answer":"児童センター事業の目的です。児童センターは１８歳未満の全ての子どもを対象としまして、遊び、生活の援助と地域における子育て支援を行い、子どもを心身ともに健やかに育成することを目的としておりますので、これらの事業もその目的に沿って実施しています。","voiceIndex":174,"id":"exchange-074"},{"speaker":"沢田委員","kind":"質問","question":"２１６ページの介護保険保険給付と、成果報告書の１２３ページの地域包括支援センター機能強化事業で、高齢者の虐待のこと、それから、１２２ページの法人に対する助成金で、社会福祉法人法の改正のことでお伺いします。","respondent":"大串福祉計画課長","answer":"民間の事業所です。今、最初におっしゃっていただいた有料老人ホーム、いわゆる特養施設、こちらは区内で１２カ所、それから、サービス付きの高齢者住宅ですが、こちらが３カ所、以上です。","voiceIndex":177,"id":"exchange-075"},{"speaker":"沢田委員","kind":"意見","question":"民間のことでありますが、また、どういった場合にこういった調査とか検査とかということが定期的に、何かあったときに行われているのかお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"民間の高齢者住宅ですけれども、こういった場合、東京都が監査あるいは指導に入っておりますので、区としては何かよほど特殊な場合ということで東京都から情報を得ることはできますが、今のところ、直接区がかかわっていない民間のところに入っていくことはございません。","voiceIndex":179,"id":"exchange-076"},{"speaker":"沢田委員","kind":"質問","question":"先般、民間の介護施設で、高齢者の虐待、死亡事件がありました。区として、厚労省がこういう特別検査に入ったわけですけれども、何かこの情報は入っているのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"区内では、サービス付き高齢者住宅、同じ会社ですけれども、ただ、住宅部門というところで、そちらのところとは違う部門が経営しているということで、そちらの民間から区のほうに報告はいただいております。","voiceIndex":181,"id":"exchange-077"},{"speaker":"沢田委員","kind":"質問","question":"本社のほうにそういったことがあったということでありまして、品川区のほうにも報告があったということですけれども、厚労省の調査によると、介護施設などでの虐待や相談、施設での虐待相談件数は、２００６年から２０１３年で、２００６年が５４件、それが２０１３年では２２１件と、虐待と判断された件数は激増しているということで、委員会の質疑でもありましたけれども。","respondent":"永尾高齢者福祉課長","answer":"ただ、そういうところ、報告が施設から来ない場合もありますので、やはり苦情とかがあった場合については、きちんとその状況を確認して把握に努めていかなければいけないというふうに思っております。","voiceIndex":183,"id":"exchange-078"},{"speaker":"沢田委員","kind":"質問・要望","question":"高齢者虐待防止ネットワークに、こちらは在宅での高齢者の虐待ということが中心で、安心しながわネットワークの中で、「しながわ見守りホットライン」の設置ということでやっていますけれども、高齢者の虐待ということで関連して、虐待対応チームの充実とか、普及啓発事業の充実ということを今後さらにしていくですけれども、在宅での虐待に関して、今後の取り組みについて改めて確認させてください。","respondent":"永尾高齢者福祉課長","answer":"在宅での取り組みということで、区のほうでもケアマネに対しての研修会を行って、その発見に早く努め、スピード感のある対応ができるような研修を行っていたり、あとは、民生委員に対する啓発をやるとともに、また、そういう事故があったときには。","voiceIndex":185,"id":"exchange-079"},{"speaker":"沢田委員","kind":"意見","question":"それから次に、関連してその続きというか、リハビリテーション病院なのですけれども、先日、五反田に大変立派な、２００床もある大変大きな回復期のリハビリテーション病院ができました。これもやはり民間の病院ということでありますけれども、このリハビリ病院と、区は今の段階でどの程度コミュニケーションというか、関係があるのかお聞かせください。","respondent":"大串福祉計画課長","answer":"リハビリ病院ということで、しかも民間ということで、今現在、特に区と何か関連ということはないというのが現状です。","voiceIndex":187,"id":"exchange-080"},{"speaker":"沢田委員","kind":"質問・要望","question":"まだ特に関係はないということでありますけれども、このリハビリテーション病院のパンフレットには、基本方針の中に「地域医療」という言葉が入っていまして、地域の医療、福祉施設と密接な連携をとりという、寝たきりゼロ、在宅復帰を目標に、誰でも安心して利用できる回復期リハビリテーション病院を目指しますということでそう書いてあるのですけれども、地域の医療。","respondent":"川島健康課長","answer":"新設の病院です。地域医療連携の会議のほうにお誘いをかける、これからアプローチをとるという段階です。それから、災害時の医療体制の中にもぜひ入っていただいて、区のために貢献していただきたいということで、積極的に私どももそういった営業みたいなものをかけていこうです。","voiceIndex":189,"id":"exchange-081"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは社会福祉法人法の改正についてなのですけれども、今国会で７月に社会福祉法人法の改正が衆議院を通過した段階で参議院のほうでは審議はできなかったということで審議未了になってしまいましたけれども、平成２７年度からいろいろ動き出すということで、秋の国会ではしっかりと採決していただけるかと思うのですけれども、今回の社会福祉法人法の改正は、これまでにない大変大規模なもので。","respondent":"大串福祉計画課長","answer":"大きなものとして５つ、経営組織のガバナンスの強化、事業運営の透明性の向上、財務規律の強化、それから、今ご紹介いただきました地域における公益的な取り組みを実施する責務、それから行政の関与のあり方といったところです。","voiceIndex":191,"id":"exchange-082"},{"speaker":"塚本委員","kind":"質問・要望","question":"区長からは、「今後、さまざまな活動団体と協議しながら体系化を図っていく」と、こういう答弁もいただいているところですが、新たな担い手は総合事業と、もう一方のところで、いわゆる有資格者によるケアマネとか、あるいはヘルパーといわれる有資格者の人材不足というところで、今後は貴重なといいますか、有資格者の方たちは、プロフェッショナルとしての専門性を大いに活かして、より重度の。","respondent":"永尾高齢者福祉課長","answer":"それに備えて、実務者研修の通信制の講座も今度、平成２８年度から開始するように準備を進めております。現在働いている方については、実際に福祉カレッジを開催して専門性を高めるというようなことを行っております。","voiceIndex":194,"id":"exchange-083"},{"speaker":"塚本委員","kind":"確認","question":"私より、特にさらに確認したいのは、重度の方の介護については、より処遇の改善といいますか、重たい作業というか、重たい仕事をされるわけなので、そういった面もこの人材の確保については外せないポイントというか、問題だと思いますけれども、その辺についてはどのように考えていらっしゃるかお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"介護の仕方によって体への負担がやわらげられるというふうに考えておりまして、現在、ケア協議会のほうに委託をしておりまして、研修でボディーメカニズムというものを、実際に介護をしている職員のために行っております。","voiceIndex":196,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"そういった作業面での軽減というところと、もう１つは、いわゆる給与面といいますか、そういう処遇、待遇、こういったところでの重度な介護を担っていただくいわゆるプロフェッショナルの有資格者の方々への処遇、待遇、こういったところでの今後の改善というか、そういうものは一連の介護人材の活用の中でどのように考えていらっしゃるかお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"さまざまそういう研究を国のほうでも行っており、報酬改定をこれまでも重ねてきているところですけれども、ただ、報酬を単純に上げると、例えば、パートなどで働いている方だったり、扶養家族としてパートで働いている人などの場合だと、オーバーしてしまうとか。","voiceIndex":198,"id":"exchange-085","title":"議員研修会の内容と所要時間"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。こういった動き、品川区としてどのように捉えているか、外国人の介護人材の受入れ、品川区はどのように受けとめていらっしゃるでしょうか、お伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"外国人の場合、多分言葉のことと、あと、生活習慣のところで難しいところが出てくるのかとは思うのですけれども、ただ、現場の意見などを聞きますと、外国人だということがわかりますので、逆にお互いに気を使いながら意思疎通ができるということも聞いております。","voiceIndex":200,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問・要望","question":"残った時間で、紙おむつの支給についてなのですけれども、高齢者、障害者の紙おむつ支給が、もともと現物だったものが、今、月５,０００円の交換券ということで購入できる仕組みというふうに変わっておりますけれども、これによって、従来おむつだけというものが、尿とりパッドですとか、いろいろなものが交換できる、こういったことになっているかと思いますけれども、こういう中で。","respondent":"永尾高齢者福祉課長","answer":"社会福祉協議会では、実際に職員が体験してみたりして、使いやすいものを選んだりということも聞いております。区と社会福祉協議会と協議しながら、品目の変更等はこれからもかけていきたいと考えています。","voiceIndex":202,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。さまざまな声が私どものほうにも届いておりますので、都度お伝えすることもしていきたいと思いますけれども、区民の方々のそういったご要望をしっかり受けとめていただいて、品目を増やすということはそれほど大きな弊害はないと考えていますので、前向きに捉えていただいて対応していっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"成果報告書１３５ページのすまいるスクール運営費についてお聞きします。条例改正がありました。ここで改めてお聞きします。すまいるスクールの役割は何でしょうか。そして、今の現在使われている方々、小学生になると思いますが、実態の調査をしたのでしょうか。この２つをお聞きします。","respondent":"伊崎子ども育成課長","answer":"すまいるスクールの役割ですけれども、全児童放課後対策ということでして、放課後子ども教室、放課後の学習支援、スポーツの支援、文化活動の支援などと、あと、放課後健全育成事業、子どもの家庭にかわる安心の場を提供するという２つの機能を兼ね備えているものです。","voiceIndex":206,"id":"exchange-089"},{"speaker":"西本委員","kind":"確認","question":"すまいるスクールなのですけれども、先ほどの質問の中にもありましたが、昔、学童保育クラブというものがありました。その当時から再三私は確認しているのですが、延長というものもありました。なぜかというと、保育園もその当時から７時半、８時半、１０時という延長保育をやっておりましたので、当然ながら働く親御さんからは延長してほしいというのは当然あるわけです。ニーズは高いと思います。","respondent":"伊崎子ども育成課長","answer":"これまで、今ご説明いただいたとおり、子どもの自立に向けての過程ということで、すまいるスクールの時間を規定しておりましたけれども、やはり社会情勢の変化というものは非常に保護者にとっての不安が大きくなってきたところです。","voiceIndex":208,"id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"社会ニーズがある、社会環境が非常に変わってきておりますので、やはり延長が必要な方もそれはいるでしょう。ニーズはわかります。しかしながら、変えてはいけないこともあると思うのです。子どもにとってということを考えたときに、一番大切な時期です。４月に小学校に入学して、宿題もたくさん出ます。私も働きながら３人の子育てをしましたからよくわかっております。それをどのように伝えていきますか。","respondent":"伊崎子ども育成課長","answer":"そういったところを徹底していく中で、親の役割ということもきちんと理解をしていただいた上でご利用していただければと考えています。","voiceIndex":210,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ここだけは押さえてください、「親の役割は何ですか」。ただ単に延長すればいいとか、そういう問題ではなくて、しっかりとやるべきことやってくださいというしっかりとしたメッセージを伝えていただきたいと強く思います。少し運用についてお聞きしますけれども、１８時まで預けていた親、これはこの仕組みを見ると、３,０００円、４,０００円という形で月の利用料がかかってきます。","respondent":"伊崎子ども育成課長","answer":"その中で一定の負担をしていただくということで料金を上げさせていただきました。高いということで使えないことがないように、そこの減免規定、免除規定などは整えていこうと考えております。","voiceIndex":212,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"これからの、来年からになりますけれども、どういう使用状況になっていくか、そして子どもたちへの影響はどういうところにあるのか、しっかり見ていただきたいと思います。そして、あまり子どもたちにとっていい環境に。例えば、お迎えに行くのに７時過ぎても迎えに来ないという人もいるかもしれません。そういったときの対応をどうするかということも含めて、慎重に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１３２ページ、社会福祉費の３目児童福祉施設費、保育園運営費に関連して質問します。見直しにより待機児ゼロになるときが平成２８年４月から遅れるということでしょうか。つまり、いつ待機児ゼロにするのか伺います。","respondent":"今井待機児童対策担当課長","answer":"現在の子ども・子育て支援事業計画の中にあります、子ども・子育て計画では、平成２５年度の人口とニーズ量におきましては、確かに平成２８年度末を目標ということで掲げておりますけれども、現時点で人口推計が変わりますので。","voiceIndex":216,"id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"今、検討中、推計が変わったので検討中ということですけれども、この新人口推計では、年少人口は今後２４年間、現在よりも多い状態が続いていくとなっています。遅れるかぐらいはわかると思いますので、もう一度改めてお聞きしたいと思います。","respondent":"今井待機児童対策担当課長","answer":"人口自体が増えておりますので、確保方策自体も現在の子ども・子育て支援事業計画では、毎年３４５人の開設計画で平成２８年度末というふうなところを見込みましたけれども、今、実際には来年も開設の数を強化しておりますので、改めてこのニーズ、または保育需要を見ないと。","voiceIndex":218,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"遅れるということも言えないということなのですけれども、では、違う角度から質問させていただきたいと思います。昨年の区長選挙で公約に掲げた待機児ゼロ、これは任期の４年以内には待機児をゼロにするということでよいのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"待機児童解消というのは、国の目標が平成２９年度末の解消ということで、前倒しで平成２５年度から国も努めておりますし、東京都も努めております。品川区もそれに先立って平成２２年度から強化して進めているところです。","voiceIndex":220,"id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"大きな、重大な目的だと、政策目標だということなのですけれども、私がお聞きしたのは、４年以内に実現させるのか、こういったことを聞いたので、しっかりと答えていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"先ほどの質問でも待機児童解消年次をご質問になりましたけれども、それと同様です。今後、子ども・子育て支援事業計画の策定の中で改めて検討してまいります。","voiceIndex":222,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"この政策目標ということなのですけれども、今のご答弁ですと、目指すべきものではなくて、実現されるものでないというような感じなのですけれども、やはりこの保育というのは、区の責務だと思います。実現できないということでは済まされないと思いますので、改めて４年以内にできるのか、しっかりと答えていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"こちらの計画につきましては、繰り返しになりますけれども、待機児童解消ゼロというのは、これはもう喫緊の課題というふうに認識しておりますので、その実現に向けてさまざまな手段で努力していく考えです。","voiceIndex":224,"id":"exchange-098"},{"speaker":"のだて委員","kind":"質問","question":"さまざまな対策でやっていくということなのですけれども、過去最悪の待機児童数となった今年の入園申請者数は３,０６０人です。一般質問の答弁で、昨年９月の入園申請者数は９７９人で、今年の９月は１,１７３人だったと説明しています。既に９月時点で昨年よりも約２００人多い状況です。この状況を鑑みて、来年４月の申請者は今年を超えると見ているのでしょうか、伺います。","respondent":"今井待機児童対策担当課長","answer":"ですので、私ども、現在の入園申込者数の増加を踏まえますと、この２,７９９人が３,０００人程度に最終的にはなるものというふうに見込んでいるところです。","voiceIndex":226,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"この３,０６０人というのは、一次と二次の申請者数を合わせた数になっておりますけれども、昨年よりも来年４月に保育園に入れない待機児が増えると見ているのか伺ったので、改めて答えていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"保育の申込者数につきましては、今年の４月１日のときが２,７９９人、そして入園申込者数、来年度は３,０００人を今想定しておりますけれども、今年４月の開設は、認可保育園２園にとどまりましたので、来年につきましては、大規模保育施設３００人の定員も含めて。","voiceIndex":228,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のご答弁ですと、昨年が２,７９９人で、今年が３,０００人ということで、申請者数が増えるということだと思います。来年４月に向けて待機児ゼロにしていく、こういったことが大事になってきます。４月に保育園に入ることが切実な願いなのです。この願いをしっかりと受けとめて、４月に待機児を生み出さないための緊急対策、追加対策に踏み出すことを求めますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"毎定例会で請願等もいただきまして、同じようなご説明を繰り返しているところなのですけれども、私ども、今年の５月の臨時議会の中で、来年の４月の開設に間に合わせるために、公設民営型の大規模保育施設という緊急対策を議会のご議決をいただいて速やかに進めているところです。","voiceIndex":230,"id":"exchange-101"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。本日の款別審査でずっといろいろな話を聞いていまして、１３５ページ、すまいるスクール運営費が直前で幾つかありました。かねてより前半の時間の延長等を要望させていただいていて、このたび時間延長にもなりました。今まで６時までが預かり時間でみたいな話がありましたが、確認ですけれども、これ、預かり時間はあくまでも５時ですよね。","respondent":"伊崎子ども育成課長","answer":"すまいるスクール、現在の利用時間は５時までとなっておりまして、就労等、事情がある方については６時までとなっております。","voiceIndex":233,"id":"exchange-102"},{"speaker":"渡部委員","kind":"質問・要望","question":"当然いろいろな相談を議員とかにもされるのでしょうから、それぞれ発言の内容は変わると思いますが、概ねそのような形で十数年も運用はされているのだから問題はなかったのかというふうに感じます。すまいるスクールは５時まで。５時から６時は事情のある人だけが預かってもらうんだよ。その違いもあるんだよ」とご説明して、「あら、そうなんだ」などという話があるぐらいですから、そういうこともある。","respondent":"伊崎子ども育成課長","answer":"時代の変化、保護者のニーズの変化、さまざまなものに対応しながら、子育て支援の一番大事なところはしっかり踏まえて対応していきたいと考えております。","voiceIndex":235,"id":"exchange-103"},{"speaker":"渡部委員","kind":"確認","question":"事務事業概要のほうを確認させていただいて、あらあらの金額ですとか、人数の推移は見てとれるのですけれども、もし数字を持ち合わせていたら教えてほしいのですが、１万何千人参加の中で、大体どれぐらい、年齢層はどういうふうに散らばっているかということをまず知りたいのと、要は、あそこは本当に泥んこになって遊んでください、火もがんがん焚いて遊んだりするような施設。","respondent":"伊崎子ども育成課長","answer":"こちらは雨の日も、そんなにひどい雨でない限りは基本的にやっておりまして、利用につきましては保護者がついてくる家庭はいいのですが、子どもだけで来る方もいらっしゃいますので、プレイリーダーという方を配置しています。委託の職員が対応しています。","voiceIndex":237,"id":"exchange-104"},{"speaker":"渡部委員","kind":"質問","question":"そのプレイリーダーがどういう方が当たっている、委託先の方だとは思うのですけれども、それだけなのか、ボランティアとかが入っているのかということが１つと、その人数、当然、今これ、人数がわかるかといったら、書いてもらっているからわかると思うのですけれども、区外の方の利用はあるのかどうか、わかれば教えてください。わからなかったらいいです。リーダーのこと。","respondent":"伊崎子ども育成課長","answer":"委託はＮＰＯ法人に行っておりまして、そこでは子どもの遊びを指導する者、児童指導員の資格を持った方がプレイリーダーを行っております。その他、高校を卒業した方などがボランティアに来ていると聞いております。","voiceIndex":239,"id":"exchange-105"},{"speaker":"渡部委員","kind":"質問","question":"参加されている方々はいろいろなところがあると思うのですけれども、平日などですと、１カ所ですから、あの辺の界隈の方が多いのかと。せめてあと１カ所、１カ所と言わず、例えば勝島の公園とか、広いところの一画でもう１カ所そのような方、それこそＮＰＯなのか、また別の団体で、そういうプレイリーダーになれる素質のある方とかがいると思うのですけれども、増やす考えでいかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"プレイパークにつきましては、子どもの情操を育てるということで大変貴重な空間だと考えております。区としましても、今、増やす方向で検討をしています。","voiceIndex":241,"id":"exchange-106"},{"speaker":"渡部委員","kind":"質問","question":"増やす方向で検討しているのですか、本当に前向きに検討をお願いしたいと思います。それで、それに対してクレームなどはほとんどない。一切ないとは言い切らないですけれども、ほとんどないような状況。利用されている方にしてみましても、それぐらい子どもが元気なほうがいいのだという方がどうやら利用していただいていると思います。すみません、最後に１つ、検討していただいて、できそうなのですか。","respondent":"伊崎子ども育成課長","answer":"２カ所目のプレイパークの開設に向けまして、庁内で頑張って協議を進めているところです。","voiceIndex":243,"id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１２４ページの仮称ふれあいステーション、２点目が、１２９ページのひとり親家庭支援事業、この２点をお伺いします。１点目の仮称ふれあいステーションですけれども、午前中にも我が会派の新妻委員からも質問しましたけれども、私からは、事業の運用、中身について考え方をお聞きしたいと思います。ふれあいステーションを利用できる対象者についてお聞きいたします。お願いします。","respondent":"大串福祉計画課長","answer":"あるいは、日中独居、夜間はご家族がいらっしゃるけれども、日中には高齢者のみになってしまう、こういった方たち、高齢者全般が対象になってくるといったところです。それから、対応の流れですが、午前中もご答弁させていただきましたが、８月に新規で２カ所できました。","voiceIndex":247,"id":"exchange-108"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご説明の中にもありました、この事業は介護保険のサービス外の支援事業ということで、そうしますと、これまであったふれあいサポート事業とはどう違うのかということと、あと、さまざまに寄せられる相談事に対して、できる限り対応していただきたいですし、支援していただきたいと思いますが、その点の対応の機能、能力というのでしょうか、どのような形で考えていらっしゃいますでしょうか。","respondent":"大串福祉計画課長","answer":"対応の仕方というところかと思います。","voiceIndex":249,"id":"exchange-109"},{"speaker":"こんの委員","kind":"質問","question":"一人でやっと行ったのだけれども、先生との、主治医との対話の中で、治療についてだとか、あるいはいろいろな指導、そのことについてよく理解ができなかったり、会話が成り立たなかったりという自分でもちょっと不安なところがあるというようなご相談、こういうものは介護保険にはなかなかつながらない部分でありますが、もしこうした事例があった場合は、どのように考えられますでしょうか。","respondent":"大串福祉計画課長","answer":"やはりご本人もしくはご家族の方がそういったお医者様との治療内容あるいは自分の症状についてのご説明といったところが第一義かというふうには考えております。ただ、多分いろいろなご事情があろうかと思いますので、どんな対応ができるか検討してまいりたいと思います。","voiceIndex":251,"id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"難しいというのは私もそのような思いはいたしますが、ぜひ今後の対応として研究、そして考えていただきたい、このように思います。次の質問に移ります。ひとり親家庭支援事業のほうです。近年、世帯の１人当たりの所得が国民の平均所得の半分に満たない約１２２万円以下で生活している困窮状態にある世帯の割合が、ひとり親家庭に限ると５４.６％に上るという報道があります。","respondent":"廣田子ども家庭支援課長","answer":"自治体窓口のワンストップ化でありますとか、そちらのほうの方向性を受けまして、具体的に少しずつ、現在の時点では、拡充を検討している事業、新規で検討している事業というところで、項目出しはいただいているところではありますが。","voiceIndex":253,"id":"exchange-111"},{"speaker":"こんの委員","kind":"質問・要望","question":"この機会をぜひ、国の動きがある中ですので、品川区としては、現在の実施をされている事業の中で、今、現状と、そして課題の洗い出しをして、今後の支援の強化に向けての取り組みを進めていくことが大事だと、このように考えておりますので、ぜひその点、国の動きも注視をされながら、この支援の強化に向けてお願いしたいと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。成果報告書の１２４ページから１２８ページの障害者福祉費の、どこに含まれるのかがあれですが、発達障害児全般についてお尋ねいたします。平成２０年から品川児童学園内に子ども発達相談室が設置されています。そこで、平成２６年度の実績をお伺いします。もし年齢ごとにそういった人数がわかればお願いいたします。","respondent":"中山障害者福祉課長","answer":"平成２６年度の子ども発達相談室の相談件数になりますが、児童学園本園で４,８２８件、昨年度、戸越ルームを開設いたしまして、そちらが１８４件、合計で５,０１２件の相談がございました。年齢別はとっていないので申しわけありません。","voiceIndex":257,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、５,０００件を超える相談があったということですが、あとで戸越ルームが開設されましたが、この平成２６年度時点での、相談体制の課題はどのような点があったのでしょうか。","respondent":"中山障害者福祉課長","answer":"それと同時に、常勤の相談員を１人置くことで、例えばインテーク、インテークというのは実際に心理の検査をとったりする作業になるのですが、その前段階からの相談も行いながら、お子さまの療育につなげたり、あるいは親御さんの支援というところで行っているところです。","voiceIndex":259,"id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"相談件数の増加に対して対応されているところですが、相談待ちの期間が長いという課題もまだあるということですので、今年度の相談について、そういった点を解消しながらよろしくお願いします。平成２６年度はこの庁内連絡会がどのぐらい開かれたのかということと、具体的にそこでどのようなお話がされて、それがどのような成果があったのか、お教えください。","respondent":"中山障害者福祉課長","answer":"３回の中での主な中身というところになりますが、それぞれの保健、教育、保育、それから障害、各分野での課題の洗い出し、それから療育ノート作成に向けての打ち合わせ、それからあとは、お子さまの相談のときに伝える実際の冊子みたいなものを作成しようということで、この間。","voiceIndex":261,"id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが第一歩になるのではないかと思いますが、どのように把握しているのかお聞かせください。先ほどの庁内連絡会も３回開かれたということでありますから、そこの中でそういった情報の共有も行われていたと思いますが、その点、品川区ではどの程度把握されているでしょうか。","respondent":"中山障害者福祉課長","answer":"発達障害のあるお子さまの人数の把握ということなのですが、実は発達障害のみであれば、特に手帳が必要ないというところになりますので、人数の把握が非常に難しい状況にあります。児童学園での相談があるということは１つあります。","voiceIndex":263,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その発達障害なのですが、医者に発達障害と診断されなくても、落ち着きがなかったり、言語が遅かったり、さまざまな発達に遅れのあるお子さまが多くなってきています。それぞれ特性があるために非常に細かい支援が必要となっていますが、保育の現場、保育園、幼稚園で人的な加配が必要ですが、品川区としてどのような対応をされているでしょうか。","respondent":"竹田保育課長","answer":"例えばの数字でご紹介しますと、保育園４２園に対しまして、派遣１８、非常勤１０４、幼保につきましては、派遣職員２、それから非常勤１０といった数を配置しています。特別支援全体でそういった職員を配置しています。","voiceIndex":265,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひそのような手厚い支援を今後も続けていっていただきたいと思います。平成２６年に改定された長期基本計画の中でも切れ目のない特別支援の実施ということがうたわれています。最後に要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-118"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１３４ページ、児童センター事業について、１８９ページ、電算システム改修費について、１２１ページ、運営助成について、１９５ページ、特定保健指導事業について、１３１ページ、ＡＥＤの設置費助成についてお伺いをしていきます。簡単な質問です、大丈夫です。それと１３１ページのＡＥＤの設置費助成、これは保育園全体でどれだけ今、ＡＥＤが設置されているのかお知らせください。","respondent":"永尾高齢者福祉課長、高森国保医療年金課長、竹田保育課長、伊崎子ども育成課長","answer":"この１万円というのは、特に理由がある１万円ではなくて、内訳としては、人件費の助成と、保険の助成と。こちらの保健指導ですが、平成２６年度は対象者数が国保の基本健診を受診した方の中から、お医者さまからのご推薦というか、内容がよろしくない。一部まだ未設置のところについては、積極的に働きかけていきたいと考えております。児童センターの多世代交流施設化ですけれども、ハード上の課題がいろいろありますので。","voiceIndex":269,"id":"exchange-119"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"特定保健指導事業は、課長、本当にお疲れさまでした。成果が出てよかったです。保育園にあえて必要ないのかというふうに思いますが、未設置の保育園については、これはぜひ積極的に働きかけをしていただきたいと思いますが、１点だけそこで、例えば予算で毎年何園まで助成をするとかということが決まっているのかどうか。先ほど数を聞き漏れたので、あと何園ぐらい未設置の保育園があるのかお知らせください。","respondent":"竹田保育課長","answer":"未設置の園につきましては、年度の予算前に意向調査をしまして、その意向に基づきまして予算化しています。未設置のところなのですが、正確なところがわかりかねるのですが、約１０園ほどというふうに考えております。","voiceIndex":274,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"１２２ページの要介護度改善ケア奨励金と、１９９ページの後期高齢者医療特別会計の２点をお伺いします。介護度が改善することや介護の質の向上に取り組む施設職員に対し、本人や家族の評価はどのような声が上がっているでしょうかということを２つ目にお聞きして、また同時に、８６名ということですが、改善された方々の年齢についても、平均年齢とか、分布とかについても教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"施設サービス向上研究会ですが、平成１５年に開始しております。まだまだ民間のサービスが不十分な時代でした。その中で品川区はいち早く質の向上を取り上げて、区が中心になって、各社会福祉法人と協力しながら、その研究会を立ち上げています。","voiceIndex":278,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問","question":"改善された方々の年齢についても、当然皆さま、ご高齢で、８０代かと思うのですけれども、一応参考までに教えていただければと思います。続きまして、今お話がありましたように、介護の質というところに着目をしていきたい。それからもう１つ、介護度が改善することによって、１つの成果のあらわし方という観点かもしれませんけれども、在宅介護になられた方がいらっしゃるのかどうか。","respondent":"永尾高齢者福祉課長","answer":"ご家族もそれは望んでいることだと思うのですけれども、ただ、戻れる環境にない場合について、入所の特例という措置をとって、そのまま入っていただくということもあると思います。現状では、３から２になって出たというケースは今のところはありません。","voiceIndex":280,"id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、これは今回、施設での介護の改善という事業ですけれども、一方で在宅で介護されている方が区内には約１万人程度いらっしゃいますが、今度は施設というカテゴリではなく、いわゆる通所等在宅介護に取り組む事業者が区内にはたくさんいらっしゃると思いますけれども、こういったカテゴリの中で、お互いに事業所間で切磋琢磨をしてという、もう一方の広がり方もあるのかと思いますので。","respondent":"永尾高齢者福祉課長","answer":"品川区の取り組みの場合、２４時間介護をするという意味で、入所施設を対象としております。それは介護度が改善する要因として、ケアだけではなくて、いろいろな生活環境だとか、そういうものもかかわってきます。","voiceIndex":282,"id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、品川区の後期高齢者の方々の医療費は一体どのようになっているのか、伸びですとか、また医療費額とか、わかる範囲で教えていただきたいと思います。それから、よく健康寿命ということが言われておりまして、直近の推計では、女性が７３.６歳、男性が７０歳強ということが国で言われておりますけれども、品川区の健康寿命という数字は出されているのでしょうか。この２つをお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"現役並みについても１億３,９００万円ということで、総額でいきますと、療養給付費の総額は１０７億５,２８７万円余というふうな状況です。","voiceIndex":284,"id":"exchange-124"},{"speaker":"本多委員","kind":"質問・要望","question":"この数字の差について教えていただきたいのと、２７６人の相談員がそれぞれ受けた相談件数と相談量がどのくらいあるのか、内容についてはいろいろ難しいかもしれませんが、その辺の分析の概要について教えてください。","respondent":"大串福祉計画課長","answer":"３年に一度の高齢者実態調査、これについても従事をしていただく、こういったものが主な業務内容等々になっているといったところです。","voiceIndex":290,"id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"相談、内容についてはいろいろ個人情報ですから出さなくていいのですけれども、その受けたものの対策ができているのかどうか、その辺のところを教えてください。","respondent":"永尾高齢者福祉課長","answer":"高齢者相談員の方からは、毎月報告をいただいておりまして、それを高齢者福祉課のケースワーカーのところにその書類が全て回りまして、気になる内容については、在宅介護支援センターのケアマネと連携をして支援をするというようなサイクルをとっております。","voiceIndex":292,"id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"多種多様な相談があるかと思いますが、よろしくお願いいたします。昨日、渡辺委員から生活安全について取り上げられました。生活安全というと、款別では総務費になりますけれども、消費者センターですとか特殊詐欺対策では産業経済費になりますけれども、こうした視点を全区的な取り組み、全庁的な取り組みというところで、高齢者の目線での対応については、どのように考えていますでしょうか。","respondent":"永尾高齢者福祉課長","answer":"いろいろな詐欺が今横行しておりますけれども、もちろんマスコミ等や民生委員等の相談等で詐欺の防止ということも考えられていますし、これまでもずっとやっておりますけれども、先日、弁護士会の方にご紹介をいただきまして。","voiceIndex":294,"id":"exchange-127"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に部、それぞれ横ぐしで連携をとりながら対策をしていただきたいと思います。筋力トレーニング、さまざまな体操、しながわ出会いの湯、本当にメニューが多いのですけれども、いきいき脳の健康教室などと、その辺の高齢者の方たちの危ない話を回避する緊張感というのですか、その辺と介護予防とのかかわりについて、そうした視点などについていかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"そういったときに区と情報連携をしまして、私ども高齢者地域支援課から高齢者福祉課のケースワーカーのほうに情報を流しまして、きちんと丁寧に対応しております。","voiceIndex":296,"id":"exchange-128"},{"speaker":"本多委員","kind":"質問・要望","question":"この出生率の改善に向けて、ちょっと目的は違うと思うのですけれども、しながわネウボラネットワークなのですけれども、先ほどもたくさん出ていますけれども、来月から保健センターの専門職により、いよいよ始動するということで、目的は切れ目ない子育て支援ということなのですけれども、これが来月スタートするというところの準備状況、その辺をお聞かせいただきたいのと。","respondent":"伊崎子ども育成課長","answer":"しながわネウボラネットワークの進捗状況、準備状況です。現在、しながわネウボラネットワーク検討委員会を立ち上げ、その中でネットワークの構築、それに伴う産後ケア事業など、必要な事業の企画、選定、実施に向けての仕組みなどを今検討しています。","voiceIndex":298,"id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１３２ページの保育園運営費についてお伺いしたいと思います。なぜ６０％なのか、その根拠について説明をしていただきたいと思います。１０年前の値上げのときは、全国の自治体が６０％くらいなのでと、しかし、２３区はほとんどが５０％前後だと、そういう根拠としてはちょっと曖昧な説明だったわけですけれども、今回はどういうふうな説明をされるのかということでお聞きしたいと思います。","respondent":"竹田保育課長","answer":"１人当たりの月額保育料でいいますと２万３,５７９円です。６０％を実施することによって適正な負担に近づけていきたいと考えております。それから、２３区の状況ですが、今、手元に詳しい資料はございません。","voiceIndex":301,"id":"exchange-130"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ６０％なのか、６０％にするとなぜ適正なのかという、そのなぜなのかということでお聞きしたいので、その根拠についてお聞かせいただきたいと思います。それが保育料値上げの根拠になっているわけですから、ご説明ください。それからあと、モデルを出さない問題です。保育料もそうすべきではないかと思いますけれども、なぜ国保と同じようにモデルで出すことができないのか伺いたいと思います。","respondent":"竹田保育課長","answer":"モデルケースにつきましては、それぞれ所得の状況、あるいは控除の状況、個々によって違いますので、モデルケースを挙げるのではかえって誤解を招く部分もあろうかと思いますので、個々のご質問に対して丁寧にご説明していきたいと考えております。","voiceIndex":303,"id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ６０％なのかということでは、政策目標というだけで、なぜなのかという説明にはなっていないのです。それなのになぜ出せないのかということなのですけれども、それでも出さないというふうなことで言っていますので、私たちが計算をしたことがこれでいいのかということで改めて伺いたいと思います。Ｄ６という保育料でした。２万３,５００円。このモデルの計算の方式でいいかどうかを伺いたいと思います。","respondent":"竹田保育課長","answer":"モデルケースの件ですが、それぞれ年が変われば所得が変わる。お子さまの年齢が上がれば保育料が下がるなど、いろいろなケース、要因がありますので、モデルケースよりも個々のご質問に対応していきたいと考えております。","voiceIndex":305,"id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民がどういうふうな保育料になるのかというものをきちんと見えるように努力すべきです。区はこれだけの値上げをするわけですから。それともう１つ確認をさせていただきたいのが、多子軽減の対象人数です。小学校３年まで拡大をすることで、第二子、第三子それぞれ現在の人数、新たに増える人数、トータルの人数、どうなるのかということについてお聞かせいただきたいと思います。","respondent":"竹田保育課長","answer":"モデルケースの件ですが、大雑把なモデルケースを示すことよりも、かえって丁寧に個々のご質問に答えることのほうが私は丁寧な対応、わかりやすい間違いのない対応だというふうに考えております。","voiceIndex":307,"id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第一子が小学校３年ではなくて、戸籍上の全ての多子まで拡大すべきだということを改めて要望しておきたいと思います。私はなぜこれを多子軽減に充てないのか、住民税は新たな増税で増え続けているわけです。これを多子軽減に充てるべきだと思いますけれども、いかがでしょうかというのが１点です。それから、保育料は値上げではなくて引き下げこそすべきだと求めますけれども、いかがでしょうか。","respondent":"竹田保育課長","answer":"次の世代へバトンをつなぎやすくすることによって、品川区を未来の希望の持てるまち、保育料を通して住み続けたいまち品川を実現していきたいと考えております。","voiceIndex":309,"id":"exchange-134"},{"speaker":"たけうち委員","kind":"質問","question":"私は、１２１ページの社会福祉協議会助成金と、１２８ページの精神障害者地域生活支援センター運営費でお聞きしたいと思います。初めに、社会福祉協議会の助成金ですが、１２１ページに運営助成と、また事業助成、それから団体助成とあります。運営助成と事業助成は何となくイメージがつくのですが、この団体助成の３７４万円、これについてどのようなあれで算出をしているのかということを教えてください。","respondent":"大串福祉計画課長","answer":"社会福祉協議会の団体助成ですが、これは各課またがった形で社協にお出しをして、社協のほうから各団体へ助成を行っているというものです。内訳につきましては、保護司会、母子寡婦連合会、遺族会、手話登録等の団体、こういったところにお出しをしているといった内容のものです。","voiceIndex":312,"id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、この寄附の部分が高額な場合に、その年度は入ってくるものが増えると思うのですけれども、区だと、わからないですけれども繰り越ししていくと思うのですけれども、先ほど、ほかの委員のところでもあったのですけれども、まだ法律は成立していないけれども、これから社会福祉協議会の内部留保だとか、また地域貢献というものが叫ばれてくる中で。","respondent":"永尾高齢者福祉課長","answer":"ふれあい作業所の建設の部分に約２,０００万円、あと、ふれあい売店、ここの庁舎のふれあい売店のほうに約５００万円ということ、あと、そのほかボランティアファンドがありまして、ボランティアの団体が新規に事業をやるときの資金を貸し付けるというボランティアファンドに。","voiceIndex":316,"id":"exchange-136"},{"speaker":"たけうち委員","kind":"意見","question":"次に行かせていただきますけれども、精神障害者の地域生活支援センター運営費ということで、「たいむ」のほうの事業だと思うのですが、「たいむ」でピアカウンセリングというものをやっていると思うのですけれども、その事業内容と実績について、また、今、厚労省のほうでも、今度、ピアサポートということで、この導入についてのいろいろな指針等が総合支援法の中で出されていると思うのですけれども。","respondent":"中山障害者福祉課長","answer":"ただ、精神障害という障害の特殊性ということがございまして、なかなかご本人たちの体調ですとか、あるいは精神の状態が安定しないというところから、継続的に固定的にやっていくということが実際的には難しいのかということで感じております。","voiceIndex":318,"id":"exchange-137"},{"speaker":"たけうち委員","kind":"質問・要望","question":"課題については今課長がおっしゃっていただいたことがあると思うのですが、品川区としては、これは事業としてはまだやっていらっしゃらないと思うので、やってみたいというか、ぜひ協力したいという会の方もいらっしゃるので、ぜひ今後、検討していただきたいと思いますので、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、国保をやるということではないのであれなのですが、平成２６年の国保そのものの中身にあまり入らないかもしれないのですが、例として国保が一番わかりやすかったのでそこから入りますが、平成２６年の資料を見ると、平成２６年は３７万３,７３２人、国保９万２,３９７人、後期高齢が３万５,４１２人ということだったのですけれども、これで１つ教えてほしいのは。","respondent":"高森国保医療年金課長","answer":"国保の加入者が平成２７年３月末で９万２,３９７人ですので、逆の話をすれば、区の人口からそれを引いたものが国保以外の加入者というような状況になるのかと思います。","voiceIndex":322,"id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問","question":"ずっと来て平成２６年度は４１億円余です。これはもちろん国民健康保険法があって、第７２条の３で特別会計に繰り入れなければならない。それはいいのですが、こういう税のあり方、税の公平性というのは、どこに考えられてやっているのかということを伺いたいです。これ、公平ですか。そうすると、それは法律があるからお金を出すのはいいのだけれども、税が公平ですか。それを一度お聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"確かに一般会計から国保会計に４１億円余り繰り入れしておるわけですが、委員ご指摘いただいたように、基盤安定のための軽減分、支援金分と、また職員給与費等の繰入れ等、それぞれあります。","voiceIndex":324,"id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺は、これは私はどこかで訴えていけばいいわけだけれども、やはりそういうことも考えながら税金を使うということは、ぜひやっていただきたい。ただ法律でこうだからこう、保険だから違うのではないか、そういうことはぜひ考えていただきたいと思いますので、これは要望にしておきます。だけど、それはそれで施設も結構いいのですとか、そういう肌の感覚をまず教えていただきたい。","respondent":"伊東生活福祉課長","answer":"ただ、大変申しわけございませんけれども、数につきましては押さえていないところでございまして、数十ぐらいあるのかというような感覚的な部分があります。","voiceIndex":326,"id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"施設のご紹介もぜひしていただきたかったのですが、私から言うと、多分住宅型有料老人ホームは、もちろん介護サービスも一緒にやっていこうという施設併用型ということもある。ここら辺のところがどういう形でこれを捉えているのかというところを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"在宅支援になりますので、まずは在宅介護支援センターでケアマネジメントを受けて、本当にそういう住宅が、費用の面もありますけれども、そういう住宅でいいのかどうか、ご家族はどうなのか、あと、最終的には本人はどうなのか。","voiceIndex":328,"id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は生活福祉で措置をされているところは、結構いいところが増えてきました。変な話、特養とか住所地特例で行くとか、そういうよりもケアハウスは例えば高いとか、お一人だったりするならば、介護とセットで医療連携も図れるのなら、住宅型有料老人ホームのあっ旋はありだと思うのだけれども、そこら辺のそれが危険だという話が出てくると、そうかと思うのだけれども、もう１回答弁をお願いします。","respondent":"永尾高齢者福祉課長","answer":"その基準にきちんと合致しているところであれば危険はないと思われるのですけれども、最近、いろいろ問題になっているというのは、例えば消防上の問題だとか、面積とか、介護職員のこととか、そういう面で設置基準が満たされていないで事故になるというケースが多いので。","voiceIndex":330,"id":"exchange-143"},{"speaker":"石田（秀）委員","kind":"質問","question":"だから私、あえて生活扶助から入ったのだ。多分、今、生活保護の方が生活扶助で行っているところは、多分、安全なところばかりだと思います。先ほど言った大手のところがやり出して、それでやっているところは、例えば私でも知っています。そういう連携がとれていれば、私はそこをご紹介することは、これからの高齢者対策の中でありだと思うのだけれども、再度答弁をお願いします。","respondent":"永尾高齢者福祉課長","answer":"高齢者部門と生活福祉課の部門と、きちんとケースワーカーとの間で連携をとりながら、設置基準のきちんと満たされているところであれば、そういうところをご紹介をするなどして、低所得者の方への住宅の配慮を進めていきたいと考えています。","voiceIndex":332,"id":"exchange-144"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひそれは私はありで、もちろんそのときに住所地特例を使うかどうかということがちょっとあるのだけれども、これがそういう高齢者の方に住所地特例を使うということはオーケーなのですか。現実、あっ旋とかをしていて、実例を今度つくっていこうとされているのか、そこら辺のところを最後にお願いします。","respondent":"永尾高齢者福祉課長","answer":"サービス付き高齢者住宅も同様に今年の４月から住所地特例が可能になっております。ですので、いろいろな施設があると思いますので、その施設の特徴、特色、また費用の面も加味しながら、生活福祉課、高齢者福祉課と連携していきたいと思います。","voiceIndex":334,"id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"あえて住宅型有料老人ホームと言いました。サ高住は、なかなか区内、どこかで今誘致をしていても、そんなに安くはないし、使い勝手がいいなら、だから私はあえて住宅型有料老人ホームと言っているのだけれども、低所得者対策にはそこが一番見合うのではないかと思っていますので、ぜひ検討していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":336,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"私は、１２９ページ、ひとり親家庭学習支援事業、１３６ページ、生活保護費、受験生チャレンジ支援貸付、そして１２３ページ、高齢福祉費についてお聞きしたいと思います。これは先ほど我が会派の委員が聞きましたが、もう一度、何のためにあるのか、やったのか、もう２年になるのですか。そして、生活保護費のほうで、受験生チャレンジ支援貸付、これについてもお聞かせください。","respondent":"廣田子ども家庭支援課長、伊東生活福祉課長","answer":"ひとり親家庭学習支援事業ですが、ひとり親家庭のお子様が無料で学習塾にはなかなか通いにくいということで、子どもたちを会議室のような、塾のような形で学生を中心とした若いボランティアに、お姉さん、お兄さんの立場で。受験生チャレンジのお問い合わせですけれども、こちらにつきましては、低所得者といいますか、生活保護にはなっていない方なのですけれども、塾代の補助ですとか、受験料を貸し付けるというものです。","voiceIndex":338,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"今、現実に子どもの貧困、そして家庭もなかなか正規社員になれなくて大変なところがあります。そして、その中で貧困の連鎖ということで、本来なら皆さま学校を出て、そして会社へ勤めて、ある程度の収入を得て、そしてまた子どもたちが成長していくというパターンがあります。それでこういう支援をしていると思うのですが、それでよろしいでしょうか。","respondent":"廣田子ども家庭支援課長、伊東生活福祉課長","answer":"経済的な面であったり、精神的な不安を取り除くという意味もありますけれども、学習環境がひとり親の家庭ですと、なかなか住居の問題でありますとか、親の就労の問題でありますとか。こちらの受験生チャレンジのところに関しまして、低所得者ということで、やはり一定の学力を持っていただくということでの意味合いで貸し付けて。","voiceIndex":341,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"ところが、結局、厚生労働省でこれをやらなければいけない。違うのではないですか、本筋として。だって、全国的にきちんとやっているところもあると思うのですが、教育現場として、国の中で厚生労働省、文部科学省、２つのところで、厚生労働省がわざわざやらなければいけないということは、私は恥ずかしくないのかと、また情けないかと思うのですが、ご見解はどうですか。お聞かせ願えますか。","respondent":"廣田子ども家庭支援課長、伊東生活福祉課長、村尾教育総合支援センター長","answer":"教育の見解についてとは別に、ひとり親家庭の子どもたちにとっては、同じ境遇の子どもたちが一緒にともに学ぶというところの意味合いもありますので。受験生チャレンジのほうの貸付ですけれども、こちらにつきましては、学校のほうということではなくて。ただ、さまざまな今の社会情勢を考えてみて、教育だけではなくて、さまざまな機関と連携を図りながら、子どもたちのよりよい学習環境。","voiceIndex":344,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"あまり深く入れないでお話ししますけれども、やはり私は、学習指導、教育というのは、やはりきちんと教育委員会で、私はやはり底辺の底上げということはやってほしいのです。次に、介護のほうなのですが、大都市の高齢化はますます進んでいるということで、介護現場では厳しい労働環境があり、週２日の深夜勤務、人手不足も含むと、本当に長時間労働になっております。","respondent":"永尾高齢者福祉課長","answer":"品川区では、質の確保ということで、そういう新しいスキルについても積極的に介護職員に対して福祉カレッジ等で指導しており、また、悩み等も各事業所、施設からも聞いておりますので、そういうことを継続していくことによって。","voiceIndex":348,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"早い人で２年、３年、長くても５年で辞めていっている。私もそんなに多くはないですけれども、いろいろ施設を見ていると、この間いたのに、早い人は３カ月、長くて６カ月、もっといても１年いるかというような、そんなような感じなのです。現場はそうやってどんどん辞めていくという現状を思ったら、今言ったスキルをつける、この人たちに指導するというのは不可能ではないですか。その辺をご答弁ください。","respondent":"永尾高齢者福祉課長","answer":"全国だと最近の調査によりますと１６.５％というのが報道でも出ていると思うのですけれども、品川区の場合だと、平均で１０.２６％です。中にはもっと１桁のところもあるという状況ですので、こういう状況が継続されるように区と連携していきたいというふうに思っております。","voiceIndex":350,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"現場では一生懸命やっていらっしゃる、それはわかります。ただ、勤めて２年、３年、４年、５年しても給料は上がらない。ほとんどの方が年収２５０万円から３００万円。これで税金を引かれてしまったら、どうやって暮らしていくのですか。毎年毎年人は辞めていく、何をする、どうする。どうぞ若い人材、優秀な人材、介護現場にたくさんいると思いますので、私は育ててあげていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":352,"id":"exchange-152"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１２５ページ、自立支援サービス、移動支援について、それから、１３５ページ、すまいるスクール運営費、これは学校との連携も含めてお伺いをしたいと思います。それから、１２９ページ、児童相談にかかわって、午前中から出ていますネウボラと赤ちゃん訪問事業のかかわりについてお伺いしたいと思います。時間があれば、少し冒険、遊び場にも触れたいと思います。","respondent":"中山障害者福祉課長","answer":"現在、移動支援を契約している事業者、３７社あるうち、特に区内を中心に移動支援のお願いをまずは移動支援の中で特に通学支援をやってもらえないかというお願いをしていくことが、まずは一番最初の手立てかと考えています。","voiceIndex":354,"id":"exchange-153"},{"speaker":"あべ委員","kind":"提案","question":"今、個別の相談は受けていらっしゃると思いますけれども、当事者や家族にとっても、やはり将来的な見通しがわかるとか、あるいは、当事者だけではなくて民間事業者やボランティアの方、あるいは教育や医療関係者など新設の分野の方にもいろいろなサービスを概要としてご理解いただくことはとても大切だと思いますので、ぜひご検討いただければと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"大きな概要というところでは、全ての区民の方にそちらのほうでお示しをさせていただいたところではあります。ホームページを活用して、例えば区内の社会資源マップであるとかというのは、１つ検討はできるかというふうに思っております。","voiceIndex":356,"id":"exchange-154"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ広げていただきたいと思います。すまいるスクールの質問に移りたいと思います。長年要望のあったすまいるスクールの時間延長が実現することは、私は現在の家庭の実態を踏まえたもので歓迎したいと考えています。どのようなプロセスを経てこのようなことになったのか、改めて教えてください。","respondent":"伊崎子ども育成課長","answer":"しかしながら、この間の検討ですけれども、事件が多発しているということに対する親の不安感、これに対して区はどうやってこたえていくかというところをどのように政策としてあらわしていくか、そこの点の検討を進めてまいりまして、なおかつ、いろいろな声を聞きながら。","voiceIndex":358,"id":"exchange-155"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと聞き方が曖昧だったかもしれない。私は、時系列でお伺いしたいと思ったのです。教育委員会から移管したときに伺ったときには、明解にやらないということだったのですけれども、例えば、検討のための組織がいつごろできて、その中でどう決まったというような、この間とかというのではなくて、時間で教えていただければと思います。端的にお願いします。","respondent":"伊崎子ども育成課長","answer":"すまいるスクールが子ども未来部に移管をされてから検討にかかっております。","voiceIndex":360,"id":"exchange-156"},{"speaker":"あべ委員","kind":"質問","question":"学校関係者にとって、この間、先ほどの質問の中でも、例えば保護者や職員の方々とのニーズ調査などはどうだったのかというお話も出てきましたけれども、今回のことは学校関係者にとってもかなり唐突に受けとめられていたように聞いております。学校長等とのすり合わせというのは、いつごろからどのように行っていたかということをお伺いしたいと思います。","respondent":"伊崎子ども育成課長","answer":"学校長との検討ですけれども、８月になりましてから検討は行っております。","voiceIndex":362,"id":"exchange-157"},{"speaker":"あべ委員","kind":"質問","question":"今年の８月になってから決定事項を伝えるということで、私が聞いた限りでは、学校側は今回のことについて、むしろ困惑したような声を聞いております。ぜひ子ども未来部、そして教育委員会双方のすまいるスクールに対する見解と意識のすり合わせの方策についてお伺いしたいと思います。","respondent":"伊崎子ども育成課長、品川庶務課長","answer":"その後ですが、何回か校長会との意見を交わしながら、またこの後もきちんといただいた意見に関しては検討したものを返しながら、４月に向けて進んでいこうと考えています。このすまいるスクールの件に関しましては、当然、子ども未来部と教育委員会事務局が連携して進めていく、そういうつもりです。","voiceIndex":364,"id":"exchange-158"},{"speaker":"あべ委員","kind":"質問・要望","question":"そのつもりと言いながら、そのようになっていないのではないかということを今るる時間をかけながら話して、その上でのご見解を求めたのであって、うまくいっていて、全然課題がないと思っていたらこんな質問はしないわけです。これはご答弁を求めても、結局、抽象論になってしまいそうなので、ぜひ関係の方々には、この事業のことだけではなくて、ぜひ考えていただきたいと思います。教えてください。","respondent":"太田品川保健センター所長","answer":"したがって、別の人になりますが、もちろんハイリスクの方に関しては、面接、電話相談、訪問は常勤が行いますし、希少職種ですので難しいところもありますが、要支援の方はネウボラ相談員がずっと支援していっておりますので、助産師を配置できれば。","voiceIndex":367,"id":"exchange-159"},{"speaker":"あべ委員","kind":"質問","question":"途中で足した事業ですので、いきなりは難しいかもしれないですけれども、やはり当事者にとって一番安心できるやり方、人繰りも含めて、ぜひ考えていただいて、本当の意味での切れ目のない支援ということを試行していただければと思いますが、いかがでしょうか。","respondent":"太田品川保健センター所長","answer":"できるだけ同じ方が……。","voiceIndex":369,"id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、国民健康保険について伺いたいと思います。先ほど、平成２７年度で９万２,３９７人が国民健康保険に加入しているということだったのですけれども、もうちょっと数字のところでお聞きしたいと思うのですが、収納率、滞納件数、あと差押件数を２０１４年と２０１５年で教えていただきたいと思います。","respondent":"高森国保医療年金課長","answer":"平成２５年の収納率ですが、７６.３１％、平成２６年が７８.１％です。それと、差押の件数は、平成２６年度が７４４件、平成２５年が３９４件です。","voiceIndex":372,"id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"滞納世帯件数も伺ったので、そこもお聞かせいただきたいと思います。それで、２００５年ぐらいから厚生労働省からは全国の自治体に収納率向上の取り組み強化を求める発令が出されてきたと思うのですけれども、区はそれに基づいて取り組んできたのか、収納率も少しですけれども上がっているというところでは、どのように取り組まれてきたのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"区役所においでいただいた方に口座振替のキャンペーンなども実施しておりまして、口座振替の加入率を高めることによりまして、必然的に収納率の向上を図っていく。さまざまな形で対応しています。","voiceIndex":374,"id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"確認","question":"でも、この差押件数が平成２６年は７４４件ということで、ちょっと大きい数字にびっくりしたのですけれども、今、緩やかに取り組んできたということだったのですけれども、やはりほかの地域では、強権的な徴収をしているという実態もありまして、品川区ではそういったことはないのか確認させてください。","respondent":"高森国保医療年金課長","answer":"そのようなことは断じてございません。","voiceIndex":376,"id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問","question":"一般財源１３億５,０００万円の投入を４年間でゼロにすると、今年はその２年目の年ですので、既に値上げがされています。高額療養費の一般財源投入ゼロになるその翌年、２０１８年（平成３０年）には、国保の都道府県単位化が進んでいく、そこに向けているということなのですけれども、この都道府県単位化にすることで、保険料がさらに引き上がっていくと思うのですけれども、区の認識はいかがでしょうか。","respondent":"高森国保医療年金課長","answer":"１年９,０００円程度ということで、毎年２,２００円の保険料の加入者の方の負担という形で進んでおるわけですけれども、平成３０年度の都道府県化は都道府県化として、現在、東京都と特別区において、さまざまな形で検討を進め始めたところということでございまして。","voiceIndex":378,"id":"exchange-164"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも、この分賦金が１００％完納が都から強く求められてくるわけです。なので、区市町村がかぶるか、被保険者が保険料として値上げをかぶるか、そうしなければ１００％納付ができないというような状況に都道府県単位化になれば、こういったことも強いられてくるので、やはり保険料がさらに値上げされていく仕組みになっているのではないかと思うのですけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"そのようなご意見をお持ちなのは存じておりますけれども、東京都のほうでは、平成２７年度の目標徴収率を現年度分定めていると申し上げましたけれども、平成２７年度は８７.７４％というふうな目標の数値になっておりまして、実はこの目標の数値を達成しているところは。","voiceIndex":380,"id":"exchange-165"},{"speaker":"石田（ち）委員","kind":"質問","question":"１００％などはないと思うということですけれども、でも、今の数字を聞いただけでも大変になってくるのではないかというふうに思います。この特例措置は後期高齢者医療制度のときに反対の声に押されて設けられた軽減措置です。廃止されることで、２倍から１０倍の負担増を強いられていくというふうに言われています。区内で区民の方でこの特例措置の対象者は何人いるのか教えてください。","respondent":"高森国保医療年金課長","answer":"後期高齢における均等割の軽減の方が１万８,４２６人、所得割の軽減の方が４,００７人というふうにここには出ております。","voiceIndex":382,"id":"exchange-166"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年金は下げられて、働く世代の実質賃金もマイナスの連続なわけです。この間、私たちも国民健康保険料の軽減、引き下げを求めてきているわけですけれども、やはり区民への保険料が高いとう認識、この間、課長には伺ってきているのですけれども、高いという認識はないというのが姿勢なわけですが、ぜひ区民にとって大きな負担である、高くて払えないという認識を持っていただきたいと思うのです。","respondent":"高森国保医療年金課長","answer":"薬剤につきましても、実質的に、昨年度、平成２５年度と比べましても、一定の割合で歳出の部分が平成２４年から平成２６年を見ても伸びている状況ですので、こういうふうなものをやはり加入されている方に負担をお願いするというのは、これは当たり前のことでございまして。","voiceIndex":384,"id":"exchange-167"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国民健康保険料の高騰する大きな原因としては、国の負担が削減されていく。そして、やはり加入者の貧困化、この２つが大きい原因だと思います。本当に非正規で社会保険にも入れないという状況で国保に入っても高過ぎて払えない。そして必要であれば一般財源はしっかりと投入していく、こういったことを進めていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"確かに前年度に比べて今年は収入が少ないとか、かなり落ちたとか、いろいろな方がいらっしゃいます。そういうふうな方につきましては、ぜひともご相談いただいて、収入がない方に対して払え払えというふうなことは一切言っておりませんので、よろしくお願いしたいと思います。","voiceIndex":386,"id":"exchange-168"},{"speaker":"浅野委員","kind":"質問・要望","question":"最初に、１９５ページ、２０４ページの人間ドック助成事業、こちらについてお伺いします。そしてもう１つの項目ですけれども、１７９ページ、国民健康保険事業について質問します。そして、そのときに特定健診保健指導の受診率向上に力を入れるように要望しました。そういう制度がスタートするということだったですけれども、この制度は今どうなっているのか教えてください。","respondent":"高森国保医療年金課長","answer":"人間ドックの助成ですガ、確かに委員おっしゃるとおり、後期高齢におきましては６８件の助成をしています。国保につきましては１９５件ですが、助成をしています。それと、すみません、後ろのほうの質問がちょっと聞こえなかったので、もう一度よろしいでしょうか。すみません。","voiceIndex":389,"id":"exchange-169"},{"speaker":"浅野委員","kind":"質問","question":"その上で伺いますけれども、先ほど出ました収納状況です、国民健康保険料、こちらは平成２４年が８５.２７％とありますけれども、目標としまして、これが平成２６年度が７８.４３％に下がっています。国の方の目標は８７.７４％が平成２７年度、平成２８年度が８８.９６％になっています。このような状況の中で、今後はどのような形で進めていくのか、国保としての取り組みについて教えてください。","respondent":"高森国保医療年金課長","answer":"確かに前段の１点目の国保の健康対策に競争制というふうな形で、確かにおっしゃるように成績評価の指標を盛り込むというふうな形で前倒しで実施するというふうな新聞記事を私も拝見させていただきました。","voiceIndex":391,"id":"exchange-170"},{"speaker":"浅野委員","kind":"質問","question":"数字、私のほうで間違えたかもしれませんが、そういう意味では、まだ下がっていないということであれば、まだ可能性はあるのかと思いますけれども、これが実際に施行されるというふうになりますと、かなり頑張っていかないとマイナスが出てしまうような気がしてならないわけでありまして、そういう意味では、これからの取り組み、収納率のアップ、そしてまたジェネリック医薬品の使用割合ですとか。","respondent":"高森国保医療年金課長","answer":"ジェネリックの医薬品の差額数値ですが、平成２６年度におきまして、ちょっと数字を固めてまいりました。","voiceIndex":393,"id":"exchange-171"},{"speaker":"浅野委員","kind":"質問","question":"ジェネリックのほうは１０１.１％ということで、少しずつ進んでいるということだと思います。ここの部分につきましても、しっかりとやっていかなければならないということと、あと、この成績評価の指標の中で、糖尿病の重症化予防というものがあるのですけれども、これはどのような指標が使われるのか、今まで区として数値的なものを出されたことがあるのか教えてください。","respondent":"高森国保医療年金課長","answer":"国保の基本健診におきまして、例えば生活習慣病という中には、糖尿病の予備軍だとか、または高血圧の方、高血圧で若干高めの方とか、だんだん高血圧については年齢を重ねてまいりますと、高血圧の推移も上がっていくというのが一般的な考え方ですので。","voiceIndex":395,"id":"exchange-172"},{"speaker":"浅野委員","kind":"質問","question":"いろいろ数字を伺っているわけでありますけれども、先ほどお伺いした品川区の収納状況ですけれども、ほかの市区町村と比べてどのレベルにあるのかということを教えてください。特定健診の受診率、これもどのぐらいのレベルなのか、平均的なのか、それともかなりいい線を行っているのかということについて教えてください。","respondent":"高森国保医療年金課長","answer":"収納率のほうは、現年度と滞納繰越分を合わせまして、平成２６年度は２３区の中では４番目の高い率というふうに確認をしています。国保の基本健診の受診率ですが、平成２５年度では２３区の中の順位が出ておりまして、品川区は３８.５０％で、２３区の順位としては１７位です。","voiceIndex":397,"id":"exchange-173"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１２０ページの社会福祉費全般、１３３ページ、ぷりすくーる西五反田運営費について伺います。初めに、ユニバーサルデザインワークショップという観点から、平成２６年度、ユニバーサルデザイン、おたがいさま運動研修会、この品川区の事例が東京都のほうの資料にも事例紹介で出ていました。回数が、このモデル事業的なものだから５回なのか、今後どうなっていくのかお知らせください。","respondent":"大串福祉計画課長","answer":"参加人数としては延べ８６人といったところです。それから、予算の関係です。昨年、平成２６年度の予算は、そういった啓発活動等々含めて４６３万６,０００円の予算を計上しています。","voiceIndex":400,"id":"exchange-174","title":"議員研修会の内容と所要時間"},{"speaker":"渡辺委員","kind":"質問","question":"実感という中で、１つ伺いたいのが、まず、防災訓練等で車椅子を試乗すると、どの年代の方も非常に何か感じるものがあるというのがよく見受けられます。子どもへのユニバーサルデザイン教育が、平成２６年度、４区で展開されている。福祉のまちづくりサポーター養成も３区で展開されている。残り２つが、今挙げました地域の住民対象のワークショップ、これは４区で展開されている１つが品川である。","respondent":"大串福祉計画課長","answer":"今後ですけれども、今、委員からご紹介いただいたような体験学習の機会に含めまして、今年度はＤＶＤを制作しておりまして、障害をお持ちの方への接し方ですとか、障害をお持ちの方とのふれあい方といったものをつくりまして、来年以降は学校等々と連携をしながら。","voiceIndex":402,"id":"exchange-175"},{"speaker":"渡辺委員","kind":"質問","question":"続きまして、ぷりすくーるのことを伺います。ぷりすくーるをはじめとして、幼保連携型認定こども園が区の子ども・子育て計画の中でもいろいろな理念が明記されています。この辺の進むべき方向性とポイント、定義はいろいろあるかと思うのです。でも、やはり保護者目線、家庭の目線、子どもの目線で絞っていくと何かと思ったのです。この辺の進むべき方向とポイントを伺いたいと思います。","respondent":"竹田保育課長","answer":"特にぷりすくーるは、子ども中心の保育を目指し続けるということで、一人一人を大切に個性を生かす保育、あるいは心身の発達を援助する保育を実施していくという方針のもとに、今、鋭意頑張っているところです。","voiceIndex":404,"id":"exchange-176"},{"speaker":"渡辺委員","kind":"質問","question":"ほかの場面でも各委員からもこのぷりすくーるへの評価があり、それは総じて先駆的な取り組みの評価がなされているというふうに捉えています。その中で１つ伺いたいのが、１０年たちます、ぷりすくーるという施設、あるいは取り組み、視察等が一時期多かったやに聞いています。これも評価の１つだと思います。この２点の考え方を教えてください。","respondent":"竹田保育課長","answer":"特色ある教育ですが、伝統文化の継承事業、あるいは音楽リズム能力の向上、国際理解教育等、多方面にわたりまして生きる力を身につけ、心身を健全に育むという環境整備に努めているところです。","voiceIndex":406,"id":"exchange-177"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと、人材の確保のところ、これは本日の我が会派の鈴木博委員からも、保育士の確保とか維持というもの、あと質の担保、この辺はやはりあわせて要望したいという思いから伺っていきます。それについて、やはり１つのチャレンジする、文字どおりこの事業名がチャレンジプログラムというように、チャレンジに対する支援をどうお考えか。この辺の考え方を教えてください。","respondent":"竹田保育課長","answer":"チャレンジする保育というところですが、いろいろな事業に取り組んでいるところなのですが、意外に実施側が考えていたよりも保護者の方が想定外の反応を示すということもあります。","voiceIndex":408,"id":"exchange-178"},{"speaker":"渡辺委員","kind":"意見","question":"そのことをお伝えすると同時に、この１０年はいろいろな方がかかわり、すごくノウハウが蓄積されてきている。この１０年のノウハウをためて、それをどう活かすかという中で、これまでも恐らく全区的に他の幼児教育施設、機関で活かされていると思います。やはりこの節目の中で大きく何か活かせるのではないかという思いがあるので、その辺が１つと、もう１つ、先ほど、チャレンジという言葉がありました。","respondent":"竹田保育課長","answer":"今後もさらに充実を図っていきたいと考えております。それから、人事交流というお話ですけれども、十分どういったことが可能なのかというふうに検討させていただいて、今後の適切な人材育成等に努めてまいりたいと考えております。","voiceIndex":410,"id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":122705,"voices":412}},{"id":"h27-20151007-4","meetingId":"h27-c-settlement","date":"2015年10月7日","dateIso":"2015-10-07","committee":"決算特別委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２６年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ちょっと、今の説明に質疑があるのですけれど、よろしいでしょうか。そうしましたら、この数字は直らなくてはおかしいのではないのですか。このままで進んでしまいますと、この数字がこのまま残ってしまいますけれども、東京さくらツーリストが不正を働いて返還した部分は支出ではないので、これはどういうふうに取り扱うようになっているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"平成２６年度の決算を今、審議しようという中に、ここに書いてある数字が違っていたら審査できないですよ。間違いがあったら訂正するのが筋ではないのですか。何で訂正しないのですかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"返還されているのですよね。お金は受け取っているのですよね。この説明をしてください。返還されたのなら、この数字を訂正しなくてはおかしいでしょうということです。これがこのまま動いてしまったら、我々が審議しなかったら、この数字がこのまま残ってしまうのですから。これは議事進行についてですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"どこそこの款で訂正がありましたという小さな紙が配られていますけれど、そういう形で訂正を先にすべきではないのですか。実際にお金が、返してもらっていたら、この決算金額、２５５万５,０００円を実際に支出したということになっていて、もう、この決算が始まる前に返還されているという発表があるのですから、訂正ということで、その数字をしっかりここに載せるべきではないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、成果報告書の１４６ページの雨水利用タンク設置助成事業、１４５ページのリサイクルショップ運営費についてお伺いします。雨水利用タンク設置助成事業ですが、水の有効活用ということだと思いますけれども、助成事業の内容を教えてください。","respondent":"和田河川下水道課長","answer":"雨水利用タンクの助成の内容ですが、品川区内に雨水利用タンクを設置していただける方を対象に、設置費用の２分の１、タンク１個につき５万円を限度に助成するものです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この雨水タンクに貯水した水の活用方法、例えば庭の草木への水やり、雨水を水やりに使うとか、庭や道路の打ち水、そして有事のときの非常用の水として活用ができて有効だと思いますけれども、件数だけ見ますと魅力がないのかなと私は判断しましたが、その辺のことはいかがでしょうか。","respondent":"和田河川下水道課長","answer":"例年、２０件前後の申請があります。現在、平成２７年度につきましては、１０月１日現在で１１件の申請をいただいております。そういうことで、評判は好評ということで区は認識しています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひ今後も、より一層のＰＲをしていただき、すばらしい事業だと私は思っていますので、ぜひよろしくお願いいたします。続きまして、リサイクルショップ運営費についてお伺いいたします。リサイクルショップ、リボンの運営は区が支援しておりますけれども、その運営内容と、２店舗で２,０７５万円ですけれども、それぞれの各店舗の運営費を教えてください。","respondent":"小林品川区清掃事務所長","answer":"区のかかわりといたしましては、リユース事業の基幹になる店舗として、できるだけ区民の参加をもって運営していただくことを目的に、区はあくまでも支援に徹するということで、この８００万円の主な支出内容といたしましては、建物、旗の台の管理業務関係の委託。","voiceIndex":23,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"旗の台近辺でも個人事業のリサイクルショップが今現在、何店舗がありまして、利用者の皆様も選択肢が広がってきております。これは旗の台なのですけれども、私が見る限り減少傾向が見受けられますけれども、この支援は今後も続けていかれるのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"その年代を、より広範に支持されるような工夫をしていただけるようにご相談をしながら、区のリユース事業の基幹事業として今後も支援を続けていきたいと考えております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これはきちんと運営ができていれば、問題は私はないと思っています。ぜひ区としても、これからも支援をよろしくお願いいたします。時間がもう少しありますので、もう一点、質問をします。１４６ページの区有施設等雨水利用タンク整備事業についてお伺いします。この整備事業は、具体的にどういったところに設置されている、そして事業の内容をお知らせください。","respondent":"和田河川下水道課長","answer":"区有施設等の雨水利用タンクの整備事業ですけれども、先ほどもお話ししました個人のお宅の雨水利用タンクの助成のＰＲのために、区有施設、具体的には保育園、幼稚園、それから小学校、中学校などに雨水利用タンクを設置するものです。","voiceIndex":27,"id":"exchange-009"},{"speaker":"新妻委員","kind":"提案","question":"私のほうから、１３９ページ、各種がん検診、そして高橋委員と重なりますが、１４５ページのリサイクルショップ、リボンについて、質問が重ならないようにお伺いしたいと思います。１０月は乳がん月間でもあり、がんで亡くなる方が一人でも減るような思いで質問をいたします。会派といたしましても、かねてより、がん検診の受診率アップのためにさまざま提案をし、拡充もしていただいております。","respondent":"川島健康課長","answer":"近年の主ながん検診の受診率の状況ですが、平成２５年度と平成２６年度をお伝えします。胃がんが、平成２５年度が３.４％だったものが、平成２６年度に３.１％、少し下がっております。それから子宮がん検診が、２４.８％だったものが２５.８％と少し上昇しています。","voiceIndex":31,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"この数字、他区と比べるとどのような状況なのか。なかなか分母等もはっきりしていない中で難しいかと思うのですが、東京の中での位置と、また品川区はこの受診率に関してどのように受けとめていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"川島健康課長","answer":"国が定める目標というのが５０％と非常に高いものです。胃と肺と大腸については当面４０％ということなのですが、まだまだその目標が高いということなので、引き続き事業の改善に向けて努力をしていく必要があると考えています。","voiceIndex":33,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"私のところに聞こえる声の中で、女性の方のご要望ですけれども、なかなかやっぱり行きたいけれども行けない現状があるという中で、子どもの託児ルームがあると受けやすいとか、また夜間に受けられる、この夜間の時間を拡大してもらえるといいという声もあります。働く方からは、男性、女性問わずですけれども、品川区内ではなく働いている先、区外でも受けたいというご要望もいただいております。","respondent":"川島健康課長","answer":"私どもも、なるべく検診を受けやすくするという、環境を整えるというのは非常に重要だというふうな認識でおりますが、まず一つ、受け手の問題ということで、夜間の部分につきましては、夜間、開業している診療所の問題ですね。","voiceIndex":35,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"国のほうで、コール・リコールということで、検診を受けましょうという電話をするという運動があります。品川区としての現状をお聞かせいただきたいと思います。","respondent":"川島健康課長","answer":"つながった場合も不審がられまして、かなり電話の説明が長引くといったことがございまして、やはり電話というのは、今いろいろな、何というのでしょう、押し売りですとか、いろいろな問題になっているようなものがありますので。","voiceIndex":37,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"この質問は終わります。続いてリサイクルショップです。ただいま、運営の状況はお伺いさせていただきましたので、そのことは割愛いたします。ＮＰＯ法人に運営を委託されているということで、利益を求めないというところですけれども、特に私も、このリボンの会員になっております。区の負担金ではなく、売上をどのような形で使われているのかという内訳を教えていただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"この４２％等を集計した売上ですけれど、例えば平成２６年度の営業収入といたしましては、年間２,９５６万９,０００円、３,０００万円弱の金額になっておりまして、全ての支出項目について見せていただいておりませんが、あの店舗の規模ですと。","voiceIndex":39,"id":"exchange-014"},{"speaker":"新妻委員","kind":"意見","question":"これからも長く利用していただくために、また対策をさまざま区からも助言をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"１４８ページの産業振興事業助成金の品川区商店街連合会について、１５１ページ、空き店舗解消支援事業助成について、それぞれ区商連事務局の職員待遇改善への支援と、空き店舗解消支援を伺いたいと思います。区にも寄せられていると思いますけれども、この確認と、どのように受けとめていらっしゃるのか伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"こうしたことについては、毎年、予算編成などで区商連の意向を十分、区としても聞き取りをしながら、活動の支援、あるいは区に代わって業務をやっていただくというような関係にあるものです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"区商連については、おっしゃるとおり公益性が高く重要な役割があると。現在の制度上、現状の仕組みの範囲で可能なのか、それとも新しい支援が必要なのか、形は様々だと思いますけれども、何か必要な手だてについて、区商連ともよく連携して知恵を出せないものかと思うのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"特に区のほうでは、先ほどの繰り返しになりますけれども、予算編成の中でいろいろな要望をお聞きして、年度ごとに対応しているというようなことでございまして、運営に厳しい状況だというような切実な声というのは、区のほうとしては、そこまでには至っていないというか。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、空き店舗解消支援事業ですけれども、こちらは商店街が企画する事業でなくてもよいのかという確認と、個人の新規開設、開店も対象なのか、ちょっと伺いたいのと、あと現状の内容について、住宅部分と店舗部分の分離や、これに係るトイレや出入り口の工事への一部助成ということですけれども、対象工事を広げるなど、事業の拡大について、今どのようにお考えになっているのか伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"その中の一つで、平成２５年度でございましたけれども、委員おっしゃった生鮮三品を取り扱っている商店街の支援ということで、この年度に生鮮三品については力を入れて取り組んだというようなことです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"個店支援につながっていく支援に力を入れていきたい。例えば工事であれば、ダフトだったり排水だったり内装・外装・ガス管の工事など、いろいろ検討していただけたらと思うのですけれども、この点いかがでしょうかということです。こういう新しい活力が地域や商店街に加わっていくことは、住民にとっても、またまちのにぎわいにとっても、とても大事ではないのかなと思いますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"商店街が企画・実施する空き店舗の活用という意味では、商売を始めていただく初年度こそ発生する内装の関係ですとかハード経費、それからお店のＰＲなどというようなことで対応させていただいているようなところです。","voiceIndex":49,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"私がやっぱり踏み込んでいただきたいなと思うのは、こうした様々な融資の制度と共に、支援をつくっていくべきではないのかなと思うのです。買い物がしにくい地域が生まれておりますので、こうした状況もよく把握していただきたいと思いますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"行政が行う産業支援ですので、一つそこに広域的な観点などのバランスなどを踏まえて事業展開をしていくというような考えに基づいてやってまいりたいと思ってあります。","voiceIndex":51,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"成果報告書の１４０ページのビル衛生管理について伺いたいと思います。監視件数とありますけれども、この項目で監視されているビルについて伺いたいと思います。どういった項目を監視しているのかも伺いたいと思います。","respondent":"高山生活衛生課長","answer":"ビル衛生管理のお尋ねです。こちらは、多数の方々が使用します建築物の衛生の確保を図る目的から、３,０００m2以上の大規模な建築物を対象に検査を行うものです。","voiceIndex":54,"id":"exchange-021"},{"speaker":"松永委員","kind":"意見","question":"そうしますと、平成２５年度の監視件数が２７件で１８万２,８６０円で、平成２６年度の決算では１８件で４６万９,４７３円と計上されておりますけれども、この件数が減っていて決算額が上がっている理由についてお答えをお願いいたします。","respondent":"高山生活衛生課長","answer":"平成２５年度の比較で、監視件数が少ない割には執行率が高いというところのお話ですが、こちらにつきましては、実は先ほど申しました空気環境の測定に当たりまして、デジタル粉じん計という機器を用いまして測定しているのですが、こちらを新規に購入しました関係で。","voiceIndex":56,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"わかりました。続きまして、監視員というのはどのような形で選ばれているのか。それで何人体制、例えばビル１棟で何人というのは決まっているのでしょうか。改めて伺いたいと思います。","respondent":"高山生活衛生課長","answer":"ビル管理に当たりましては、環境衛生監視員という専門職の職員がおりまして、大学で、薬学であるとか、あるいは農芸科学などの理科系の学問を修めました専門職が、衛生監視の職種で監視を行っているものでございまして。","voiceIndex":58,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"初歩的な質問なのですが、ビル管理のビルというのは、例えばどういったものになるのか伺いたいと思います。","respondent":"高山生活衛生課長","answer":"例えば、特定用途ということで１１種類ございまして、例えば興行場でありますとか百貨店、集会場、図書館などが対象となるのですが、具体な名称で申しますと、例えば品川区の本庁舎でありますとか、あるいは伊藤学園などの学校施設、それから閉鎖されましたが。","voiceIndex":60,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"わかりました。次に１４３ページの低公害車買換え支援事業について伺いたいと思います。平成２６年度予算では約１９６万円、平成２６年度決算では約９３万円となっておりますが、１台につき約どのぐらいの補助が出ているのか伺いたいと思います。予算額と決算額との差が約２倍違うのですが、その理由についても伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"しかしながら、こちら、低公害車につきましては、地球温暖化対策、また大気汚染対策、こちら東京都のディーゼル車規制が根本的なところになっておりますので、そちらにつきましてもまた引き続き実施していきたいと考えています。","voiceIndex":62,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"この低公害車について伺いたいと思いますが、もしかしたら周知が少し足りないということだったのですけれども、もしくは中小企業にあっても対象の車が合わないのかもしれませんが、例えば低公害車の条件となる車について伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらの低公害車買換え支援事業の対象となる車ですけれども、こちらにつきましては、東京都の融資あっせんを受けました車の利子については東京都が２分の１を補助しておりますけれども、それと、あと信用保証料について３分の２、東京都が補助しております。","voiceIndex":64,"id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"車種などはあれなのですね、わかりました。最後に、やはりそういった中で、メーカーとの連携も必要となってくるとは思うのですけれども、その辺はいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"実際、こちらの車種につきましてですけれども、例えば電気自動車であたり、燃料電池車であったり、またプラグインハイブリッドなどの車種となっております。具体的な車種名は差し控えしますけれども、そのようなものとなっています。","voiceIndex":66,"id":"exchange-027"},{"speaker":"松永委員","kind":"質問","question":"１４４ページの水質調査について伺いたいと思います。平成２５年度の決算では１１カ所に対し約６１６万円、平成２６年度では同じく１１カ所で約３５９万円となっておりますが、またこの同じ場所を水質調査を行い約半分の金額になっていますが、それについて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらは毎年度、入札でございまして、今回の業者に関しましては半分程度の金額となっております。","voiceIndex":68,"id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"調査内容は変わっていないということなのでしょうか。","respondent":"三ツ橋環境課長","answer":"実際、こちらの検査の内容につきましては、先ほど委員おっしゃられましたように、１１地点、また表層・下層につきまして、実際に同様の検査をしております。","voiceIndex":70,"id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、例えば平成２５年度と平成２６年度の調査結果についてわかりましたら伺いたい。１１カ所もあるので、立会川、勝島運河あたりでお願いしたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらの基準は実際には１０以下というものでございまして、こちらにつきましては１０以下です。平成２６年度につきましても１.９となっておりますので、同様のものとなっています。","voiceIndex":72,"id":"exchange-030"},{"speaker":"松永委員","kind":"質問","question":"今後とも調査をよろしくお願いします。少し時間がありますので、１４６ページの資源再商品化経費について伺いたいと思います。資源になる缶、瓶、ペットボトル、プラスチック、古紙についてですが、どのような流れで商品になるのか、簡単でいいので教えてください。主に約９４０万円は何に使われているのか、あわせて伺います。","respondent":"小林品川区清掃事務所長","answer":"ただし、プラスチック製容器包装だけは、資源化センターでの処理能力を超えていて対応不能ですので、従前、東日本東京資源循環センターに委託いたしまして、そこで同種の選別、圧縮、梱包等を行った後、エム・エム・プラスチック等を通して再商品化をしています。","voiceIndex":74,"id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、回収した資源についてですけれども、年間どれぐらいの財源になっているのでしょうか、伺いたいと思います。もしわかりましたら、缶、瓶、ペットボトル、プラスチック、古紙なのですが、年間どのぐらいの財源になっているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"大変お手数ですけれども、お手元の資料９８ページをご覧いただきたいと思います。リサイクル資源売払収入は、結果的にトータルで２億３,６００万円余になっております。","voiceIndex":76,"id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"今後とも環境のためにしっかりとよろしくお願いいたします。最後に一点だけなのですが、１４９ページのしながわ巡りアプリ作製経費について伺いたいと思います。それで、今現在、言語についてですが、今、タイ人がこちらのほうに増えている、観光しに来るということなのですが、今後、タイ語について取り入れる予定はあるのか、伺いたいと思います。","respondent":"間部文化観光課長","answer":"タイ語については検討してまいります。","voiceIndex":78,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"１３７ページの衛生統計調査費なのですが、ここにいろいろな調査が並んでいるのですけれども、具体的にどんな調査か教えてください。","respondent":"高山生活衛生課長","answer":"その他、一つ一つ申し上げるのもあれかと思いますが。もう一つ申しますと、例えば国民健康栄養調査などにつきましては、健康増進法などに基づく調査項目で、国民の健康の増進を総合的に推進するための基礎資料とする、そういった統計内容です。","voiceIndex":81,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"調査はまず大事です。そういう意味において、この調査の流れですね。ここで調査をして所管の担当の課に行って、どういう形でこの調査を活かしているのか教えていただけますか。","respondent":"柏原企画調整課長","answer":"人口の調査、こちらのほうの衛生部門でやっている調査、それから企画部門でもやっている調査がありますけれども、そういった調査を、例えば今回、人口推計という形でやりましたけれども、まず衛生の調査、それから基本データを企画部門にいただいたり。","voiceIndex":83,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"すばらしいですね、調査を活かしていてね。これはすごく大事だと思うのですけれども。それで課長、自分で何かピックアップして栄養調査も出していたじゃないですか。この栄養調査はどこの課でどういうふうに、何というのですか、活かされているのか教えていただけますか。","respondent":"高山生活衛生課長","answer":"こちらのほうは、国の、最終的には厚生統計行政上の統計処理を経た上で、あまねく国民の衛生統計上に活用されるということで、品川区内におきましては、そういった調査区を設けまして、例えば身長であるとか胸囲であるとか血圧などの調査にご協力いただいた統計上の数値を。","voiceIndex":85,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"それと、次が１３９ページの各種がん検診なのですけれども、受診率のことはわかりました。それで課長のご答弁で、これからも受診率の向上のために頑張りますというお話が出たのですけれども、頑張るためには、なぜ受診率が思っている数字までいかないのかという分析が大事だと思うのですけれども、受診率があまり上がらない理由というのは区としてどう考えているのでしょうか。","respondent":"川島健康課長","answer":"検査機関のほうも、数字はちょっと１年でならすとどうなるかはわからないのですけれども、かなり多い予約が入っているという話も聞いておりますので、やはり啓発の重要性というのはあるのですが、多分、自分はがんにかからないですとか。","voiceIndex":87,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"本当に課長がおっしゃるとおりなのです。私も、がんにはならないだろうと思っていました。がんになっていないですよ。ならないだろうと思っています。安心した。なぜかといいますと、再検査までして早期発見という形にすれば、長い人生を考えて、行政のコストを考えると、早期発見・早期治療にしたほうがコスト的には安いのではないかなという思いが出まして、その辺についてはいかがでしょうか。","respondent":"川島健康課長","answer":"我々自治体のやっておりますがんの検診というのは、広くスクリーニングの意味で、異常を発見しまして、その異常がある方は医療につなげるというような意味合いでやっているものですので、これからその辺の助成ですとか、そういった可能性が全くないというわけではないのですが。","voiceIndex":89,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"次に産業のほうを伺うのですけれど、逆に今度は温かい、他区の方でもいいですよというすばらしい施策についてお伺いしたいと思うのですけれども、１５２ページの創業支援についてお伺いしたいのですけれども、以前からこの事業についてお伺いしているのですが、費用対効果というのをまず判断するのは難しいですよね。創業支援もそうじゃないですか。はい、他区に行きます。この辺についてはいかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"そういったことで、引き続き、区内のほうで創業・起業してもらえるような形で支援を続けていくというような形で支援をしてまいりたいと考えています。","voiceIndex":91,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、品川区のために、品川区民の税金を使ってもこうなるのですというのはないわけじゃないですか。私は思っている。マネジャーもすごいじゃないですか。誇りを持ってやってくださっているじゃないですか。そういう形に、ぜひぜひ持っていっていただきたいと思うのですけれども、そのぐらいに対しては、そのぐらいと言ってはいけませんね、大事な、そういうことに関してはいかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"創業した後も、区内に限らずいろいろなネットワーク、連携をその後も持ちまして、いろいろやっていくような形で連携をとっておりますので、そういった形での支援になります。","voiceIndex":93,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"１３９ページ、１項２目、保健衛生費予防費のこころの健康づくり事業、１４８ページ、１項１目、産業経済費、産業経済総務費の就業支援費、そして１４３ページ、２項１目、環境保全事業について伺います。こころの健康づくり事業は、近年、８００万円から１,０００万円ぐらいの事業費を推移しています。そこで伺うのですが、事業の効果測定をどのように行われているのかお伺いいたします。","respondent":"榎本荏原保健センター所長","answer":"その支援している中で、それぞれの方々に社会復帰に向けてアンケートと、もしくはご本人から聴取いたしまして、状態が改善しているということで、企業、お勤めになられる方等、そういった成果の中で進めている、確認しているです。","voiceIndex":96,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"アンケートと、聴き取りをしているということで安心しました。２０１４年度のこころの健康相談訪問事業で、相談人数等の実績と、専門医による相談が必要だったケースを教えてください。そして、希望する方が全て専門医による相談ができたのか、その辺の状況についてあわせてお答えください。","respondent":"榎本荏原保健センター所長","answer":"こちらの保健センターのほうにご希望がありまして、お電話があった方については全て、予約ができないとか、そういったことはございませんで、事前に保健師や心理職の者が対応いたしまして、細かく、インテークと申しますか、ご相談の内容をお聞きいたしまして。","voiceIndex":98,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"思春期の心の相談が７７件とのことで、月３回の予約相談だと、およそ１日２人の相談となりますが、予約相談を必要としている子どもが平日の１０時から１２時ぐらいに相談に向かうというのは少し難しくないでしょうか。そういった問題意識はお持ちでしょうか。","respondent":"榎本荏原保健センター所長","answer":"もしくは、どうしても外に出られないということで、家に閉じこもっておられるとか、もしくは対応の仕方がわからないといったことで、日中帯でのご相談で、特にそのほかの時間にご相談したいというようなことでは伺っておりませんので。","voiceIndex":100,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"わかりました。２０１０年の決算特別委員会で、生活者ネットワークの質問に「学校保健会との連携を検討している」と答弁されています。それから５年が経過しています。具体的にはどのようなことを学校と連携されているか教えてください。","respondent":"榎本荏原保健センター所長","answer":"保健センターの所長は学校保健会の会議にも出させていただいておりまして、その中で、思春期の講演会でありますとかご相談をＰＲさせていただきまして、ぜひお受けいただくようにということで、先生方や保健会の方々とご相談しながら進めているところです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問","question":"精神保健福祉という中で、心の病気の予防、精神障害者の社会復帰の支援を行うと事務事業概要にも書かれており、思春期に焦点を当てて伺ってきました。精神疾患の早期発見がいかに重要かということは、誰しも疑いのないところだと考えます。教育委員会からは答弁をいただいていますが、精神保健福祉の専門の担当者として、教育部門との連携に課題があるという認識はお持ちでしょうか。","respondent":"榎本荏原保健センター所長","answer":"そういった方々に対して保健センターも様々なＰＲをいたしまして、相談に乗れる体制をとってまいりたいと思いますし、学校保健の方々とも協力して対策を進めて支援してまいりたいと考えています。","voiceIndex":104,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"よろしくお願いします。精神障害者の家族会の皆さんからも、教育現場での精神保健教育は毎年要望を出されていると伺いました。ぜひ、積極的な連携と実践をお願いいたします。最後に確認したいことがありますが、心の健康相談の相談実績は年々増えています。取っかかりとして、最初の相談窓口が保健師だと思われますが、母子相談件数も近年、増加している状況です。保健師の増員は図られていますか。","respondent":"米田人事課長","answer":"所管のほうで、それぞれ事業を実施している中で、いわゆるそれぞれの専門職についての定員については、業務の実態等を踏まえて、今後も所管のほうと検討してまいりたいと考えています。","voiceIndex":106,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"人にかかわる人材は本当に重要だと考えます。必要なところには十分で適切な配置を要望します。区の仕事は第一義的には区民の福祉向上なので、しっかりと認識してくださいますようお願いいたします。若者就業支援事業について伺います。若者就業支援の中に、若者と女性向け就業支援がありますが、それぞれ相談曜日と時間を教えてください。","respondent":"立木産業活性化担当課長","answer":"若者、それから女性の相談の曜日と時間ですけれども、若者相談に関しましては火曜日から金曜日、午前１０時から午後５時までということで、１日通してやってあります。","voiceIndex":108,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"相談から就業につながった事例数をそれぞれ伺います。","respondent":"立木産業活性化担当課長","answer":"平成２６年度のデータですけれども、若者のほうが、延べ利用が２７７名、就職決定が１９名ということになってあります。女性の利用者が、平成２６年度は４３名のうち、就労のほうが０名ということになってあります。","voiceIndex":110,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"先ほど相談時間を伺ったのですが、明らかに女性の就労相談時間が、でも前回よりは月曜日が増えて良かったなとは思ったのですけれど、相談時間が短いと思いますが、何かそこに関しては理由はありますか。","respondent":"立木産業活性化担当課長","answer":"やはり、どうしても就業相談にいらっしゃいます女性の方は育児中の方が多いということもございまして、当初、この時間で開始したものですけれども、今年度、もう少し就労相談を受けやすい時間帯を設定して多くの方に来てもらえるようにということで、月曜日のコマを今年度。","voiceIndex":112,"id":"exchange-049"},{"speaker":"田中委員","kind":"意見","question":"この時間に来られない方へのフォローはどうなっているのかということと、電話対応などを行っているのかということと、そして今おっしゃられたように、育児中の方のために、子どもを連れても相談ができるような配慮はありますか。例えば遊びのスペース、子どもが遊べるスペースがあったり託児が用意されているとか、そういったことを具体的にお願いいたします。","respondent":"立木産業活性化担当課長","answer":"そのような形で、今、実施しております。","voiceIndex":114,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"やっぱり子どもを連れて相談というのは、お母さん的にもなかなか本当に難しいじゃないですか。では次に行きます。環境保全事業について、主にエネルギーについて伺います。そこで、２０１３年３月に策定された第２次品川区環境計画より質問します。質問ですが、２０１４年度の検討内容と、２０１５年度にはどんな内容の事業が開始されているのか、基本目標１について伺います。","respondent":"三ツ橋環境課長","answer":"民間活力のエネルギーの導入の部分ですけれども、仕組みの検討でございまして、この中の、低炭素のまちをつくるという部分ですと、公共施設への再生可能エネルギーなど導入促進の点がございまして、例えば太陽光エネルギーの部分の設置助成なども考えております。","voiceIndex":116,"id":"exchange-051"},{"speaker":"田中委員","kind":"確認","question":"こういった計画では、達成目標が示されて初めて進捗状況が確認でき事業評価も可能であると私たち生活者ネットワークは考えています。重点プログラムの進捗状況、指標・目標値の達成状況を鑑み、２０１７年度に中間見直しを実施とあります。２０１７年ぐらいには、２３施設からどのぐらいの増を見込んでいるのでしょうか。","respondent":"三ツ橋環境課長","answer":"例えば全てのところに太陽光エネルギーを設置するというのもなかなか難しい問題でございまして、また公共施設に関しても、できる限り地球温暖化防止に向けて推進していきたいと考えていますけれども、この目標につきましては、日々、年々、推進していきたいと思っておりまして。","voiceIndex":118,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問","question":"私からは、１３９ページ、女性の健康診査、子宮がん検診、そして１４０ページの母子健康診査費、１４２ページの不妊治療助成事業についてお伺いいたします。不妊治療助成事業についてからお伺いします。特定不妊治療、そして一般不妊治療の概要とそれぞれの助成の件数、そして過去の件数との比較、最近の傾向、また男女の数もおわかりになりましたらお聞かせください。","respondent":"川島健康課長","answer":"所得制限は設けておらず、検査に要する医療費の自己負担額の２分の１を限度に、１年度１０万円まで、通算して５年度まで助成しております。助成の件数ですが、平成２４年度が６５３件、平成２５年度が７２６件、平成２６年度は７７８件の実績になっております。","voiceIndex":123,"id":"exchange-053"},{"speaker":"横山委員","kind":"確認","question":"詳細のデータを教えていただきまして、ありがとうございました。一般不妊治療の件数、平成２４年から平成２５年、平成２６年と増えているような傾向であるということがわかりました。男女の数、女性が圧倒的に多いということで、男性の不妊の治療の方も一部いらっしゃるということで確認をさせていただきました。次に、平成２８年度からの年齢制限の内容についてもご説明をお願いいたします。","respondent":"川島健康課長","answer":"国のほうで、体外受精、それから顕微授精といった特定不妊治療の助成をしているのですが、そちらに平成２８年度から年齢制限を置くといった、その背景のご説明をします。近年、結婚年齢、それから妊娠・出産年齢の上昇という状況があります。","voiceIndex":125,"id":"exchange-054"},{"speaker":"横山委員","kind":"質問","question":"男女それぞれの出産に適した年齢について、先ほど、国の見解で３５歳までということで周知というキーワードですとか、あとは４３歳以上を対象外にしていくというお話がございましたけれども、品川区としては出産適齢期というものをどのように捉えていらっしゃるでしょうか。","respondent":"川島健康課長","answer":"こうした国の報告の動きというのも非常に重要なものであるということで、ちょっと今、どういった手法ですとかタイミングで、周知ですとか啓発する必要があるのかというのは、すぐにお答えは出せないのですが、機会を捉えて啓発するような必要があると認識しています。","voiceIndex":127,"id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"自分自身、そしてパートナーの体を知ること、また性を知ることで、区民の皆様がより多くの選択肢とそれを選ぶことのできる自由を得ることができるかと思います。区民の皆様のよりよいライフプランのために、科学的な根拠をベースとした、妊娠・出産の年齢に関する知識を周知・啓発していただきたいと考えております。","respondent":"川島健康課長","answer":"庁内の関係機関と適切に連携して、必要な周知が行われるように検討してまいりたいと思います。","voiceIndex":129,"id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"啓発、そして周知のほう、適切なタイミング、そして方法のほう、ぜひ検討していただきまして実施していただけたらと考えております。要望します。次に子宮がん検診についてお伺いいたします。細胞診とＨＰＶ検査併用検診導入に関しまして、以前から質問をしています。国の現在の方針と品川区のお考えをお聞かせください。","respondent":"川島健康課長","answer":"国で平成２５年度から、細胞診とＨＰＶ検査併用の有効性を検証する検証事業を実施しておりましたが、そちらでもまだ結論は出されていないということで、国のがん検診の指針にない検査につきまして区で新たに取り入れるというのはかなりハードルが高いなという考え方です。","voiceIndex":131,"id":"exchange-057"},{"speaker":"横山委員","kind":"質問・要望","question":"ただいまの国のほうの状況をお知らせいただきました。現在、現時点ではハードルが非常に高いというところなのですけれども、品川区と関係の産婦人科の医会等でワーキンググループをつくっていただいて、実施に当たっての問題点・費用等の調査についても将来的に積極的に考えていただきたいというところを要望させていただきたいのですが、区のお考えをもう一度すみません、お聞かせください。","respondent":"川島健康課長","answer":"国の指針にない検査を導入するというのは、先ほども申し上げたとおり、かなりハードルが高いと思いますが、課題ですとか可能性を探るという意味の話というのは大事なことだと思いますので、なかなか難しい点はあるとは思うのですけれども検討させていただきたいと思います。","voiceIndex":133,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"２点、要望だけさせていただきたいのですけれども、子宮頸がんの受診率、まだ改善する余地があるかと思います。こちらは要望だけさせていただけたらと思います。そして次に、女性の産後の健康診査について、また母子健康診査費のところをお伺いします。女性の産後の健康診査について現状を確認させていただきたいと思います。","respondent":"太田品川保健センター所長","answer":"女性の産後の体のケアについては非常に重要な課題だと考えています。講演会等、いろいろな機会を捉えて啓発してまいりたいと考えています。","voiceIndex":135,"id":"exchange-059"},{"speaker":"横山委員","kind":"質問","question":"産後のケア、重要ということでご答弁をいただきました。我が会派でほかの委員の方からも何度かご質問させていただいたかと思うのですけれども、産後の宿泊型ですとか、または日帰りのケアの施設、そういった体制をとっているような自治体等もあるという情報をいただいております。産後のケアの充実について、もう少し詳しくもう一度お願いいたします。","respondent":"太田品川保健センター所長","answer":"産後の宿泊型のケア等につきましては、以前から重要な課題だと認識しておりました。今後、ネウボラネットワークの検討会の中でも優先度が高い事業として検討を進めてまいります。","voiceIndex":137,"id":"exchange-060"},{"speaker":"つる委員","kind":"確認","question":"以前にも質問して確認しておりますけれども改めて、区の施設への設置台数は２１１台、１９６カ所でよろしいかどうかということと、夜間利用可能な場所はどこにあるか。今年の予算特別委員会でも伺いましたが、蛍光表示板に変わっているものの台数、またその代替策として懐中電灯等を保管して夜間でも操作しやすくなっているところについてお聞かせください。","respondent":"川島健康課長","answer":"ご質問とはちょっと違うのですが、それが白だったものがオレンジに切り替わっておりまして、それから、今新しいＡＥＤを試してみますとボタンが発光するということで、旧式のＡＥＤというのはもう２台のみということで、新しいものに変わったので。","voiceIndex":140,"id":"exchange-061"},{"speaker":"つる委員","kind":"提案","question":"あわせて次の角度からなのですが、これも前回質問させていただいて、オープンデータを活用して、ナビワンコでＡＥＤの場所もＡＲ技術を使って確認ができる。こうしたものの周知、そのときも周知についてどういうふうに、ＡＥＤの一覧のところにリンクを張ったらどうですかというようなことも含めて提案しましたが、そのあたりの周知についてどのように行っているのか教えてください。","respondent":"川島健康課長","answer":"ウォーキングコース上の区有施設のＡＥＤも表示できるようにするという配慮をしたいと考えています。","voiceIndex":142,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"その近くにいらっしゃる方がもしいれば、ＡＥＤの箇所を確認した上で現場に急行するというような実証実験が行われたという報道もありました。次の質問に行きます。こうした意味でも、先ほども触れましたオープンデータでの活用というところでも、トイレについても広げていただきたいと思いながら、この公衆便所費について、維持管理費の推移というのはどういうふうになっているのか教えてください。","respondent":"多並公園課長","answer":"公衆便所です。駅前を中心とした、公衆の衛生上、必要となる場所について、公衆便所を設置しておりまして、現在３６カ所あり、維持管理をしています。維持管理費ですけれども、平成２６年度の決算が、ここにありますような３,８４６万１,０００円。","voiceIndex":144,"id":"exchange-063"},{"speaker":"つる委員","kind":"質問","question":"わかりました。維持管理費の件は結構です。その維持管理費ということも含めての次の質問なのですが、だれでもトイレというのは、公衆便所と公園、また児童遊園トイレを合わせて２６カ所あるということで、過去の答弁を見たらありました。その上で、一般的に、使いたくなるトイレとか気持ちよくなるトイレというのはどういうトイレなのでしょうか。","respondent":"多並公園課長","answer":"子育ての方からすればベビーベッドがある、または障害者の方からすればオストメイト等の必要な設備があるというようなところで、いつでも誰でも快適にご活用いただけるトイレを整備していくことが重要だと考えているところです。","voiceIndex":146,"id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"そうした配慮というのでしょうか、そういう工夫も必要かなと思いながら、ちょっと調べましたらば、おもてなし課というところで有名な高知県の取組みなのですが、県の取組みなのですけれども、平成２４年度からおもてなしトイレの認定を行っているそうでありまして、６９４カ所、認定シールをやって、優れた取組みに対し表彰状だとか記念品をあげている。これは要望も含めてで終わります。次に行きます。","respondent":"間部文化観光課長","answer":"品川区の魅力というご質問ですが、一つ挙げられるとすれば、旧東海道の町並みですとか、大森貝塚の部分ですとか、商店街、あとは水辺の関係ですね。そういった多種多様な資源があると考えているところです。","voiceIndex":148,"id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"それを発信して、いかに品川区に来訪いただくかという視点でありますけれども、過去の我が会派の一般質問の答弁で、区長のご答弁でありましたけれども、「品川が目指す都市型観光は、区民一人ひとりが自分こそが観光大使の意気込みで、自分のまちのよさを自慢し、来訪者をもてなすまちづくりであります」というふうにご答弁をされています。こういう工夫も必要かと思いますけれども、いかがでしょうか。","respondent":"間部文化観光課長","answer":"「ゆうゆう散歩」ですとか、いろいろなのが出ているのですけれども、確かにマスコミを通じてアピールすることが品川区の魅力を伝達することになりますので、プレゼントということもありますけれども、ＳＮＳなどを使った書き込みを中心に。","voiceIndex":150,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"は１３７ページ、休日・応急診療費について伺いたいと思います。私も５歳と２歳の２人の娘がおりますけれども、急な発熱の際、４回か５回、利用させていただきまして、大変助かりました。品川区はこの休日診療事業の重要性をどのように認識しているのか伺いたいと思います。あわせて、この１０年、２０年の受診者数の推移、増えているのか減っている傾向なのかお伺いしたいと思います。","respondent":"川島健康課長","answer":"休日診療を区はどう捉えているかというところがまずありますが、夜間、それから休日における区民の方の医療不安を解消するという、区民の生命を守る目的で行っている非常に重要な事業だと考えております。","voiceIndex":153,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"ところが、この事業に対しての委託料なのですが、平成１１年、１９９９年から変わっていないということで伺いました。伺いますけれども、委託料というのは受診者数に比例して算出するものなのかどうかお答えいただきたいと思います。休日診療費、委託料、事業が始まってから２０年になるわけですが、どのように推移してきたのか、増えてきたのか減ってきたのか、そこもお伺いしたいと思います。","respondent":"川島健康課長","answer":"２０年という推移は何とも言えないのですが、今ご指摘のとおり、ここ数年は、消費税の増額の見込みはあったのですが、委託料は据え置きのような形で推移しているという認識です。","voiceIndex":155,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"それと、人件費のところということでしたけれども、患者数が相当増えている中で、やっぱり実際、事業をするほうとしては負担も、先ほど倍になっているとお話も紹介させていただいたのですが、当然負担も上がっていると思うのですが、委託料ですけれども、受診者数に比例して算出するというものではないのかどうか、そこももう一度お伺いします。","respondent":"川島健康課長","answer":"今おっしゃったとおり、単価的には、私ども平成１３年ぐらいから大きく変わっていないですが、繁忙期の対応ということで別途契約して増強するような手当てをしたりして対応してきたと考えております。","voiceIndex":157,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"実際、休日返上で診療に当たる現場では、休日診療所に勤務する医師も少なくなってきていると。とりわけ、小児科医などでは高齢化なども進んでおりまして、かなり疲弊していて、もうギブアップ寸前、このままでは事業を続けられない事態になりかねないとの深刻な声が上がっております。こうした声とか状況を品川区としては把握しているのでしょうか、伺います。","respondent":"川島健康課長","answer":"１％、単価をアップしますと、約１,０００万円ほどの財政出動になるということもあります。様々な要素を勘案しまして、適切に検討して対応してまいりたいと考えています。","voiceIndex":159,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとごめんなさい。現場からの声というのを伺っているのかということでお伺いしたので、そこら辺、結構深刻な声が寄せられております。そこをもう一度だけお願いします。","respondent":"川島健康課長","answer":"医師会の状況というのも、直接、私ども聞いて、お伺いして、その上で今までこういった予算措置をしてきたですので、今年度もまたいろいろな状況を踏まえて適切に対応していくような考え方でおります。","voiceIndex":161,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"伺っているということでしたけれども、私が改めて驚いたのが、医師会の自助努力や自己犠牲によってこの事業が成り立っているという実態でした。ぶっちゃけ、大きな持ち出しになっているということなのです。委託料は約３０万円。何と半分以上、約４４万円が持ち出しと。私は、医師会の自己犠牲頼みでは、この事業、やはり続けていけないのではないかと思うのですけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"いろいろな状況、直接にお話も伺っているところですので、様々な要素を踏まえまして適切な対応を検討してまいりたいと考えております。","voiceIndex":163,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、自己犠牲頼みでは事業が続かないのではないかと思うのですけれども、いかがでしょうかということで聞かせていただいたので、そこを後でお聞かせいただきたいという点が一つ。休日における区民の医療不安の解消や、生命を守ると。それで、この休日診療の委託料をやっぱり見直し、改定、上げて、休日診療に当たる勤務者の確保・存続を要望しますけれども、いかがかと。","respondent":"川島健康課長","answer":"今、先ほどからも委員がお話ししていただいている部分を踏まえまして、それから様々な状況を勘案しまして、適切に、慎重に対応してまいりたいと思います。","voiceIndex":165,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ私も、一区民としても一人の親としても、休日・夜間診療、これからも大変大事な事業だと考えていますので、現場の声もさらにしっかり伺っていただいて、必要な支出はきちんとしていくという立場で改善をお願いしたいと思います。続いて１３８ページの各種予防接種について伺いたいと思います。それが何日も続いていくと。もしつかんでおりましたら伺わせていただきたいと思います。","respondent":"舟木保健予防課長","answer":"ただ、国のほうが出しております資料で、東京都全体で大体６５％ぐらいの方が接種しているという状況はわかっております。区も大体その程度ではないかなと考えています。","voiceIndex":167,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど紹介したように、最悪、死に至ることもあります。子どもの命を守り、子育て負担を軽くして子育て支援を進めるためにも、ぜひロタウイルスワクチンについても助成制度の創設が必要だと思いますけれども、私は要望したいのですが、いかがでしょうか。この助成制度創設に向けて課題があると考えているのならば、何が課題となっているのか、それもあわせて伺います。","respondent":"舟木保健予防課長","answer":"ロタウイルスのワクチンについては、国が定期接種化に向けて動いているところです。区のほうでは、そちらの検討状況を見ながら、また区の財政状況を見て、費用助成については現在検討しているところです。","voiceIndex":169,"id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先天性風しん症候群対策について、一般質問に引き続きお尋ねいたします。成果報告書に記載されている先天性風しん症候群対策の風しん抗体検査１,３３３件、予防接種５５６件の数について、区はどのように評価されているのでしょうか。大雑把でよろしいのですが、２０から４０歳代の、風しんに抗体を持たない、すなわち免疫を持たない男女はどのぐらい存在するとざっと見積もられているのでしょうか。","respondent":"舟木保健予防課長","answer":"この事業を実施するに当たり、国のほうから示されていた、風しんの抗体が十分ある人の割合というのが大体８割ぐらいというふうな形で国のほうから言われていたのですが、実際はそれよりもかなり少ないなという印象を持っています。","voiceIndex":172,"id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"提案","question":"第３回定例会の一般質問で、風しんに対する感受性者を少しでも減らすため、風しんに免疫がないことが明らかな妊娠を望む女性には、過去のワクチン接種の有無にかかわらず接種費用の助成を行うこと、さらに女性の３５歳からの健康診査に風しん抗体検査を加えることを提案いたしました。その後の検査、予防接種の勧奨のご検討はいかがお進みでしょうか。新たな取組みなどもお考えでしょうか。","respondent":"舟木保健予防課長","answer":"この事業、風しん抗体検査の啓発につきましては、１０代の啓発は引き続き啓発するとともに、２０歳から４０歳代での患者発生が多いということを踏まえまして、職域等への啓発も今後検討していきたいと考えています。","voiceIndex":174,"id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"提案","question":"しかし、この流行を受けて提案された風しん感受性集団に対する積極的なワクチン接種はほとんど実行されず、平成２５年に再び爆発的な大流行が引き起こされ、先天性風しん症候群の赤ちゃんが多数出生したことは記憶に新しいところです。もう二度と風しんの流行を繰り返してはなりません。次に、任意接種、流行性耳下腺炎ほかから、おたふく風邪ワクチンについてお尋ねいたします。それから８年が経ちました。","respondent":"舟木保健予防課長","answer":"おたふく風邪ワクチンの接種の実績ですが、こちらの事業は平成１９年度から開始しております。それで、すみません、実績については過去３年のものしか今持ち合わせておりませんので、過去３年の実績をお伝えします。","voiceIndex":176,"id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"小児科クリニックで実際に診療しておりますと、おたふく風邪は本当に少なくなったということが実感されます。風しんワクチンは定期接種となりましたが、おたふく風邪ワクチンについては現在、国の動向はいかがと区は評価されているのでしょうか。国の定期接種化の動向についてご説明をお願いいたします。","respondent":"舟木保健予防課長","answer":"国の動向なのですが、定期接種化の検討につきましては、新たなワクチン、ＭＭＲ、おたふく、麻しん、風しんの混合ワクチンなのですが、そちらのワクチンの開発が望まれておりまして、引き続きの検討となっているような状況です。","voiceIndex":178,"id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"おたふく風邪は別名、流行性耳下腺炎ともムンプスともいいますが、この病気にかかりますと、１０から２０人に１人は髄膜炎となり、１００人に１人は永続的な片耳の難聴となり、さらに年長で発病すると不妊などのリスクが高まります。次に、難病対策費についてお伺いいたします。その学習会の成果も踏まえ、難病対策についてお尋ねいたします。初めに、難病と指定難病の定義についてご説明をお願いいたします。","respondent":"舟木保健予防課長","answer":"この難病のうち、患者数が人口の概ね０.１％以下、客観的な診断基準が確立しているものを指定難病としまして、医療費の助成の対象となっております。","voiceIndex":180,"id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"確認","question":"治療法が確立しておらず、どう治療してよいかわからない。このうち、特に人口数が少なくて患者数が少なくて、大体３万から５万人以下、さらに客観的な診断基準は確立していて、非常に病気であるということがしっかりと確認できるようなものを指定難病と呼び、この指定難病は現在、医療費の助成の対象となっております。指定難病を３０６疾病まで増やした理由と、なぜこのような難病の制度改革が行われたのか。","respondent":"舟木保健予防課長","answer":"難病対策の改革について提言や報告書が出されまして、検討が進められて、その結果、持続可能で安定的な難病対策を行うためということで、平成２６年５月２３日に難病の患者に対する医療等に関する法律が制定されて、平成２７年１月１日、施行されております。","voiceIndex":182,"id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"難病に関しては、大体３００から５００種類以上、様々な難病が現在いろいろと確立していたり、新たに増えているのが現状です。品川区では、医療費を助成している指定難病患者というのは現在どのぐらいいらっしゃるのでしょうか。","respondent":"舟木保健予防課長","answer":"疾病拡大前の昨年度の実績ですと、約２,４００人の方が申請を出しております。疾病拡大によりまして、先ほど大体７８万人から１５０万人程度に拡大するということを、数字を当てはめますと、４,０００人以上になるのではないかと考えております。","voiceIndex":184,"id":"exchange-082"},{"speaker":"鈴木（博）委員","kind":"質問","question":"難病患者に対する療養などは東京都の業務ということになっております。しかし、原因不明の病気で治療法もわからず、日々、病気と闘いながら必死にご苦労されている難病の患者の皆様に、品川区としても最大限の支援と努力をお願いしたいと思いまして、私の質問を終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"私からは、１３９ページの下から２行目のこころの健康づくり事業からの質問です。この事業を簡単にご説明いただければと思います。","respondent":"榎本荏原保健センター所長","answer":"こころの健康づくり事業のご説明です。こころの健康づくり事業は、保健センターが主となって行っているところです。","voiceIndex":188,"id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"この中に５つの事業があります。ここ３年間は約６６人と減少しておりますけれども、これは大変喜ばしいことですけれども、この減少の原因というものはどのように考えているのか。そしてまたこの２３区で本区は比較をすると多いのかそれとも少ないのか、どちらでしょうか。教えてください。","respondent":"舟木保健予防課長","answer":"２３区の比較についてなのですが、自殺者数の人数がそんなに多いものではないので、結構、前後するものでありますが、大体、概ね真ん中前後を行き来しているような状況とこちらでは把握しております。","voiceIndex":190,"id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"大変なことであります、人の命でありますから、何とかそれを抑えることができればなと考えています。この事業は、保健予防課だけではなくて、この品川区の３保健センターと共同で区民の相談を受けるそうでありますけれども、主にどのような相談を受けることが多いのでしょうか。そしてまた年間を通しての相談事業、一人でも多くの区民を救うために、特に本区として９月が自殺予防月間ということであります。","respondent":"舟木保健予防課長","answer":"それ以外にも機会を捉えてリーフレットを配ったり等しております。今回、１０月３日に行った映画上映会に関しましては、非常に多くの方に来ていただきまして、定員２００名のところ、２３６名というような状況となっております。","voiceIndex":192,"id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"関心度はどちらかといえば高いということですか。区民の皆さんから見ればそれが関心度は高いということで理解してよろしいでしょうね。自殺を考えている人は、周囲の人に何らかのサインを発していると説明していますけれども、相談センターにはいろいろと電話もかかってくることと思いますけれども、本人からか、それとも周囲の人たちなのか、割合的にはどのような感じでしょうか。","respondent":"榎本荏原保健センター所長","answer":"お仕事がなくアルコールの量が増えたとか、なかなか家からやはりちょっとうつの状態になって出られなくなってしまって、どう対応したらいいかわからないといったご相談なども入ってきているところです。","voiceIndex":194,"id":"exchange-087"},{"speaker":"木村委員","kind":"質問","question":"そのようにして、多くの周りの方々が、そういう病を持っている方々に対して目配りをしている、注意を払っているということは、大変なことだと思います。大事なことだと思いますので、お願いしたいと思います。このようなことで、自殺予防のアナウンスカーというものは聞いたことがありませんけれども、そういうものは、何か法律的なものがあって、そういうものはできないということなのでしょうか。","respondent":"舟木保健予防課長","answer":"アナウンスカーの適用などについては、すみません、こちらのほうで把握はしていないのですが、ラッピングカーとか、そういうのは東京都でもやっているかなと把握しております。","voiceIndex":196,"id":"exchange-088"},{"speaker":"木村委員","kind":"質問","question":"そのようにして、本当に声を耳から聞くことも大変有効な手段ではないかと思います。次に１４０ページ、下から１０行目、先ほどつる委員からもありましたけれども、公衆便所費というものに対しての質問であります。この公衆便所、３６カ所、３,８００万円余でありますけれども、公園内のトイレと私は思っていました。これは先ほど思いついたわけでありますけれども、お聞かせください。","respondent":"多並公園課長","answer":"そういった観点からしても、今、名前としては、だれでもトイレという形で全国でもつけさせていただいて管理していますので、現時点ではそういった形で広く皆様がご活用、誰でも使える形で進めさせていただければと考えています。","voiceIndex":198,"id":"exchange-089"},{"speaker":"木村委員","kind":"質問","question":"だれでもトイレですね、わかりました。この報告書には、何というのでしょうか、小破修理というのでしょうか、２８９万円余とありますけれども、どのような修理が大変多いのか。修理箇所とは劣化によって自然に破損や故障することを意味するのか、どうでしょうか。公共施設を守るためにも、何か行政として特に力を入れているようなところというものはあるでしょうか。","respondent":"多並公園課長","answer":"今の小破修理の件ですけれども、この決算書にあります小破修理、２８０万円余ですが、全部で２２件の修理がございました。内容といたしましては、主なものとしましては、例えばドアが壊れてしまって修理した。","voiceIndex":200,"id":"exchange-090"},{"speaker":"木村委員","kind":"質問","question":"公衆トイレで何よりも気を使うところというものは、多くの区民が利用するわけでありますから、いつでも本当に清潔に保つことだと思います。地域のボランティアの団体が駅前を掃除したりすることというのがよくあるわけでありますけれども、このようなことでトイレ掃除などをしたいというボランティアからの申し出というものはあるのかどうか、教えてください。","respondent":"多並公園課長","answer":"現在、公衆便所は３６カ所ございまして、その清掃につきましては、多く使うところを中心に１日２回、これが１７カ所、残りの１９カ所につきましては１日１回、清掃させていただいてあります。","voiceIndex":202,"id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"次に１４５ページ、上から６行目なのですけれども、緑化啓発普及事業の質問ですが、緑のボランティア支援事業、１６５団体。まちの駅のトイレも可能であるかどうか教えてください。","respondent":"多並公園課長","answer":"そういう申し出があれば、もちろん可能な限り、区として支援するということで前向きに受けるような形で、ご相談をまずお受けして、そのような形でできる部分を支援したいと思います。","voiceIndex":204,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問・要望","question":"初めに１５０ページの中小企業ワークライフバランス支援事業ということで質問いたしますけれども、今、社会情勢というか高齢化社会ですとか、また核家族とか、そういう社会情勢の変化の中でワークライフバランスという考え方が大変に重要になってきていると考えていますけれども、まず品川区の中小企業ワークライフバランス支援事業で、平成２６年度。","respondent":"山崎商業・ものづくり課長","answer":"こちらの理由ですけれども、年度当初にワークライフバランスの導入を予定している中小企業のコンサルティング事業の申請を受け付けまして、予算的には３社で各１００万円ずつの３００万円というような内訳でございました。","voiceIndex":207,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"社内都合ということでございましたけれども、もし差し支えなければ、その社内都合がどういったものであったのかというのをお伺いしたいのですけれども、お願いします。","respondent":"山崎商業・ものづくり課長","answer":"経営者の方が会社の魅力をアップするために自社でワークライフバランスの考え方を取り入れるんだということで検討していたのですけれども、いろいろな厳しい社会状況で、会社の経営自体が、そうした部分というよりも経営本体のほうに諸問題が発生しまして、今年度については。","voiceIndex":209,"id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"やはり中小企業、特に今おっしゃられたような小規模・零細というようなところでのワークライフバランスというのはなかなか、思いがあっても進めていくというところが難しいというようなところもあると認識いたしておりますけれども、そういった中、本定例会の会派の一般質問の中でも、ワークライフバランス、さらなる推進をというような趣旨で質問させていただいて。","respondent":"山崎商業・ものづくり課長","answer":"それから企業の推進の部分に限って申し上げますと、このワークライフバランスの推進も事業を始めて５年、６年と経ってきておりまして、当初の頃にいろいろ中小企業の経営者の方が導入した会社の実態なども、さらに継続して、それが導入して年数を経て。","voiceIndex":211,"id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の効果測定というお話、大変に重要かと思います。次に、１４２ページのかかりつけ歯科医です。この１１２件という数字を、私としては、区民のニーズからすれば、やや少ないのかなという印象も持っているのですけれども、区としてはこの１１２件どのように捉えていらっしゃるでしょうか、お伺いいたします。","respondent":"川島健康課長","answer":"今ご紹介のありました１１２件というものは、全部の紹介件数のうちの訪問の対応をしたもの、訪問歯科診療が必要だという方のお宅まで歯科医と訪問しまして、お宅の状況、それから歯の状況を見まして、適切な歯科医を紹介するということでして。","voiceIndex":213,"id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる紹介をして、訪問歯科診療につなげていくというところでの１１２件。それ以外も含めると２４５件ということでしたけれども、そういう問い合わせが区民のほうからあって、それが訪問歯科診療にスムーズに結びつけてというのですか。もっと区民のニーズに応えて訪問歯科診療を受けていく、そういう方向性があるべきなのではないかというふうな思いもあるのですが、その点についてはいかがでしょうか。","respondent":"川島健康課長","answer":"こちらのかかりつけ医の紹介は、品川と荏原、両歯科医師会のほうに委託しているものです。その会員の先生がまず行くということで、その辺の連携は、調査に行くのは会員の先生が行くということで、スムーズにいっていると考えています。","voiceIndex":215,"id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうインフラというか、そういった部分での、そんなのが、もし手かせ足かせになって、区民のニーズに対しての足らざるところというものがあるのであれば、そういったところにもぜひ支援の手を差し伸べていただきたいと、このように思いますけれどもいかがでしょうか。","respondent":"川島健康課長","answer":"どのようにすれば訪問歯科診療に取り組みやすい環境ができるかということで、どんなお手伝いが私どもができるか、政策的に誘導できるかというところもあるのですが、今、知恵を絞って、少しずつですけれども進めていけるような形を考えているところですので。","voiceIndex":217,"id":"exchange-098"},{"speaker":"塚本委員","kind":"確認","question":"わかりました。では引き続きよろしくご検討のほうお願いしたいと思いますので、この質問は以上で終わりといたします。若干時間がありますので、１３９ページ、肝炎ウイルス検診について、確認でお伺いします。平成２５年決算の実績としては３,８３７件。","respondent":"川島健康課長","answer":"今、最初に委員がおっしゃった、一生に一度でいい検査だということで、本当でしたらどんどん減っていくはずなのですが、まだ同数程度、毎年実績があるということで、こういった予算立てをさせていただいているです。","voiceIndex":219,"id":"exchange-099"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１３８ページの予防費、定期予防接種と、それから１５１ページの海外進出推進事業についてお伺いします。定期予防接種なのですけれども、我が会派の鈴木委員は専門家でございまして、私が専門家ではない立場で質問をしたいと考えています。改めて、定期予防接種の意味と、それから任意予防接種との違いについて簡単に教えてください。","respondent":"舟木保健予防課長","answer":"定期予防接種と任意予防接種の違いですが、定期予防接種は予防接種法、法律に基づいた接種となります。任意予防接種ですが、こちらは予防接種法に基づかない接種となります。","voiceIndex":222,"id":"exchange-100"},{"speaker":"沢田委員","kind":"質問・要望","question":"特に定期の風しん・麻しんのワクチンについて、ＭＲワクチンの件で、品川区の最近の接種率とその傾向、それから、大体どれぐらいの人数が接種の対象で、どれぐらいが打たれているのか教えていただきたいと思います。接種をしていないというのは、一体どういう場合のどういう方がされていないのか教えてください。","respondent":"舟木保健予防課長","answer":"ではＭＲワクチンの接種率ですが、１期につきましては、対象者、発送件数なのですが、３,４２０件発送いたしまして、接種が３,３８０件となっておりますので、接種率は９８.８％となっております。","voiceIndex":224,"id":"exchange-101"},{"speaker":"沢田委員","kind":"意見","question":"ＭＲワクチンに関して、実際、重度の副反応というのはどういうことがあるのか、またそういった例は一体どの程度あるのかということをお聞かせいただければと思います。拒否されるというのはちょっとよくわからないのですけれども、信用できないということで拒否されている親御さんに対する区からの説明というか、改めての説明はどうなっているのかお聞かせいただければと思います。","respondent":"舟木保健予防課長","answer":"個別にご相談があれば、その都度ご相談に乗っております。病気の方で受けられない方の場合であれば、ある一定の決められた疾患等ありますので、それに相当し、確認できましたら、普通に定期として受けることができますので、そのような対応もこちらのほうとしては行っております。","voiceIndex":226,"id":"exchange-102"},{"speaker":"沢田委員","kind":"質問","question":"先ほども鈴木委員からも質問がありましたけれども、風しんで様々な、２年前、大変、風しんが大流行して、そういった障害を持ったお子さんが生まれたりとか大変なことになったかと思います。","respondent":"舟木保健予防課長","answer":"予防接種につきましては、やはり接種率のほうが確保できないと、麻しんや風しんのように海外の流行に合わせて国内での流行がまた起こってしまうというような懸念があると思います。","voiceIndex":228,"id":"exchange-103"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった自治体もありますので、品川区でも１００％を目指して定期予防接種を受けるように進めていっていただきたいと思います。それから、ちょっと時間がないので、海外進出推進事業ですけれども、このビジネスサポートセンターの件についてはいろいろと今までも質問もありましたけれども、タイで行っていますけれども、平成２５年度はベトナムへの視察団を派遣されたということでありました。","respondent":"山崎商業・ものづくり課長","answer":"少し問題もありまして、直ちに進出支援というような状況ではございません。タイのＡＳＥＡＮも共同体で一緒になりますので、そちらのほうの調査結果も踏まえて検討してまいりたいと思います。","voiceIndex":230,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"成果報告書の１４３ページ、環境費になると思うのですが、ＬＥＤについてお聞きします。このＬＥＤですけれども、平成２１年１２月３０日に新成長戦略基本方針が閣議決定されております。商店街の活性というものをどうイメージされているのでしょうか。これは、そもそもこのセンターの役割は何でしょうかということです。その目標に対して評価というのはどういう評価をされているのかお聞きします。","respondent":"三ツ橋環境課長、山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"区といたしましては、環境面に関しましては、事業者用のＬＥＤ設置助成というものを実際に実施しております。大きく分けて３つの視点といいますか、まずは商店街で代表的な、１年に１度、大きなお祭りという意味のイベントの支援というような側面。武蔵小山創業支援センターの役割と目標についてですけれども、ほかの創業センターがものづくりの部分に力を入れているのに対しまして。","voiceIndex":233,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"ですから、２０２０年までにしなくてはいけない。それを計画的にされているのですかということを聞いているので、計画的にどういうふうな考えを持って進めていくのかお知らせください。それと、商店街の活性ですけれども、それで活性化になっているのですかと、非常に私は疑問を持ちます。では、その割には、品川区で商売している人というのはどれだけいるのですかということです。","respondent":"藤田都市環境部長、小林施設整備課長、山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"そうした中で、区のほうとして単独で今ＰＲに努めているなどというのはまだこれからの段階ですけれども。ただ、この蛍光灯の種類が、水銀の含有量が５ｍｇを超えるものについては２０２０年ということがあるのですが。区としましては、欠かすことのできない地域インフラの中心ということで支援を続けてまいりたいと考えております。各ステージに合わせて、創業の支援をしてまいっております。","voiceIndex":237,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"ＬＥＤは、計画を持ってやってください。街路灯をやっているわけですから、やれないわけがないと思いますので、しっかり計画を立てて進めていただくように要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１４３ページの環境対策費に関連して、羽田増便問題について質問します。この間、国土交通省による説明会が品川区で８日間、行われてきました。昨日も品川区での日程がありました。この間、品川区で行われた各説明会に参加した人数と合計数を教えてください。","respondent":"三ツ橋環境課長","answer":"羽田空港の機能強化に関する国の説明会の参加人数および合計の件数ですけれども、８日間ございまして、まず区役所で８月９日から１２日に行いましたところ、４６０名でございました。次に９月５日、アトレ大井町でございましたけれども、こちらは４００名でございました。","voiceIndex":244,"id":"exchange-108"},{"speaker":"のだて委員","kind":"意見","question":"９月２４日には八潮で、唯一のグループ討議の形式で説明会が行われました。八潮では、やはり約２０年前に上空を航空機が飛んでいたわけで注目も高く、当初の定員の５０人をはるかに超える１００名の方の参加があったということですけれども、区も説明会に参加していると思いますので、賛成、反対、どちらが多かったのか、どんな意見があったのか、紹介していただければと思います。","respondent":"三ツ橋環境課長","answer":"実際に、国主催ですので、詳細な部分につきましてはまだデータ等が来ておりませんのでお答えできないのですけれども、実際に私もその場におりまして、そのときの状況をお伝えしたいと思いますけれども、賛成、反対という、そういう立場ではないです。","voiceIndex":246,"id":"exchange-109"},{"speaker":"のだて委員","kind":"質問","question":"私のほうでは、八潮での行われたものについては、多くの方が反対だったと聞いております。結論先にありきのようだ。なぜ羽田なのか、中部空港や茨城空港もあるのではないかといった反対や不安の声がありました。品川区での説明会に参加した人は合計で１,０６０人ということで、区民のほんの一部にしか過ぎません。私はこれで理解が深まったとは思えませんが、理解が深まったと思うか伺います。","respondent":"三ツ橋環境課長","answer":"今まず、この夏の段階に国が初めてオープンハウス形式という形で説明会を始めたスタートです。したがいまして、ようやくスタートから１歩深まったと理解しておりますので、まずはスタートです。","voiceIndex":248,"id":"exchange-110"},{"speaker":"のだて委員","kind":"提案","question":"この協議会の資料には、関係自治体からの主な発言として、「国からの説明会等を通じ、自治体レベルでは、機能強化の必要性や、そのための飛行経路の見直しなどの、国が提案している内容について、理解が深まった」とあります。南風時には、つまり品川区の市街地の上を飛ぶ住宅地ルートに反対したのか、どう対応したのか伺います。","respondent":"三ツ橋環境課長","answer":"続きまして、品川区の南風案につきましての考え方ですけれども、これまでまずは東京都・２３区が連携いたしまして情報共有や意見交換を行いまして、国に対して、騒音等の影響に関する情報提供をするように求めてまいりました。","voiceIndex":250,"id":"exchange-111"},{"speaker":"のだて委員","kind":"質問","question":"国土交通省の協議会では、「理解が深まった」となっています。安倍首相は２月の施政方針演説で、「地元の理解を得て飛行経路を見直して進めていく」と発言しています。だからこそ地元品川区が反対表明をすべきだと思いますが、いかがでしょうか。国は品川区にどのように説明したのか、地元の理解を得ることは前提条件なのか伺います。","respondent":"三ツ橋環境課長","answer":"実際に、またちょっと繰り返しになってしまうのですけれども、まずは区といたしましても説明を求めている段階でございまして、区民の皆様に実際にどのようなルートなのか、実際、どのようなことが起こることがあるのかなど。","voiceIndex":252,"id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は、総理の発言、「地元の理解を得ていく」ということについて、それが前提条件なのかとお聞きしたので、もう一度ご答弁いただきたいと思います。","respondent":"三ツ橋環境課長","answer":"オープンハウスの説明会となっておりますので、まずはその段階と考えています。","voiceIndex":254,"id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"地元の理解を得るということが前提条件でないならば、今まだちょっとわからないみたいなご答弁ですけれども、なおさら地元品川区が反対表明をしていかなければ、説明会が建前になってしまい、国が決めたことを押しつけてくることになってしまいます。計画段階の今が絶好のときです。区長の反対表明を求めますが、いかがですか。","respondent":"藤田都市環境部長","answer":"担当の課長のほうからいろいろ申し上げておりますけれども、まず今の段階は、理解を深めていくための説明会を行っているところです。引き続き、しっかりとした説明を国に対して求めてまいりたいと考えています。","voiceIndex":256,"id":"exchange-114"},{"speaker":"渡部委員","kind":"質問・要望","question":"区の制度融資ですけれども、私ども自民党も常日頃より要望させていただいておりまして、継続して、３年間無利子の小規模事業特別事業資金なども、事務事業概要を見ましてもかなりの方々にご利用いただいていて、いい制度、これからも続けていただきたいのですけれど、品川区の制度融資を見ていきますと、十何種類あって、その中でちょっと気になったのが、事務事業概要をずっと見ていたのですけれど。","respondent":"山崎商業・ものづくり課長","answer":"委員おっしゃられたとおり、リーマンショックの後からは、１,１１８業種が全部、不況業種認定がされてきたということでございまして、先ほど、その必要型の融資の活用を軸にして、融資制度というのは品川区も対応してきたです。","voiceIndex":259,"id":"exchange-115"},{"speaker":"渡部委員","kind":"質問","question":"しかも、例えばＡ社という会社が、例えば業態を細かく見ていくと、これもやっている、あれもやっているとなると、それぞれの売上を全部ばらして見て、そこで前年同月比というか、前年直近３カ月比ですか、５％下がっていなければなどという。だから、もう面倒くさいから、ちょっとそっちでもういってしまおうかというようなケースが、これは出ているのではないかなと思うのですが、どうでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"ということで、５号認定を必要ではなくても同様の融資事業に応えられるような、区の制度の改善をもって対応してきているというような状況です。","voiceIndex":261,"id":"exchange-116"},{"speaker":"渡部委員","kind":"質問・要望","question":"それで、もう一件が、１５２ページの産業支援交流施設。当然、区民委員会で行ったばかりの頃、開いたばかりでしたから、まだ会員数はどれぐらいですかなどと聞いても、今までの会員からプラスアルファ増えたりなどというのはなかったのですけれども、今、１０月になりました。当初から大きいホールは様々な形で稼働しているとは伺っていたのですけれど、三カ月、四カ月経って、動きはいかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"それから４階のほうの交流室等の稼働ですけれども、４階の交流室の会員、オープンラウンジの会員が今現在、９月３０日現在になりますが、トータルで７６の会員様にご登録をいただいている状況です。","voiceIndex":263,"id":"exchange-117"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは開設して、あれだけのスペースで、見た方はみんなそうだったと思うのですけれど、３Ｄプリンタのすごいのが、もう世界に何台しかないですよというやつが入っていたりしまして、それ相当な施設です。立地条件のいいところですばらしい施設ができていますので、これから先、いろいろ広めていただきたいとも思うのですけれど、何かその辺の働きかけというのは行っていますでしょうか。","respondent":"立木産業活性化担当課長","answer":"近隣のオフィス等に関しましてはポスティング等を行っております。はいろいろコンテスト、交流会等を行っておりまして、会員になる機会のほう、勧誘等行っているところです。","voiceIndex":265,"id":"exchange-118"},{"speaker":"こんの委員","kind":"質問","question":"私からは１３８ページの予防接種費、そして２点目が１３９ページのこころの健康づくり事業、この２点をお伺いしたいと思います。初めに、こころの健康づくり事業ですけれども、先ほども他の委員からも質問が出ておりました。事業の評価について、アンケート調査も行って、結果、概ね成果が出ているという説明でありましたけれども、その点をもう少し詳しくお聞きしたいと思います。","respondent":"榎本荏原保健センター所長","answer":"そのような対応をしています。","voiceIndex":269,"id":"exchange-119"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる予防ではなくて、もう既に発症が心配される、こうした方が相談に来られていると考えます。そこで、その必要な道筋をつけるということですけれども、その道筋をつけるべく、いわゆる必要な医療機関につなぐ、デイケアをする。こうしたいわゆる相談者の後追いというのでしょうか、そうしたことへのケアというのはどのようにされていますでしょうか。","respondent":"榎本荏原保健センター所長","answer":"それで、初め、専門相談から入ってくるという場合もありますけれども、そういった中で、その後、その方に対して例えば受診を勧めた場合、治療が必要だということでお勧めした場合は、その後受診されましたかとか、その方に合った形で、必要な、適宜適切な時期にフォローして。","voiceIndex":271,"id":"exchange-120"},{"speaker":"こんの委員","kind":"質問","question":"フォローはしてくださっているということであります。そのうつ病というこの病について、自殺との関係と言われているところで区としても対策をとっていらっしゃると思いますが、この辺の自殺とうつとの関係、そしてこのうつ病は治る病気と言われておりますけれども、区の認識をお伺いしたいと思います。","respondent":"舟木保健予防課長","answer":"自殺をした方の約９０％の方が何らか直前までに精神疾患を発症していると言われていて、自殺で亡くなる方の危険度は、うつ病とそうでない人を比べると非常に危険度に差があるということで、３００倍ぐらいあると言われていて。","voiceIndex":273,"id":"exchange-121"},{"speaker":"こんの委員","kind":"質問","question":"うつ病、治る病気というふうに言われていますが、その認識はいかがでしょうか。","respondent":"舟木保健予防課長","answer":"うつ病につきましては、いろいろ一人一人、症状とか治療等は違いますが、まずは休養をとって心と体を休ませることが大事だということで、適切な治療を受けて環境を整えて症状を落ち着かせることができれば、しっかり治ることもできますし。","voiceIndex":275,"id":"exchange-122"},{"speaker":"こんの委員","kind":"質問","question":"今ご説明があったような環境が整えば、うつ病の治るという方向性に向かうというご説明でしたので、そうなると、この健康づくりの中には、うつ病対策のそうした具体的な対策というのは見えない、ないというふうに私は理解してしまうのですが、いかがでしょうか。","respondent":"榎本荏原保健センター所長","answer":"先ほど、ご相談やデイケア事業等のご説明をさせていただきましたけれども、そのほか、例えば今年におきましても、うつ病の知識と理解ということで、ご本人もしくは家族の方に向けて、そういった講演会なども行っております。様々な支援力の向上という意味での対策もしています。","voiceIndex":277,"id":"exchange-123"},{"speaker":"こんの委員","kind":"質問・要望","question":"この点、非常に難しい問題ではありますが、大事なことでありますので、今後、考えていっていただきたいなと思います。そして、先ほどもありましたけれども、「財政を勘案してワクチンの助成制度、助成を検討していく」とありましたので、ぜひ一日も早くご検討をお願いしたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":279,"id":"exchange-124"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは１４９ページ、しながわ巡りアプリ、１４３ページ、環境対策費について関連して聞きたいと思います。時間があれば１４５ページ、資源回収事業。しながわ巡りアプリですが、平成２６年度決算で１,１００万円の作製経費がかかっているというところで、平成２７年３月２７日からスマートフォンに向け配信が始まりました。その推移がわかれば、その推移について教えていただきたいと思います。","respondent":"間部文化観光課長、三ツ橋環境課長","answer":"観光協会に委託してということですけれども、こちらは観光協会のホームページ、アプリも同じ内容ですけれども、やはり神社のお祭りですとか、個店の案内ですとか、そういった部分の表記もあることから。こちら、平成２５年度におきましては２,４００万枚、それから平成２６年度につきましては２,５００万枚となっています。","voiceIndex":282,"id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"それで先ほど、しながわ巡りアプリについて我が会派の松永委員からも質問がありましたが、タイ語への検討というのもされていくという中で、そうした更新費というのはまた別途かかってくるのでしょうか、それを教えていただきたいと思います。個店への案内などというところで、個店の案内というのはどのような選定がされたのでしょうか。品川区においてもさまざま取組みをしているところであると伺っています。","respondent":"間部文化観光課長、三ツ橋環境課長","answer":"タイについては、今回、補正予算でも組ませていただきまして、マップをつくったりということもやっているのですが、訪日外国人数の中で第６位ということで、かなり国のポテンシャルも強く、今後増えてくるということで。そのほか、裏面活用以外にもＮアップ化、２枚一遍に印刷できるとか４アップ化など、推し進めているところです。そのほか、会議資料の部数の適正枚数ということも考えております。","voiceIndex":285,"id":"exchange-126"},{"speaker":"大倉委員","kind":"質問・要望","question":"は一方、例えば巡りアプリというわりには、地元の道場とかが入っていたりジムとかが入っていたり、この辺、訪れてどうなのかなというところが、ちょっと不思議に思っているところと、あと例えば競馬や水族館というところで、水族館が出てこなかったかなと思っているのですけれど、そういったところの改修とか、その辺は１,１００万円で収まるのかどうか、またかかってきてしまうのかどうか教えてください。","respondent":"間部文化観光課長、三ツ橋環境課長","answer":"改修につきましては、コンテンツの変更については観光協会の職員が行っていますので、その部分の経費についてはかからないです。今年度から、しながわエコリンク、職員が推し進めておりますＩＳＯから変わった環境マネジメントシステムの中ですけれども、その中では環境目標といたしまして、平成２１年度の実績が目標値となっています。","voiceIndex":288,"id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問","question":"この縛りを、大分近づいてきたわけですけれど、オリンピック・パラリンピックも決まったりしているわけですから、これをチャンスと捉えるならばというところがありますが、基本的にこの縛りも含めて、今後、何か物を申していこうとしているのか、このままで、しようがない、平成３２年が来るまで我慢するかというスタンスでいくのか、そこら辺のところをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"オリンピック・パラリンピックを前にして、返還の時期がちょうどその時期だというところは、返還といいますか、譲渡される時期はそこだというところはありますけれども、そういったオリンピック等々をチャンスと捉えて、区として有効に使えるような形でということで。","voiceIndex":292,"id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひ積極的にとお願いしたいのですけれども、そうなると、オリンピックとかパラリンピックで考えると、水の利活用、そういう中に入っていくと土木費になってしまうかもしれないので、それはやらないけれども、水の利活用とか、そういう、いろいろ使いたい部分があるじゃないですか。だけれども、もしそのときに間に合わせようというのだと、建物をどうするかとか、いろいろなことがあるじゃないですか。","respondent":"柏原企画調整課長","answer":"これまでもいろいろな形で環境局に話をしてきたところです。やりとりの中では、平成３２年３月で切れるわけですけれども、その前の段階で、例えば少し取り壊しに入ってもいいのかどうかというやりとりはしてきたところです。","voiceIndex":294,"id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは品川区の一つの財産にもなると考えていますので、ぜひ区長会でも言っていただきたいと思いますし、今、議長もいらっしゃいますけれども、議長からもぜひ一緒になって、そこの部分の話を早く進めていければなと考えています。それの中でもう一つ、し尿処理場のことで伺いたいと思っています。毎年、量も減ってくる。そういう模索というのはできないのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"品川自体から言えば、それは十数件なのですけれど、全体の数から言うと、平常作業を継続せざるを得ない形になっております。","voiceIndex":296,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問","question":"去年の実績は１万５,０００トンぐらいだそうでありますけれども、そう考えてくると、これからだんだんそういうふうになってくるわけじゃないですか。そうすると、一体でやるにしても、品川区の裁量でできるのではないのかなと、ちょっと思ったのだけど、そういうことというのは模索としてできないですかねというのをもう一回ちょっとお聞きしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"ただ、将来的に、品川区に立地しているので、その施設全体の稼働の有効活用という形でご相談する余地は全くないとは思わないのですけれど、今の委託運営で清掃一部組合が全体管理をしている上では、なかなか品川区として運営に立ち入っていくことが難しいのかなと考えております。","voiceIndex":298,"id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"意見","question":"あそこはすごく広いし、有効活用するということになれば、これも結構、品川区の財産になる場所でもあると思っていますので、ぜひ模索をしていただくことをお願いだけしておきます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":300,"id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つは産業経済費全体のこと、そして２つ目が成果報告書１４８ページの「伝統の技と味しながわ展」、１４９ページ、消費生活展についてお尋ねします。時間があれば商店街のこともお尋ねしたいと思います。成果報告書の最後の決算状況一覧表を見ると、割合は１.１％。事業の執行状況の点と、この数字との関係、先ほどの産業経済費の展開について、２点お尋ねします。","respondent":"山崎商業・ものづくり課長","answer":"このように、産業を取り巻く領域というのは、地域特性が非常に重要でございまして、それに応じた施策を展開するというようなことですので、一律に各区の総決算額に対しての産業経済費というような評価というか見方というのは。","voiceIndex":302,"id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"中小企業および商店街、そして区の経済の活性化のために引き続き施策を展開していっていただきたいと思います。ありがとうございました。ちょっと個別の話になるのですが「伝統の技と味しながわ展」、それから消費生活展についてなのですが、この２つのイベントについては、事業目的、内容、そしてこれまでの開催回数などをお尋ねします。よろしくお願いします。","respondent":"山崎商業・ものづくり課長","answer":"「伝統の技と味しながわ展」のほうです。こちらは毎年１月の下旬にきゅりあんでイベントホールにて開催しているものです。","voiceIndex":304,"id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのような形で、本当に毎年楽しみにされている方もいらっしゃるのですが、その一方で、ブース、そして来場者の方々の固定化という、いわゆるマンネリがあるのではないかと思います。今年も非常に興味深く見ていらっしゃる外国人の方がいらっしゃいました。ということで、外国の方に対する具体的なＰＲ等を含めて、今後どのような形でマンネリを解消していくか、お考えを伺います。","respondent":"山崎商業・ものづくり課長","answer":"ただ、見せ方としまして、実際に子どもたちの実演ですとか教室など、展示を見るだけではない、触れていただくようなことを工夫するとともに、委員おっしゃられました、こうした日本の伝統に培われた展示会こそ外国の方にとっては非常に興味深い部分だと認識しております。","voiceIndex":306,"id":"exchange-135"},{"speaker":"若林委員","kind":"質問・要望","question":"１５１ページの共通商品券普及促進事業と、１４０ページの公衆便所費の２点をお伺いいたします。そこで何点かご質問しますが、まず事業費としての７億７,０００万円ですけれども、どれぐらいの消費喚起を想定されて、どのような成果が上がったのかというのを１つお聞きしたいと思います。それから２点目に、いわゆる事業の主体者というのでしょうか。以上、何点かお答えいただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"先ほどアンケートのほうは、４月に春の分は発売しまして、購入者より無作為抽出で６,０００名にアンケートを送付するような形で実施してございまして、現在、回収率３５％で２,０００件ほどの回収があったというようなことです。","voiceIndex":310,"id":"exchange-136"},{"speaker":"若林委員","kind":"質問・要望","question":"今後、平時においてプレミアム付区内共通商品券、例えば先ほど言ったような小規模に特化したとか福祉的な目的に、様々な鋭い感覚で、平時においての事業を立てられると考えていますので、時間がありませんけれども、質問としては、しっかり商品券については検証・分析をして、次年度の予算に反映していただきたいということが１つ。この２点についてお考えをお聞かせいただきたい。","respondent":"山崎商業・ものづくり課長","answer":"プレミアム付区内共通商品券につきましては、いろいろな経済の動きがあります。これをしっかり踏まえまして、今回のものを検証しつつ、次年度、あるいは消費税の改定なども今後予定されておりますので、そうしたものの動向を注視してまいりたいと考えています。","voiceIndex":312,"id":"exchange-137"},{"speaker":"本多委員","kind":"質問・要望","question":"成果報告書１３９ページ、各種がん検診、２つ目は１４５ページの水辺とみどりの行動計画推進事業について質問します。こういう、全般的に民間活力についてもお伺いしたいと思います。それと、がんに２人に１人がかかり、３人に１人がお亡くなりになる時代ということなのですけれども、この現状を捉えて、がんにかかっても治るのだという部分のケアの考え方、進め方についてお知らせください。","respondent":"川島健康課長、柏原企画調整課長","answer":"今お話にございました、企業と連携しまして事業を推進するですが、４月に発行しましたしながわ健康プラン２１の協力団体、協力企業というところで、幾つか企業の皆様のご賛同が得られたというところで。そういったところ、アンテナを張りながら、民間の知見等々を、積極的な活用というのは今後進めていきたいと思ってあります。","voiceIndex":315,"id":"exchange-138"},{"speaker":"本多委員","kind":"質問","question":"がんの宣告なのですけれども、この方法を把握されていますかという質問なのですけれども、我が会派の専門家からレクチャーを受けました。それで２０年ぐらい前は、がんを発見しても、本人に言わないケースが多かったです。家族を呼んで宣告、告知をして。その辺の不安や心配を区として把握されているのか、その辺の課題についてはどう取り組まれるのか、お聞かせください。","respondent":"川島健康課長","answer":"こちら、ＰＤＦでダウンロードできるものですので、こういったものも参照していただきながら、がんの治療をして社会復帰をして仕事を続けていくといったことの支援をしていきたいと考えています。","voiceIndex":318,"id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"よろしくお願いします。本当にこのケアが大事だと思います。その辺とあわせて、以前、厚生労働省の取組みで、「受診率が５０％を目指す、がん検診企業アクション」というのがありましたけれども、そういう、もっと現状の受診率と比べて、こういう目標値、大分かけ離れているのですが、その辺というのはどういうふうにお考えでしょうか。","respondent":"川島健康課長","answer":"私どもが行っております検診は、主なものは、国、それから都の指針に基づいた形でやっているので、少し特色を出して何かやるというのが、なかなか難しい現状にあります。","voiceIndex":320,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"最後、１４５ページの水辺とみどりの行動計画のほうで聞きますけれども、いろいろと水辺に関しては、本当にいろいろな取組みで、五反田に続き、各、品川橋やしながわ水族館、大井競馬場で乗り降りができるような水辺の交通網の整備をお願いしたいと思うのです。花見のシーズンですとか、両者がうまくすみ分けができればと思うのですが、その辺の課題やルールづくりをどう思われるかお聞かせください。","respondent":"和田河川下水道課長","answer":"基本的に船の航行は自由ですけれども、一定のルールやマナーを守っていただけるよう、区としましても何かしらの対応をしていきたいと考えています。","voiceIndex":322,"id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１４８ページの就業支援事業について伺いたいと思います。働く人の３人に１人が非正規雇用、若者の２人に１人が非正規雇用という深刻な実態なわけです。そして研修中、体験している最中は、給料というのでしょうか、お金も出ると。これが平成２７年度から少し中身が変わっているということですけれども、なぜ変わったのか、どう変わったのかをちょっとお聞かせください。","respondent":"立木産業活性化担当課長","answer":"そういった関係もございまして、一旦、こちらの事業を受託した企業の契約社員という形になりまして、それで１カ月半の研修と３カ月の体験という形を組んで実施したものです。","voiceIndex":325,"id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問","question":"国の補助金が出ていたけれども、これがなくなって、平成２７年度からは区の財源でこの事業を続けていると。事務事業概要のほうで、若者就業体験事業のフォローアップ研修というのがあったのですけれども、この体験事業で就職した若者たちが早期離職することがないようにフォローアップ研修を行うということですけれども、この具体的な研修内容を教えてください。","respondent":"立木産業活性化担当課長","answer":"国の補助金としてはなくなりましたけれども、こちらの形、事業スキームを、ちょっと形を変えたものとして平成２７年度も引き続き行いまして、若者の就業支援で、体験事業のみならず、そのほか就業相談等も交えまして、多様な形で就労支援をしていこうという形で残したものです。","voiceIndex":327,"id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"働く意欲につながっていくと。就労に悩む子どもを持つ親御さんへのＰＲ、また若者がよく立ち寄る場所、コンビニだったりネットカフェだったり図書館だったりと、こういうところにＰＲのビラやらパンフレットを作成して置いていくなどしていったらいいのではないかなと思うのですけれども、その周知とＰＲについて拡充を求めたいのですが、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"今後のＰＲのほうも経済状況等も交えまして、こちら、区の重点施策になっているということもあります。はいろいろな多様な就業のほうが求められるような時代ですので、そういった世の中の情勢を見ながら周知の方法等についてはいろいろ検討してまいりたいと思います。","voiceIndex":329,"id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ多くの人にこの実績と事業の周知をしていただきたいなと思います。そこをちょっと伺いたいと思います。それと、若者の働く問題としては、ブラック企業に苦しむ実態も深刻です。品川区も、「働く環境の悪化は重要な問題だ」というふうに答弁もされているのですけれども、ブラック企業対策について、現在、品川区ではどんなことが取り組まれているのか伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"あと区内のブラック企業対策に関してですけれども、こちらの区のほうの権限では、企業の立ち入り調査等というのは法令上しっかり分けられておりますので、こちらはそれぞれ法が管理するところの労働基準監督署でありますとか東京都と連携をとりまして。","voiceIndex":331,"id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、ブラック企業のほうですけれども、都との連携というのはこの間もずっと伺ってきたのですけれども、国のほうでは青少年雇用促進法が成立しました。確かに、企業に直接、物は言えないかもしれないのですけれども、そういった若者たちへのフォローアップということで、何か対策を打っていただけないかなと思うのですけれども、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"ハローワークに関しましても連絡を取り合ってありますので、もし仮に、例えば求人票と実態が違うというような相談があった場合には、そういったものもハローワーク等にきっちり伝えて、連携をとるような形で就労支援を行っているような状況です。","voiceIndex":333,"id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり若者一人一人が安心して意欲を持って働くということは、これからの品川区にとっても大変プラスになることだと思います。それを支援する対策をさらに充実させていただきたいと思います。若者サポートステーションの創設と、そしてブラック企業対策、さらに充実させていただきたいと思いますけれども、再度求めたいと思いますけれども、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"雇用情勢に合わせて、そちらの件に関しては研究してまいりたいと思います。","voiceIndex":335,"id":"exchange-147"},{"speaker":"たけうち委員","kind":"質問","question":"私は、１５０ページの商店街活性化事業全般で伺いたいと思います。幾つか商店街について出ておりました。非常に頑張って取り組んでいただいていると考えています。比較するわけではないのですけれど、１０７ページに地域振興費の町会支援かな。地域の町会支援が約１.９億円ということで、それに比べても倍以上かけて商店街を支援しているという、これについての区の認識、見解をお知らせください。","respondent":"山崎商業・ものづくり課長","answer":"私ども、商店街振興の部門も、広く区の組織では地域振興部というような組織でございまして、商店街、それから町会なども含めまして、さまざまコミュニティの核としての団体ですので、区全体としましても、どちらというわけでもなく、双方、必要なパートナーであり。","voiceIndex":338,"id":"exchange-148"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。多分、おそらく我々、委員の方々も同じような認識だと思うのです。そうした中で、実際に区が期待する役割などというものについて、区商連の方たちもそういう認識を共有していただいていると思っていいのかということと、またそういうことについてお話し合いをされている、そういうことがあるのかどうか、教えていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"もちろん商店街の方々、それから商店街連合会という組織、こちらの組織目標も、地域に根差した商店街の発展というようなところで、区と認識をともに同一というようなことで共有しているというようなことです。","voiceIndex":340,"id":"exchange-149"},{"speaker":"たけうち委員","kind":"質問","question":"それで、また今回、区民委員会に所属しておりますので、今回の視察でも、北九州市で活性化条例というのをつくっているということで、これを勉強しに行ってまいりますけれども、条例をどうのこうのというのもありますけれど、ただ、そういう位置付けをしっかり明確にして、区民にもやっぱり理解していただいて、区民も商店街を応援していこうと思っていただけるような取組みが必要なのかなと思うので。","respondent":"山崎商業・ものづくり課長","answer":"条例などにつきましては、品川区の産業施策の根幹、長期基本計画で施策体系をとりまして、商店街の位置付けなども計画上はしっかり明記していますので、区としましては、そうした計画的な行政運営という観点で。","voiceIndex":342,"id":"exchange-150"},{"speaker":"たけうち委員","kind":"質問・要望","question":"条例については、これから区民委員会でもしっかり勉強するので、あまりそう言われてしまうと勉強しにくくなる。頑張っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-151"},{"speaker":"松澤委員","kind":"質問・要望","question":"１５１ページ、３目中小企業対策費、プレミアム付区内共通商品券発行助成に関連して、東京さくらツーリストの被災地応援ツアー商品券の不正受給についてお聞きいたします。そこで質問いたしますが、不正受給された３２６万円は平成２３年度から平成２６年度となっています。これについていつ返還を求めるかについてお聞きしたいと思います。","respondent":"間部文化観光課長","answer":"そのうち東京さくらツーリストについては１件ございまして、参加人数１１６名ということで申請をいただき、不正受給の枚数は７９人分、７万９,０００円が不正があったです。","voiceIndex":346,"id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。数字を聞きます。平成２６年度、単年度の東京さくらツーリストの被災地応援ツアーのツアー数と不正のツアー数をお聞きいたします。","respondent":"間部文化観光課長","answer":"平成２６年度のツアー数ですけれども、３１ツアーで１,５６４名の参加という形になってあります。","voiceIndex":348,"id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"数字がわかりました。数字を聞きます。改めて、不正を除いた平成２６年度の被災地応援ツアーの参加者数を改めてお聞きしたいと思います。","respondent":"間部文化観光課長","answer":"平成２６年度の、まず全体の数ですが、１,５６４名の参加になってございましたが、実績として、１,０３９名分が正しい参加者数です。今のは平成２６年度です。","voiceIndex":352,"id":"exchange-154"},{"speaker":"松澤委員","kind":"質問","question":"聞いたのは、平成２５年度、平成２６年度。この年は被災地ツアーが縮小されまして、東北地方だけになったのです。申請旅行が１８社、平成２５年度、平成２６年度が８社ですけれども、これのやっぱり正確な人数を知らないと質問も何もわかりませんので、数をしっかりお願いします。","respondent":"間部文化観光課長","answer":"すみません。数字の部分で、申し訳ございませんが、不正の数ということでよろしいでしょうか。実数ということですか。","voiceIndex":356,"id":"exchange-155"},{"speaker":"松澤委員","kind":"質問","question":"数字が出ないなら、それはそれでいいです。応援してくれたらツアーを組むよ、これは違反ではないのですか。ツアーを組むの、１０月１０日。３,２６０枚。５００円券ですから、この場合、６,５２０枚。これをどうして換金できるのですかね。ですから、全体の業者をやってしまっては本当に気の毒ですから、こういう不正を働いた業者は区商連から排除すべきだと思うのです。これについて見解を伺います。","respondent":"山崎商業・ものづくり課長","answer":"商品券の取扱いにつきましては、通常、プレミアム付区内共通商品券などでもそうなのですけれども、２,０００店舗が商品券の取扱いが、今、総数でできておりまして、そのうち約２００店舗につきましては、区商連に加入していない事業者が取り扱っているということで。","voiceIndex":358,"id":"exchange-156"},{"speaker":"松澤委員","kind":"質問","question":"だから、それについて、１年たったら排除をしっかりできるのですかということ。","respondent":"山崎商業・ものづくり課長","answer":"秋も１１月の発行に向け、今、取扱いの商店の確認をさせていただいているところでございまして、そういう意味では当該事業者も、今、秋のプレミアムの取扱いについて確認の事務作業をさせていただいているというような状況です。","voiceIndex":360,"id":"exchange-157"},{"speaker":"松澤委員","kind":"質問","question":"推移を見守るではなくて、不正が明らかで返金までしているのですから、こういう業者は排除しますと言ってくれればいいのですよ。それを言わないで推移を見守りますなどと言ったら、まだまだ先になってしまうじゃないですか。本当、私はもう、お金を返したと言っているのですよ。だから業者として何ともないんだ。これでは不正を助長するようになる。お願いします。","respondent":"山崎商業・ものづくり課長","answer":"それについては、今月の中旬には決定するようなことですので、接触ができないなり連絡がとれないということであれば、そうした取扱いについては辞退をしていただくようなことで、区としては、あるいは区商連としては考えているというようなところです。","voiceIndex":364,"id":"exchange-158"},{"speaker":"松澤委員","kind":"質問","question":"もう一枚、本当に大きいことを言おうとしたのですけれど、時間がなくなってしまいました。今年度、２０％のプレミアムがつくということで、これからいろいろ東京さくらツーリストを通じて旅行をしようという人がいっぱいいたのです。それは取り消したのですけれども、質問ができません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"私は１５１ページ、今日いろいろ質問が出ています、プレミアム付区内共通商品券の発行についてお聞きしたいと思います。先ほどもほかの委員から質問がありましたが、区が助成しているプレミアム付区内共通商品券発行の経済効果。これは毎年やっていますが、これは実際、消費の押し上げ効果がどこまであるのか。毎年のやっている事業に対して、ちょっとその辺について教えてください。","respondent":"山崎商業・ものづくり課長","answer":"これは商品券の使途とともに、手持ちの現金を追加して品物を買うというようなこともありますので、そうしたものもあわせて消費喚起効果としては３割はあるだろうというようなことで、区としては分析をしているというような状況です。","voiceIndex":368,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、そこで浮いた金額を全て貯蓄に回したり、また既に、毎年決まっているかもしれないのですが、対象地域への旅行を計画していた団体、人が、旅行費に充てるためだけに使用することになれば、同様に浮いた金額を全て貯蓄に回したりしてしまえば、消費を喚起する効果は全くなくなると思いますが、この辺についてもどのようにお考えでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"品川区におきましては、リーマンショックの経済危機以来、平成２１年度からプレミアム付区内共通商品券の発行事業を行っています。こちらのほうは、通常の商店街支援に加えて２層構造で、緊急の経済の対策というようなことで、これまでやってきているです。","voiceIndex":370,"id":"exchange-161"},{"speaker":"須貝委員","kind":"意見","question":"私は、ちょっと経済状況が変わってきたのかなと思っているのです。すなわち、どういう状況がまちの中に起きているのかというと、家計が消費を抑制しているという状況に今変わってきたのではないかと思うのです。したがって、今までのようなプレミアム商品券発行方法はもう考え直す時期に来たのではないかと思うのですが、ちょっとご見解をお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"ただ、やはり儲かっている商店、企業と、それからちょっと苦しいなというところが、どうしても二極化する傾向にあって、そういう意味では、平均的には上がっているのですが、二極化の下のほうの部分について。","voiceIndex":372,"id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"区でも東京都でも、商店街への様々な取組みをしています。でも、現実、どうでしょうか。我々も歩いていて見るのですが、ああ、ここは、よりにぎやかになったね。逆に、後継者がいない。そして、シャッターがやはりだんだんおりていく。この中に記載されている国の事業の中で、低所得者向け支援とか多子世帯支援なども書いてありますが、これは、区ではこのことについてやっているのですか、お答えください。","respondent":"柏原企画調整課長","answer":"今回、この交付金は消費喚起という大きなテーマがありましたので、今回の部分については、プレミアムの率のところであるとか配付の仕方とか、そういうところを工夫して、そちらのほうに今回、交付金は、我々の区としては割り当てたということで、特化した形では行っていないです。","voiceIndex":374,"id":"exchange-163"},{"speaker":"須貝委員","kind":"意見","question":"国でもそういうふうに、本来ならば低所得者向けとか、いろいろ使ってくれとありましたが、それは各自治体に任されているから、そのように使ったという話です。それでまた、発行する時期を知らない。すると、税金を使って実施しているのに、一部の方しか使えない、一部の人しか買えないということは、区民に対する平等・公平にあるべき自治体の事業としては間違っていませんか、お答えください。","respondent":"柏原企画調整課長","answer":"今まで行っていたプレミアム付区内共通商品券のスキームがあります。今回、国のほうの考え方でより一層の消費の喚起というところ、大きなテーマがあったです。","voiceIndex":376,"id":"exchange-164"},{"speaker":"須貝委員","kind":"意見","question":"ですが、やっぱりこういうところに目を向けて、特に低所得者層に関しては、やはりそれなりの支援をしていくという形を私はきちっと確立すべきではないかなと。そして、税金を使ってやる以上は、やはりできるだけ多くの方にこういう恩恵が回るような仕組みづくりをしてほしいと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":378,"id":"exchange-165"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１３７ページの職員給与費になるかと思います。常勤の保健師の人数をまず伺いたいと思います。内訳とか、細かいことはいいですから実数でお願いします。それから１４７ページの粗大ごみ中継所維持管理費、それから、ちょっと話題になっております商品券、そしてＳＨＩＰについてもお伺いできればと考えています。２点あわせてお伺いします。","respondent":"米田人事課長、柏原企画調整課長","answer":"保健師の人数ですが、平成２７年４月１日現在で４０名です。それを一旦、全部、都に返すということになりますと、一部といいますか、返す、お渡しするということになると、ちょっとまた話が少し複雑になって、何といいますか、ちょっと方向性が違ってきたりなどということがありますので。","voiceIndex":380,"id":"exchange-166"},{"speaker":"あべ委員","kind":"提案","question":"母子保健、あるいは子育て支援、高齢者認知症、地域包括ケア、精神保健、様々な役割を担ってくださっている方々、品川は今、３７万人の人口の中で、保健師４０名ということです。１万人当たり１人ちょっとという感じでしょうか。２３区の中でも、見ておりますと、１万人当たり１人程度というのは非常に少ないです。それから中継所のほうは、急なご提案でしたので、ぜひご検討をいただければと考えています。","respondent":"米田人事課長","answer":"そういった中では、事業によっては時間的に限られているものについては、非常勤の専門職の活用であったりというようなことでやっているものですので、今後とも所管の状況をよく踏まえて、適正な人員配置に努めてまいりたいと考えています。","voiceIndex":383,"id":"exchange-167"},{"speaker":"あべ委員","kind":"質問","question":"少しずつ増えているというのは数字の上でもあるかと思います。ぜひ前向きに計画を立てていただければと思います。それで、商店だけが対象になり続けるということが、どうバランスを維持していくのか。区として、こういった声をどう受けとめ、どう整合性を図っていくのか、そのお考えをお示しください。あわせてＳＨＩＰについて伺います。先ほどホール利用率が７割を超えて、非常にいい数字だと思います。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"その中には、例えば畳屋、畳を交換するような事業ですとか、ガラス店でガラスを交換するというようなところも含まれてありますので、一定そうした、バランスよく使いやすい。引き続きこういった形のものと、あとは、やはりサインに関しまして、ビルの１階の部分に、ちょっとレンタルでサインを出せるような場所もありそうですので、そういったものと、あと大崎駅のウエルカムビジョンのほうに。","voiceIndex":385,"id":"exchange-168"},{"speaker":"あべ委員","kind":"質問・要望","question":"先にＳＨＩＰのほうなのですけれども、ぜひ努力をしていただきたいと思います。７割あるというホールの稼働率ですが、何をやっているかというのが周りの人に見えないのでは、その存在自体がわからなくて、地域の方にも、やっぱり区立の施設ですので、どういったことをやっているのかということをわかってもらい認めてもらえるようにしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":388,"id":"exchange-169"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めに、しながわ健康プラン２１が今年の４月に策定されたと思います。これは、国のほうでは平成２５年に健康日本２１（第二次）が改正されたわけですけれども、これも踏まえながら、しながわ健康プラン２１ができたと思うのですけれども、その中で、私は健康格差の縮小というところについてお伺いしたいと思うのですが、国の健康日本２１では健康寿命の延伸と健康格差の縮小ということが打ち出されました。","respondent":"川島健康課長","answer":"品川区は品川区として健康寿命を延伸するという目標をこのプランの中で掲げまして、それを実現するためのものです。健康格差につきましては、そういったものがあるというのは国のプランにもはっきりと書かれてありますので、そういう認識でこちらのプランを策定しています。","voiceIndex":390,"id":"exchange-170"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しながわ健康プラン２１というのが、５年目で見直していくということもありますので、この中にはぜひともこれを位置付けていただきたいと思いますけれど、いかがでしょうか、ということで、後でそれはまたご答弁をお願いしたいと思います。さらなる充実を求めて質問をいたします。それから、この３５歳からの健康診査については、周知をどのようにしているのかということについても伺いたいと思います。","respondent":"川島健康課長","answer":"こういった話を踏まえてですけれども、やはり栄養状態の話、それから運動習慣の話、全て総花的と言ったらあれなのですけれども、健康プランの中には区民の方の健康づくりを促す活動を盛り込んでおりますので、そちらはそういった認識でやっております。","voiceIndex":392,"id":"exchange-171"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、そこのところに、「会社で健診を受けている方以外が対象です」ということを書いていただけばいいわけですから、そういうふうに文書が届くと自覚すると思いますので、ぜひそういう周知をお願いしたいと思いますが、いかがでしょうか。正常は２７％しかいないのです。それから、いつも石田ちひろが求めているように、歯科検診をぜひ入れていただきたいと思うのですけれど、いかがでしょうか。","respondent":"川島健康課長","answer":"それから年齢拡大なのですけれども、こちら、メタボリックシンドロームの強く疑われる者、その割合が増える４０歳ぐらい、その前の段階の３５歳からやるということで、この３５歳からという健康診査をつくったばかりのところですので、この健診のほう。","voiceIndex":394,"id":"exchange-172"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ歯科検診を入れていただきたいということを一つ要望したいと思います。こんなに多くの区ががん検診の自己負担無料にしているのだなということを私たちも驚いたわけなのですけれど、ぜひ、健康格差解消からも、このがん検診の無料化をしていただきたいと思いますけれど、いかがでしょうか。これもしっかりと私は目標値を入れてこそ取組みができるのではないかと思うのですけれど、いかがでしょうか。","respondent":"川島健康課長","answer":"区のがん検診は９種類、無料が３つ、それから有料が６つというような形ですが、基本、受益者負担というか応益負担の考え方で、単価が高いようなものですとか、それから先進的に取り入れたものというのは一部負担という考え方でやらせていただいておりますので。","voiceIndex":396,"id":"exchange-173"},{"speaker":"浅野委員","kind":"質問・要望","question":"これについて、この差は何なのかということを一つ教えていただきたいのと、あとこのシステムですけれども、区有施設の電力使用量を集約するシステムとして構築されたということですけれども、前に一般質問の答弁でいただいたのは、「公設民営の施設については、タイムリーに把握できないという課題がある」と、そういうこともありました。","respondent":"三ツ橋環境課長","answer":"こちら、ＯＳのサポート切れ、今年度がサポート切れとなっておりますので、再構築を実施したものです。次に、公設民営の件ですけれども、複合施設、例えば高齢者関係の複合施設などにつきましても、実際にデータとしては対応できる状況になってあります。","voiceIndex":399,"id":"exchange-174"},{"speaker":"浅野委員","kind":"質問","question":"システム再構築サポート切れということ、ＯＳですかね、サーバーですかね、そちらのほうが切れたということですけれども、本来であれば、前の年あたりに、予算ですかね、予算を立ててやらないといけないことかなと思ったのですけれども、たしかＸＰですとかサーバー関係も随分、Windowsのほうでサポート切れというのがありまして、その中の一つかと思います。","respondent":"三ツ橋環境課長","answer":"それらの動向を踏まえまして、区といたしましても、そろそろ３計画、こちらは環境計画、また実行計画、地域推進計画のことを指しますけれども、そちらに関しましてもそろそろ整合性をとらなければいけない段階ではないかと考えています。","voiceIndex":401,"id":"exchange-175"},{"speaker":"浅野委員","kind":"質問・要望","question":"この分かれている理由について教えていただきたいのと、平成２６年度の指導については３,０００平米以上のほうが２１棟、１,０００から３,０００平米未満が３３棟、立ち入り調査の実績が１１８件というような数字が出ております。これは対象となる建物の総数というのは何棟になるのか、それを含めて教えてください。","respondent":"小林品川区清掃事務所長","answer":"一点、保管場所の件ですけれど、保管場所は住宅系と事業系とがあります。総戸数２０戸云々というのは住宅系の保管場所の基準です。一方、こちらに書いてあります事業系のほうは、基本的には３,０００平米以上の事業系の建物という内容の記載です。","voiceIndex":403,"id":"exchange-176"},{"speaker":"浅野委員","kind":"質問","question":"毎年やるのか、それとも何年かに１回、回ってくるのかということと、あと管理責任者講習会、これは年に２回ですか、行われたということですけれども、具体的に何棟、何人の方が参加されたのか。全体から言いまして、これは、何といいましょうか、満足する人数が参加されたのかどうか教えてください。","respondent":"小林品川区清掃事務所長","answer":"それで、概ね、この対象、一つは現場に一緒に行って、管理責任者と一緒に話し合いながら減量やリサイクルを話すという立ち入り１１８件と、そうではなくて、効率的にやるために文章の審査で対応する部分とに分けて効率的に執行しております。","voiceIndex":405,"id":"exchange-177"},{"speaker":"渡辺委員","kind":"質問・要望","question":"でも、やはり区が一番大事に把握すべきは、多くの区民の方々の意見だと思いますので、確認で聞かせていただきます。これぞまさしく現場を見ていただきたい。というのは、商店街事務所等で販売していた頃と、今の郵便局の協力や土日の販売も考慮した、この待っている方、買う方々の顔ぶれ、年代層、そんなところから、一番伺いたいのは、積み重ねの大切さを感じています。その姿勢を伺えればと思います。","respondent":"山崎商業・ものづくり課長","answer":"より広くプレミアム付区内共通商品券を扱っていただくために、１口１万円でずっとやってきたものを、今回から５,０００円に分割したということで、これも先ほど来、アンケートをとりまして、買いやすくなったよというようなことの声が多数来ていますので、今回、秋についても。","voiceIndex":408,"id":"exchange-178"},{"speaker":"渡辺委員","kind":"質問","question":"そういう認識でおります。それと、地域交流支援のところ、この事業を、実際２９、ある程度、これも全区的に後々聞けば、この制度を活用して、まさしく人と人とをつなげる役割、先ほど来、町会との兼ね合いもありました。これから町会支援の条例が準備なされている。この企画自体はすごく奥深いものだと思っています。このマイクロチップを使うことの利点と、もちろん課題もあわせてまず伺えればと思います。","respondent":"山崎商業・ものづくり課長、高山生活衛生課長","answer":"地域サポーターというのは、これは商店街をリタイアされたＯＢの方だとか、こちらのほうは、商店街の経営だとか運営に知見がある方々を区商連のほうで登録して、日々の商店街活動の補助というようなことで、こちら。私からはマイクロチップの利点と課題ということについてお答えします。利点としましては、全世界において、唯一無二の１５桁の固有の番号ということで、そういった意味で固体識別においては大変有効な手段であると考えております。","voiceIndex":410,"id":"exchange-179"},{"speaker":"渡辺委員","kind":"意見","question":"動物の愛護のところ、まず今のように、制度もそうですし、効果的なところを知ってもらうという作業をぜひ応援したいと思いますし、信頼あるところがやらないとだめだと思うのです。ペットショップ等が乱立している中で、やはり信頼ある行政なり獣医師会とか、そういうところと連携をとって進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":413,"id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":115849,"voices":414}}]);
